from collections import Counter

FACES = {"T": 10, "J": 11, "Q": 12, "K": 13, "A": 14}
SUITS = "CDHS"
RANK_NAMES = {
    9: "straight flush", 8: "four of a kind", 7: "full house",
    6: "flush", 5: "straight", 4: "three of a kind",
    3: "two pair", 2: "one pair", 1: "high card",
}


def parse_card(text):
    text = text.strip().upper()
    if len(text) < 2:
        raise ValueError("card too short: " + text)
    suit = text[-1]
    if suit not in SUITS:
        raise ValueError("unknown suit: " + suit)
    face = text[:-1]
    if face in FACES:
        value = FACES[face]
    elif face.isdigit():
        value = int(face)
    else:
        raise ValueError("unknown value: " + face)
    if value < 2 or value > 14:
        raise ValueError("value out of range: " + face)
    return value, suit


def parse_hand(text):
    return [parse_card(part) for part in text.split()]


def validate_hand(hand):
    if len(hand) != 5:
        raise ValueError("a hand must hold exactly five cards")
    seen = set()
    i = 0
    while i < len(hand):
        card = hand[i]
        if len(card) != 2:
            raise ValueError("each card must be a (value, suit) pair")
        if card in seen:
            raise ValueError("duplicate card in hand")
        seen.add(card)
        i += 1


def is_flush(hand):
    i = 1
    while i < len(hand):
        if hand[i][1] != hand[0][1]:
            return False
        i += 1
    return True


def is_straight(values):
    ordered = sorted(values)
    i = 1
    while i < len(ordered):
        if ordered[i] != ordered[i - 1] + 1:
            return False
        i += 1
    return True


def evaluate(hand):
    validate_hand(hand)
    values = [value for value, _suit in hand]
    flush = is_flush(hand)
    straight = is_straight(values)
    if flush and straight:
        return 9
    counts = sorted(Counter(values).values(), reverse=True)
    if counts[0] == 4:
        return 8
    elif counts[0] == 3 and counts[1] == 2:
        return 7
    elif flush:
        return 6
    elif straight:
        return 5
    elif counts[0] == 3:
        return 4
    elif counts[0] == 2 and counts[1] == 2:
        return 3
    elif counts[0] == 2:
        return 2
    return 1


def report(texts):
    best_text = None
    best_rank = 0
    for text in texts:
        rank = evaluate(parse_hand(text))
        print("{0:<16} {1}  ({2})".format(text, rank, RANK_NAMES[rank]))
        if rank > best_rank:
            best_rank = rank
            best_text = text
    print("strongest:", best_text, "->", RANK_NAMES[best_rank])


report([
    "2H 3H 4H 5H 6H",
    "9C 9D 9S 9H 2C",
    "KD KS KH 4C 4D",
    "AS QS 8S 5S 3S",
    "7C 8D 9H TS JC",
    "JC JD 3S 3H 8C",
    "AC KD 9S 6H 3C",
])

