import sys


def _pin(pins):
    if pins == 10:
        return "X"
    elif pins == 0:
        return "-"
    return str(pins)


def _validate(rolls):
    i = 0
    while i < len(rolls):
        pins = rolls[i]
        if pins < 0:
            raise ValueError("a roll cannot knock down a negative number of pins")
        elif pins > 10:
            raise ValueError("a roll cannot knock down more than ten pins")
        i += 1


def frame_scores(rolls):
    _validate(rolls)
    scores = []
    i = 0
    frame = 0
    while frame < 10:
        if i >= len(rolls):
            raise ValueError("the game has fewer than ten frames")
        first = rolls[i]
        if first == 10:
            if i + 2 >= len(rolls):
                raise ValueError("a strike needs two following rolls")
            elif frame == 9 and rolls[i + 1] != 10 and rolls[i + 1] + rolls[i + 2] > 10:
                raise ValueError("the bonus rolls knock down more than ten pins")
            scores.append(10 + rolls[i + 1] + rolls[i + 2])
            i += 1
            if frame == 9:
                i += 2
        else:
            if i + 1 >= len(rolls):
                raise ValueError("frame %d is missing its second roll" % (frame + 1))
            second = rolls[i + 1]
            if first + second > 10:
                raise ValueError("frame %d knocks down more than ten pins" % (frame + 1))
            elif first + second == 10:
                if i + 2 >= len(rolls):
                    raise ValueError("a spare needs one following roll")
                scores.append(10 + rolls[i + 2])
                i += 1
            else:
                scores.append(first + second)
            i += 2
        frame += 1
    if i < len(rolls):
        raise ValueError("the game has more rolls than ten frames allow")
    return scores


def score(rolls):
    return sum(frame_scores(rolls))


def format_scorecard(rolls):
    totals = frame_scores(rolls)
    marks = []
    i = 0
    while len(marks) < 10:
        first = rolls[i]
        if first == 10:
            marks.append("X")
            i += 1
        elif first + rolls[i + 1] == 10:
            marks.append(_pin(first) + "/")
            i += 2
        else:
            marks.append(_pin(first) + _pin(rolls[i + 1]))
            i += 2
    if i < len(rolls):
        marks[-1] += "".join(_pin(pins) for pins in rolls[i:])
    lines = []
    running = 0
    for number, mark in enumerate(marks, 1):
        running += totals[number - 1]
        lines.append("frame %2d  %-5s %3d" % (number, mark, running))
    return "\n".join(lines)


def main():
    text = " ".join(sys.argv[1:])
    if not text.strip():
        text = sys.stdin.read()
    rolls = [int(token) for token in text.replace(",", " ").split()]
    try:
        print(format_scorecard(rolls))
    except ValueError as error:
        print("invalid game: %s" % error)
        return 1
    print("total: %d" % score(rolls))
    return 0


sys.exit(main())

