import sys

DENOMINATIONS = (100, 50, 20, 10, 5, 1)


def withdraw(amount):
    """Return the bill counts for `amount`, or [] if it cannot be dispensed."""
    if amount < 0:
        return []
    counts = [0] * len(DENOMINATIONS)
    remaining = amount
    for index, bill in enumerate(DENOMINATIONS):
        if remaining == 0:
            break
        while remaining >= bill:
            remaining -= bill
            counts[index] += 1
    if remaining != 0:
        return []
    return counts


def parse_amount(text):
    """Turn user input such as '$1,120' into an integer, or None if unusable."""
    cleaned = text.strip().lstrip("$").replace(",", "")
    if not cleaned:
        return None
    if not cleaned.isdigit() and not cleaned.startswith("-"):
        return None
    try:
        return int(cleaned)
    except ValueError:
        return None


def format_receipt(amount, counts):
    """Describe the dispensed bills for a completed or refused request."""
    if not counts:
        return "$%d: cannot be dispensed" % amount
    parts = []
    for bill, count in zip(DENOMINATIONS, counts):
        if count > 0:
            parts.append("%d x $%d" % (count, bill))
    if not parts:
        return "$%d: no bills needed" % amount
    return "$%d: %s" % (amount, ", ".join(parts))


def main():
    requests = sys.argv[1:]
    if not requests:
        requests = sys.stdin.read().split()
    status = 0
    for text in requests:
        amount = parse_amount(text)
        if amount is None:
            print("%r: not a valid amount" % text)
            status = 1
            continue
        counts = withdraw(amount)
        if not counts:
            status = 1
        print(format_receipt(amount, counts))
    return status


sys.exit(main())

