PRICE = 75
COIN_VALUES = (25, 10, 5)


def is_valid_coin(value):
    return value in COIN_VALUES


def make_change(amount):
    if amount < 0:
        raise ValueError("cannot return a negative amount")
    if amount % 5:
        raise ValueError("amount is not payable with nickels, dimes and quarters")
    coins = []
    for value in COIN_VALUES:
        while amount >= value:
            coins.append(value)
            amount -= value
    return coins


def vend(coins):
    if not isinstance(coins, list):
        raise TypeError("coins must be a list of integers")
    total = 0
    for coin in coins:
        if not isinstance(coin, int):
            raise TypeError("coin values must be integers")
        elif not is_valid_coin(coin):
            continue
        total += coin
        if total >= PRICE:
            break
    if total < PRICE:
        return False, make_change(total)
    return True, make_change(total - PRICE)


def format_report(coins, result):
    purchased, change = result
    inserted = ", ".join(str(coin) for coin in coins)
    if not inserted:
        inserted = "nothing"
    if purchased and change:
        outcome = "item dispensed, change " + ", ".join(str(coin) for coin in change)
    elif purchased:
        outcome = "item dispensed, exact payment"
    elif change:
        outcome = "no sale, refund " + ", ".join(str(coin) for coin in change)
    else:
        outcome = "no sale, nothing to refund"
    return "inserted [" + inserted + "] -> " + outcome


def main():
    sessions = [
        [25, 25, 25],
        [25, 10, 10, 25, 10],
        [5, 3, 10, 25, 25, 25, 25],
        [10, 10, 10],
        [1, 2, 7],
    ]
    sold = 0
    refunded = 0
    for coins in sessions:
        result = vend(coins)
        print(format_report(coins, result))
        purchased, change = result
        if purchased:
            sold += 1
        elif change:
            refunded += sum(change)
    print("items sold: %d, cents refunded: %d" % (sold, refunded))


main()

