import sys


def validate_pattern(pattern):
    """Reject patterns whose '*' quantifier has nothing to repeat."""
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    index = 0
    while index < len(pattern):
        if pattern[index] == "*" and index == 0:
            raise ValueError("pattern may not start with '*'")
        elif pattern[index] == "*" and pattern[index - 1] == "*":
            raise ValueError("'*' may not follow another '*'")
        index += 1
    return pattern


def match(pattern):
    """Return a predicate testing whether a target string matches `pattern`."""
    validate_pattern(pattern)

    def test(target):
        if not isinstance(target, str):
            raise TypeError("target must be a string")
        cache = {}

        def walk(pi, ti):
            key = (pi, ti)
            if key in cache:
                return cache[key]
            if pi == len(pattern):
                result = ti == len(target)
            else:
                starred = pi + 1 < len(pattern) and pattern[pi + 1] == "*"
                consumes = False
                if ti < len(target):
                    if pattern[pi] == ".":
                        consumes = True
                    elif pattern[pi] == target[ti]:
                        consumes = True
                if starred:
                    result = walk(pi + 2, ti)
                    if not result and consumes:
                        result = walk(pi, ti + 1)
                elif consumes:
                    result = walk(pi + 1, ti + 1)
                else:
                    result = False
            cache[key] = result
            return result

        return walk(0, 0)

    return test


def report(pattern, targets):
    """Describe the verdict for every target, plus the first accepted one."""
    accepts = match(pattern)
    lines = []
    winner = None
    for target in targets:
        if accepts(target):
            lines.append("{0!r:<14} matches".format(target))
            if winner is None:
                winner = target
        else:
            lines.append("{0!r:<14} no match".format(target))
    if winner is None:
        lines.append("first match: none")
    else:
        lines.append("first match: {0!r}".format(winner))
    return "\n".join(lines)


def main(argv):
    if len(argv) < 3:
        print("usage: {0} PATTERN TARGET [TARGET ...]".format(argv[0]))
        return 1
    try:
        text = report(argv[1], argv[2:])
    except (TypeError, ValueError) as exc:
        print("error: {0}".format(exc))
        return 2
    print("pattern: {0!r}".format(argv[1]))
    print(text)
    return 0


sys.exit(main(sys.argv))

