import sys

SPECIALS = "!@#$%^&*()-_=+[]{};:'\",.<>/?\\|`~"


def classify(ch):
    """Return the composition category a single character belongs to."""
    if ch.isupper():
        return "upper"
    elif ch.islower():
        return "lower"
    elif ch.isdigit():
        return "digit"
    elif ch in SPECIALS:
        return "special"
    return "other"


def scan(password):
    """Walk every character and record which categories occur."""
    flags = {"upper": False, "lower": False, "digit": False, "special": False}
    index = 0
    while index < len(password):
        kind = classify(password[index])
        if kind in flags:
            flags[kind] = True
        index += 1
    return flags


def analyze(password):
    """Score a password from 0 to 7 based on composition and length."""
    if not isinstance(password, str):
        raise TypeError("password must be a string")
    flags = scan(password)
    length = len(password)
    variety = sum(1 for used in flags.values() if used)
    score = variety
    if variety >= 3:
        score += 1
    if length >= 8:
        score += 1
    if length > 12:
        score += 1
    if password.isalpha():
        score -= 1
    elif password.isdigit():
        score -= 1
    if score < 0:
        return 0
    elif score > 7:
        return 7
    return score


def label(score):
    """Human readable verdict for a score produced by analyze()."""
    if score >= 7:
        return "excellent"
    elif score >= 5:
        return "strong"
    elif score >= 3:
        return "moderate"
    elif score >= 1:
        return "weak"
    return "unusable"


def main(argv):
    candidates = argv[1:]
    if not candidates:
        print("usage: %s PASSWORD [PASSWORD ...]" % argv[0])
        return 1
    position = 0
    while position < len(candidates):
        candidate = candidates[position]
        score = analyze(candidate)
        print("%d: length=%d score=%d verdict=%s"
              % (position + 1, len(candidate), score, label(score)))
        position += 1
    return 0


sys.exit(main(sys.argv))

