DIRECTIONS = ["N", "E", "S", "W"]
FORWARD = "F"
LEFT = "L"
RIGHT = "R"
WAIT = "W"


def parse_instructions(text):
    """Turn a raw command string into a list of single-character commands."""
    commands = []
    for character in text:
        if character.isspace():
            continue
        commands.append(character.upper())
    return commands


def turn(direction, offset):
    return DIRECTIONS[(DIRECTIONS.index(direction) + offset) % len(DIRECTIONS)]


def step(x, y, direction):
    if direction == "N":
        y += 1
    elif direction == "S":
        y -= 1
    elif direction == "E":
        x += 1
    else:
        x -= 1
    return x, y


def simulate(instructions):
    """Run the commands, returning position, heading, wait count and commands used."""
    x, y, direction, waits, index = 0, 0, "N", 0, 0
    while index < len(instructions):
        command = instructions[index]
        if command == FORWARD:
            x, y = step(x, y, direction)
        elif command == LEFT:
            direction = turn(direction, -1)
        elif command == RIGHT:
            direction = turn(direction, 1)
        elif command == WAIT:
            waits += 1
        else:
            break
        index += 1
    return x, y, direction, waits, index


def navigate(instructions):
    state = simulate(instructions)
    return (state[0], state[1])


def format_position(x, y):
    parts = []
    if y > 0:
        parts.append("%d north" % y)
    elif y < 0:
        parts.append("%d south" % -y)
    if x > 0:
        parts.append("%d east" % x)
    elif x < 0:
        parts.append("%d west" % -x)
    if not parts:
        return "at the origin"
    return "at " + " and ".join(parts)


def describe(instructions):
    x, y, direction, waits, consumed = simulate(instructions)
    lines = ["%s, facing %s" % (format_position(x, y), direction)]
    if waits == 1:
        lines.append("waited once")
    elif waits > 1:
        lines.append("waited %d times" % waits)
    if consumed < len(instructions):
        lines.append("aborted on unknown command %r at index %d"
                     % (instructions[consumed], consumed))
    return lines


def main():
    for text in ["FFRFF", "F F L F W W F", "FFRFQFF", "LLFF"]:
        commands = parse_instructions(text)
        print("%-16s -> %s" % (text, navigate(commands)))
        for line in describe(commands):
            print("    " + line)


