def validate(text):
    if not isinstance(text, str):
        raise TypeError("compress expects a string")
    for ch in text:
        if not ch.isalpha():
            raise ValueError("only alphabetical characters are allowed: %r" % ch)
    return text


def compress(text):
    validate(text)
    result = []
    count = 0
    previous = ""
    index = 0
    while index < len(text):
        char = text[index]
        if char == previous:
            count += 1
        else:
            if count > 1:
                result.append(str(count))
                result.append(previous)
            elif count == 1:
                result.append(previous)
            previous = char
            count = 1
        index += 1
    if count > 1:
        result.append(str(count))
        result.append(previous)
    elif count == 1:
        result.append(previous)
    return "".join(result)


def decompress(code):
    result = []
    digits = ""
    for ch in code:
        if ch.isdigit():
            digits += ch
        elif digits:
            result.append(ch * int(digits))
            digits = ""
        else:
            result.append(ch)
    if digits:
        raise ValueError("trailing count without a character: %s" % digits)
    return "".join(result)


def ratio(text, code):
    if not text:
        return 1.0
    return len(code) / len(text)


def report(text):
    code = compress(text)
    saving = ratio(text, code)
    if decompress(code) != text:
        status = "BROKEN"
    elif saving < 1.0:
        status = "smaller"
    elif saving > 1.0:
        status = "larger"
    else:
        status = "same size"
    return "%-14s -> %-14s (%.2f, %s)" % (text or "<empty>", code or "<empty>", saving, status)


def main():
    samples = ["", "a", "aaa", "aabbbc", "abcd", "wwwwwwwwwwwwbbb", "MississippI"]
    for sample in samples:
        print(report(sample))


