BRACKETS = (
    (250000.0, 0.40),
    (150000.0, 0.35),
    (100000.0, 0.30),
    (75000.0, 0.25),
    (50000.0, 0.20),
    (25000.0, 0.15),
    (10000.0, 0.10),
)


def parse_income(text):
    cleaned = text.strip().replace(",", "")
    if cleaned.startswith("$"):
        cleaned = cleaned[1:]
    if not cleaned:
        raise ValueError("no income value given")
    return float(cleaned)


def _validated(income):
    if not isinstance(income, (int, float)):
        raise TypeError("income must be a number")
    if income < 0:
        raise ValueError("income must not be negative")
    return float(income)


def breakdown(income):
    remaining = _validated(income)
    rows = []
    index = 0
    while index < len(BRACKETS):
        threshold, rate = BRACKETS[index]
        if remaining > threshold:
            slice_amount = remaining - threshold
            rows.append((threshold, rate, slice_amount, round(slice_amount * rate, 2)))
            remaining = threshold
        index += 1
    return rows


def calculate(income):
    remaining = _validated(income)
    total = 0.0
    index = 0
    while index < len(BRACKETS):
        threshold, rate = BRACKETS[index]
        if remaining > threshold:
            total += (remaining - threshold) * rate
            remaining = threshold
        index += 1
    return round(total, 2)


def format_report(income):
    amount = _validated(income)
    rows = breakdown(amount)
    lines = ["Income: {:,.2f}".format(amount)]
    if not rows:
        lines.append("  no tax due (income is within the untaxed band)")
    for threshold, rate, slice_amount, tax in rows:
        lines.append(
            "  above {:>10,.0f} @ {:>4.0%}: {:>12,.2f} -> {:>10,.2f}".format(
                threshold, rate, slice_amount, tax
            )
        )
    total = calculate(amount)
    lines.append("Total tax: {:,.2f}".format(total))
    if amount > 0:
        lines.append("Effective rate: {:.2%}".format(total / amount))
    return "\n".join(lines)


def main():
    samples = ["9,500", "$42000.50", "137500", "310000", "not-a-number", "-5"]
    for sample in samples:
        try:
            income = parse_income(sample)
        except ValueError:
            print("Skipping {!r}: unreadable amount".format(sample))
            continue
        if income < 0:
            print("Skipping {!r}: negative amount".format(sample))
            continue
        print(format_report(income))
        print()


main()

