VALID_CELLS = ("", "ex", "oh")

DRAW = "draw"
PENDING = "pending"


def validate_board(board):
    if not isinstance(board, list):
        raise TypeError("board must be a list of three lists")
    elif len(board) != 3:
        raise ValueError("board must contain exactly three rows")
    row_index = 0
    while row_index < 3:
        row = board[row_index]
        if not isinstance(row, list):
            raise TypeError("each row must be a list")
        elif len(row) != 3:
            raise ValueError("each row must contain exactly three cells")
        for cell in row:
            if cell not in VALID_CELLS:
                raise ValueError("unexpected cell value: %r" % (cell,))
        row_index += 1


def line_winner(first, second, third):
    if first == "":
        return None
    elif first == second and second == third:
        return first
    return None


def row_winner(board):
    for row in board:
        winner = line_winner(row[0], row[1], row[2])
        if winner is not None:
            return winner
    return None


def column_winner(board):
    column = 0
    while column < 3:
        winner = line_winner(board[0][column], board[1][column], board[2][column])
        if winner is not None:
            return winner
        column += 1
    return None


def diagonal_winner(board):
    winner = line_winner(board[0][0], board[1][1], board[2][2])
    if winner is None:
        winner = line_winner(board[0][2], board[1][1], board[2][0])
    return winner


def has_empty(board):
    for row in board:
        for cell in row:
            if cell == "":
                return True
    return False


