import sys


def _validate(current, total):
    """Return an error message for impossible page requests, else None."""
    if total < 1:
        return "error: total pages must be at least 1, got %d" % total
    if current < 1 or current > total:
        return "error: page %d is outside 1..%d" % (current, total)
    return None


def paginate(current, total):
    """Return the list of page links to display, or an error string."""
    error = _validate(current, total)
    if error is not None:
        return error
    if total <= 7:
        return [str(page) for page in range(1, total + 1)]
    if current <= 4:
        head = [str(page) for page in range(1, 6)]
        return head + ["...", str(total)]
    elif current >= total - 3:
        tail = [str(page) for page in range(total - 4, total + 1)]
        return ["1", "..."] + tail
    else:
        middle = [str(page) for page in range(current - 1, current + 2)]
        return ["1", "..."] + middle + ["...", str(total)]


def render(links, current):
    """Format the links for display, highlighting the current page."""
    parts = []
    for link in links:
        if link == "...":
            parts.append("\u2026")
        elif link == str(current):
            parts.append("[" + link + "]")
        else:
            parts.append(link)
    return " ".join(parts)


def report(current, total):
    """Build one line of output for a single pagination request."""
    links = paginate(current, total)
    if isinstance(links, str):
        return links
    return render(links, current)


def main(argv):
    if len(argv) == 3:
        try:
            current = int(argv[1])
            total = int(argv[2])
        except ValueError:
            print("error: page numbers must be integers")
            return 2
        line = report(current, total)
        print(line)
        if line.startswith("error:"):
            return 1
        return 0
    elif len(argv) == 1:
        while True:
            try:
                raw = input("current total> ")
            except EOFError:
                return 0
            fields = raw.split()
            if not fields:
                return 0
            elif len(fields) != 2:
                print("error: expected two numbers")
                continue
            try:
                print(report(int(fields[0]), int(fields[1])))
            except ValueError:
                print("error: page numbers must be integers")
    print("usage: paginate.py [CURRENT TOTAL]")
    return 2


sys.exit(main(sys.argv))

