    "........",
    "PPP.PPPP",
    "RNBQKBNR",
]


def parse_square(text):
    if len(text) != 2:
        raise ValueError("a square is written with two characters: " + text)
    file_char, rank_char = text[0], text[1]
    if file_char not in FILES:
        raise ValueError("unknown file: " + text)
    elif rank_char not in "12345678":
        raise ValueError("unknown rank: " + text)
    return FILES.index(file_char), int(rank_char)


def parse_move(text):
    parts = text.replace("-", " ").split()
    if len(parts) != 2:
        raise ValueError("a move names exactly two squares: " + text)
    return parse_square(parts[0]), parse_square(parts[1])


def load_board(rows):
    if len(rows) != 8:
        raise ValueError("a board needs 8 rows")
    board = {}
    rank = 8
    index = 0
    while index < 8:
        row = rows[index]
        if len(row) != 8:
            raise ValueError("a row needs 8 squares: " + row)
        file = 0
        while file < 8:
            board[(file, rank)] = row[file]
            file += 1
        rank -= 1
        index += 1
    return board


