SEPARATORS = ",:"
WHITESPACE = " \t\n\r"


def _read_string(text, i):
    start = i
    i += 1
    while i < len(text):
        if text[i] == '"':
            return text[start:i + 1], i + 1
        i += 1
    raise ValueError("unterminated string literal at index %d" % start)


def _read_number(text, i):
    start = i
    if text[i] == "-":
        i += 1
    while i < len(text) and text[i] in "0123456789.":
        i += 1
    token = text[start:i]
    if not any(ch.isdigit() for ch in token):
        raise ValueError("malformed number at index %d" % start)
    return token, i


def tokenize(text):
    tokens = []
    i = 0
    while i < len(text):
        c = text[i]
        if c in STRUCTURAL:
            tokens.append(c)
            i += 1
        elif c == '"':
            token, i = _read_string(text, i)
            tokens.append(token)
        elif c.isdigit() or c == "-":
            token, i = _read_number(text, i)
            tokens.append(token)
        elif c in WHITESPACE:
            i += 1
        elif c in SEPARATORS:
            tokens.append(c)
            i += 1
        else:
            raise ValueError("unexpected character %r at index %d" % (c, i))
    return tokens


def check_balance(tokens):
    closers = {"}": "{", "]": "["}
    stack = []
    for token in tokens:
        if token == "{" or token == "[":
            stack.append(token)
        elif token in closers:
            if not stack or stack.pop() != closers[token]:
                return False
    return not stack


