GREEN_TIME = 4
YELLOW_TIME = 2
RED_TIME = 3
EMERGENCY_INTERVAL = 11


def validate_cars(cars):
    """Reject anything that is not a sensible queue length."""
    if not isinstance(cars, int) or isinstance(cars, bool):
        raise TypeError("cars must be an integer")
    if cars < 0:
        raise ValueError("cars must not be negative")
    return cars


def next_color(color):
    """Green -> yellow -> red -> green."""
    if color == "green":
        return "yellow"
    elif color == "yellow":
        return "red"
    elif color == "red":
        return "green"
    raise ValueError("unknown light color: " + repr(color))


def phase_duration(color):
    if color == "green":
        return GREEN_TIME
    elif color == "yellow":
        return YELLOW_TIME
    return RED_TIME


def cars_passing(color, queue):
    """How many cars leave the queue during one time step."""
    if color == "green":
        return min(2, queue)
    elif color == "yellow":
        if queue < 2:
            return min(1, queue)
        return 0
    return 0


def emergency_active(step):
    return step % EMERGENCY_INTERVAL == 0


def simulate(cars):
    """Return the number of time steps needed to clear the queue."""
    queue = validate_cars(cars)
    color = "green"
    timer = phase_duration(color)
    steps = 0
    while queue > 0:
        steps += 1
        if emergency_active(steps):
            color = "green"
            timer = 1
        queue -= cars_passing(color, queue)
        timer -= 1
        if timer == 0:
            color = next_color(color)
            timer = phase_duration(color)
    return steps


def report(queue_sizes):
    """Print the clearing time and throughput for each queue length."""
    print("cars  steps  cars/step")
    for cars in queue_sizes:
        steps = simulate(cars)
        if steps > 0:
            print(f"{cars:4d}  {steps:5d}  {cars / steps:9.2f}")
        else:
