from collections import deque


def validate_requests(requests):
    """Turn the raw request list into a clean list of floor integers."""
    cleaned = []
    for floor in requests:
        if isinstance(floor, bool) or not isinstance(floor, int):
            raise TypeError("floor requests must be integers, got %r" % (floor,))
        cleaned.append(floor)
    return cleaned


def _service_floor(floor, pending, visited):
    """Open the doors at `floor`, dropping every pending request for it."""
    serviced = False
    while floor in pending:
        pending.remove(floor)
        serviced = True
    if serviced:
        visited.append(floor)
    return serviced


def route(requests):
    """Run the elevator over `requests` and return every floor it stopped at."""
    pending = deque(validate_requests(requests))
    visited = []
    current = 0
    while pending:
        target = pending.popleft()
        if target > current:
            while current < target:
                current += 1
                if current != target:
                    _service_floor(current, pending, visited)
        elif target < current:
            while current > target:
                current -= 1
                if current != target:
                    _service_floor(current, pending, visited)
        if not _service_floor(target, pending, visited):
            visited.append(target)
    return visited


def travel_distance(visited):
    """Total number of floors travelled starting from floor zero."""
    distance = 0
    previous = 0
    for floor in visited:
        distance += abs(floor - previous)
        previous = floor
    return distance


def describe(requests):
    """Build a one-line report for a batch of requests."""
    visited = route(requests)
    if not visited:
        return "requests %s -> elevator stays idle at floor 0" % (list(requests),)
    highest = visited[0]
    lowest = visited[0]
    for floor in visited[1:]:
        if floor > highest:
            highest = floor
        elif floor < lowest:
            lowest = floor
    return "requests %s -> stops %s (%d floors travelled, range %d..%d)" % (
        list(requests), visited, travel_distance(visited), lowest, highest)


def main():
    batches = [[], [0], [3, 1, 5], [5, 2, 2, -1], [-2, -2, 4, 1]]
    for batch in batches:
        print(describe(batch))


main()

