import sys


def split_row(line):
    """Split a raw table line on pipes and strip the surrounding blanks."""
    cells = [cell.strip() for cell in line.split('|')]
    while len(cells) > 1 and cells[-1] == '':
        cells.pop()
    return cells


def is_separator(cells):
    """True when every cell of the row is made of hyphens only."""
    if not cells:
        return False
    for text in cells:
        if not text:
            return False
        if text.strip('-'):
            return False
    return True


def column_widths(rows):
    """Maximum text width of every column, separator rows excluded."""
    widths = []
    for cells in rows:
        while len(widths) < len(cells):
            widths.append(0)
        if is_separator(cells):
            continue
        for index, text in enumerate(cells):
            if len(text) > widths[index]:
                widths[index] = len(text)
    return widths


def trim_blank_lines(lines):
    """Drop the empty lines that surround the table."""
    kept = list(lines)
    while kept and not kept[0].strip():
        kept.pop(0)
    while kept and not kept[-1].strip():
        kept.pop()
    return kept


def format(table):
    """Align the columns of an unaligned pipe-separated text table."""
    rows = [split_row(line) for line in trim_blank_lines(table)]
    widths = column_widths(rows)
    output = []
    for cells in rows:
        separator = is_separator(cells)
        parts = []
        for index, text in enumerate(cells):
            if separator:
                body = '-' * widths[index]
            else:
                body = text.ljust(widths[index])
            if index == len(cells) - 1:
                parts.append(body)
            elif separator:
                parts.append(body + '-|-')
            else:
                parts.append(body + ' | ')
        output.append(''.join(parts).rstrip())
    return '\n'.join(output)


def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        print('no table given on standard input', file=sys.stderr)
        return 1
    print(format(lines))
    return 0


sys.exit(main())

