import sys

DEFAULT_LIMIT = 20


def validate(words, limit):
    """Reject inputs that cannot be wrapped at all."""
    if not isinstance(words, list):
        raise TypeError("words must be a list of strings")
    if not isinstance(limit, int):
        raise TypeError("limit must be an integer")
    if limit < 1:
        raise ValueError("limit must be at least 1")
    for word in words:
        if not isinstance(word, str):
            raise TypeError("every word must be a string")


def hyphenate(word, limit):
    """Split an over-long word into chunks of at most `limit` characters."""
    if limit < 2:
        return [word]
    pieces = []
    rest = word
    while len(rest) > limit:
        pieces.append(rest[:limit - 1] + "-")
        rest = rest[limit - 1:]
    pieces.append(rest)
    return pieces


def wrap(words, limit):
    validate(words, limit)
    lines = []
    line = ""
    for word in words:
        if line:
            candidate = line + " " + word
        else:
            candidate = word
        if len(candidate) <= limit:
            line = candidate
            continue
        if line:
            lines.append(line)
        pieces = hyphenate(word, limit)
        lines.extend(pieces[:-1])
        line = pieces[-1]
    if line:
        lines.append(line)
    return "\n".join(lines)


def report(text, limit):
    if not text:
        return "0 line(s), longest 0/%d (ok)" % limit
    lines = text.split("\n")
    longest = max(len(line) for line in lines)
    status = "ok"
    if longest > limit:
        status = "overflow"
    return "%d line(s), longest %d/%d (%s)" % (len(lines), longest, limit, status)


def parse_args(argv):
    limit = DEFAULT_LIMIT
    words = []
    index = 0
    while index < len(argv):
        token = argv[index]
        if token == "-w":
            index += 1
            if index >= len(argv):
                raise SystemExit("-w requires a number")
            limit = int(argv[index])
        elif token.startswith("-"):
            raise SystemExit("unknown option: " + token)
        else:
            words.extend(token.split())
        index += 1
    if not words:
        words = sys.stdin.read().split()
    return limit, words


def main():
    limit, words = parse_args(sys.argv[1:])
    text = wrap(words, limit)
    print(text)
    print("-- " + report(text, limit))


main()

