BASE_RATE = 500
YOUNG_AGE = 25
SENIOR_AGE = 65
ACCIDENT_LIMIT = 2


def validate_profile(profile):
    if len(profile) != 3:
        raise ValueError("a profile needs age, accidents and car type")
    age, accidents, car_type = profile
    if not isinstance(age, int) or not isinstance(accidents, int):
        raise TypeError("age and accident count must be integers")
    if age < 0:
        raise ValueError("age cannot be negative")
    elif accidents < 0:
        raise ValueError("accident count cannot be negative")
    if not isinstance(car_type, str):
        raise TypeError("car type must be a string")
    return age, accidents, car_type.strip().lower()


def age_surcharge(age):
    if age < YOUNG_AGE:
        return 200
    elif age > SENIOR_AGE:
        return 100
    return 0


def accident_surcharge(accidents):
    if accidents == 1:
        return 100
    elif accidents == 2:
        return 250
    return 0


def car_adjustment(car_type):
    if car_type == "sports":
        return 300
    elif car_type == "minivan":
        return -50
    return 0


def quote(age, accidents, car_type):
    if accidents > ACCIDENT_LIMIT:
        return 0
    total = BASE_RATE + age_surcharge(age) + accident_surcharge(accidents)
    return total + car_adjustment(car_type)


def premiums(profiles):
    results = []
    index = 0
    while index < len(profiles):
        age, accidents, car_type = validate_profile(profiles[index])
        if age == 0:
            break
        results.append(quote(age, accidents, car_type))
        index += 1
    return results


def format_report(profiles, amounts):
    lines = []
    position = 0
    while position < len(amounts):
        age, accidents, car_type = validate_profile(profiles[position])
        if amounts[position] == 0:
            verdict = "coverage denied"
        else:
            verdict = "premium ${}".format(amounts[position])
        lines.append(
            "age {:>3}  accidents {}  {:<8} -> {}".format(
                age, accidents, car_type, verdict
            )
        )
        position += 1
    return "\n".join(lines)


def main():
    profiles = [
        (20, 1, "sports"),
        (70, 3, "sedan"),
        (40, 2, "minivan"),
        (0, 0, "none"),
    ]
    amounts = premiums(profiles)
    print(amounts)
    print(format_report(profiles, amounts))
    if amounts:
        print("average ${:.2f}".format(sum(amounts) / len(amounts)))


main()

