    elif weight <= 10:
        return 3
    return 10


def distance_fee(distance):
    """Return the surcharge that applies to the distance travelled."""
    if distance > 3000:
        return 15
    elif distance > 1000:
        return 5
    return 0


def check_package(package):
    """Raise a descriptive error if a package record is malformed."""
    if not isinstance(package, tuple):
        raise TypeError("each package must be a tuple")
    elif len(package) != 4:
        raise ValueError("each package needs weight, distance, priority, international")
    weight, distance, priority, international = package
    if not isinstance(weight, (int, float)):
        raise TypeError("weight must be numeric")
    elif not isinstance(distance, (int, float)):
        raise TypeError("distance must be numeric")
    elif distance < 0:
        raise ValueError("distance cannot be negative")
    return weight, distance, bool(priority), bool(international)


def package_cost(weight, distance, priority, international):
    """Compute the freight cost of a single package."""
    cost = 5 + weight_fee(weight) + distance_fee(distance)
    if international:
        cost += 50
    if priority:
        cost *= 2
    return cost


