SENTINEL = 999
LEVELS = ('basic', 'silver', 'gold')


def normalize_level(level):
    """Return the membership level in canonical lower-case form."""
    if not isinstance(level, str):
        raise TypeError('membership level must be a string')
    cleaned = level.strip().lower()
    if cleaned not in LEVELS:
        raise ValueError('unknown membership level: ' + repr(level))
    return cleaned


def half_rate(rate):
    """Half of a room rate, staying with whole numbers when possible."""
    if rate % 2 == 0:
        return rate // 2
    return rate / 2


def basic_fee(notice, rate):
    if notice < 2:
        return rate
    elif notice < 7:
        return half_rate(rate)
    elif notice < 30:
        return 20
    return 0


def silver_fee(notice, rate):
    if notice < 3:
        return half_rate(rate)
    return 0


def fee_for(notice, rate, level):
    """Cancellation fee for a single reservation."""
    if notice < 0:
        raise ValueError('days notice cannot be negative')
    if rate < 0:
        raise ValueError('room rate cannot be negative')
    member = normalize_level(level)
    if member == 'gold':
        return 0
    elif member == 'silver':
        return silver_fee(notice, rate)
    return basic_fee(notice, rate)


def penalty(reservations):
    """Fees for each reservation, stopping at a 999-day notice sentinel."""
    fees = []
    index = 0
    while index < len(reservations):
        notice, rate, level = reservations[index]
        if notice == SENTINEL:
            break
        fees.append(fee_for(notice, rate, level))
        index += 1
    return fees


def format_report(reservations, fees):
    lines = []
    index = 0
    while index < len(fees):
        notice, rate, level = reservations[index]
        fee = fees[index]
        if fee == 0:
            note = 'waived'
        elif fee == rate:
            note = 'full rate'
        else:
            note = 'reduced'
        lines.append('%4dd %-6s rate %5s -> fee %s (%s)'
                     % (notice, normalize_level(level), rate, fee, note))
        index += 1
    return lines


def main():
    bookings = [(1, 100, 'basic'), (2, 200, 'silver'), (5, 150, 'basic'),
                (10, 300, 'basic'), (40, 250, 'basic'), (1, 500, 'gold'),
                (999, 0, 'none'), (1, 999, 'basic')]
    fees = penalty(bookings)
    for line in format_report(bookings, fees):
        print(line)
    total = sum(fees)
    if total > 0:
        print('total charged:', total)
    else:
        print('no penalties charged')
    print('fees:', fees)


main()

