STATUSES = ('none', 'elite', 'crew')

MAX_WEIGHT = 70
FREE_LIMIT = 50
BASE_FEE = 30
HEAVY_FEE = 50
OVERSIZE_FEE = 75
SIZE_LIMIT = 62


def parse_bag(text):
    """Turn "weight,dimensions,status" into a bag tuple."""
    parts = text.split(',')
    if len(parts) != 3:
        raise ValueError('expected WEIGHT,DIMS,STATUS but got %r' % (text,))
    weight, dims, status = parts
    return int(weight), int(dims), status.strip().lower()


def validate_bag(bag):
    """Unpack one bag description, rejecting malformed entries."""
    if len(bag) != 3:
        raise ValueError('each bag needs weight, dimensions and status')
    weight, dims, status = bag
    if weight < 0:
        raise ValueError('weight cannot be negative')
    elif dims < 0:
        raise ValueError('dimensions cannot be negative')
    if status not in STATUSES:
        raise ValueError('unknown passenger status: %r' % (status,))
    return weight, dims, status


def weight_fee(weight, status, free_used):
    """Fee driven by weight alone; -1 marks a bag that may not be carried."""
    if weight > MAX_WEIGHT:
        return -1
    elif status == 'crew':
        return 0
    elif status == 'elite':
        if weight <= FREE_LIMIT and not free_used:
            return 0
        return BASE_FEE
    fee = BASE_FEE
    if weight > FREE_LIMIT:
        fee += HEAVY_FEE
    return fee


def baggage(bags):
    """Total fee per bag, stopping at the first bag with zero weight."""
    fees = []
    free_used = False
    index = 0
    while index < len(bags):
        weight, dims, status = validate_bag(bags[index])
        if weight == 0:
            break
        fee = weight_fee(weight, status, free_used)
        if fee < 0:
            fees.append(-1)
            index += 1
            continue
        elif dims > SIZE_LIMIT:
            fee += OVERSIZE_FEE
        if status == 'elite' and fee == 0:
            free_used = True
        fees.append(fee)
        index += 1
    return fees


def format_report(bags, fees):
    """Human readable summary lining bags up with their computed fees."""
    lines = []
    total = 0
    for position, fee in enumerate(fees):
        weight, dims, status = bags[position]
        if fee < 0:
            detail = 'refused (over %d lb)' % MAX_WEIGHT
        else:
            detail = '$%d' % fee
            total += fee
        lines.append('%d lb / %d in / %s: %s' % (weight, dims, status, detail))
    lines.append('total charged: $%d' % total)
    return '\n'.join(lines)


def main(argv):
    if len(argv) < 2:
        print('usage: %s WEIGHT,DIMS,STATUS ...' % argv[0])
        return 2
    bags = [parse_bag(item) for item in argv[1:]]
    fees = baggage(bags)
    print(fees)
    print(format_report(bags, fees))
    return 0


import sys

sys.exit(main(sys.argv))

