import sys


def validate_purchases(purchases):
    """Return the purchase list, raising if it is not a sequence of numbers."""
    if not isinstance(purchases, (list, tuple)):
        raise TypeError("purchases must be a list or tuple of amounts")
    for index, amount in enumerate(purchases):
        if isinstance(amount, bool):
            raise TypeError("transaction %d is not a number" % index)
        elif not isinstance(amount, (int, float)):
            raise TypeError("transaction %d is not a number" % index)
    return list(purchases)


def points_for(amount):
    """Points earned by a single non-negative transaction."""
    base = int(amount)
    if amount > 20:
        base *= 2
    bonus = 0
    if amount == 5.00:
        bonus = 2
    return base + bonus


def rewards(purchases):
    """Tally loyalty points, converting each 100 points into a free drink."""
    transactions = validate_purchases(purchases)
    drinks = 0
    points = 0
    for amount in transactions:
        if amount < 0:
            break
        points += points_for(amount)
        while points >= 100:
            points -= 100
            drinks += 1
    return (drinks, points)


def parse_amounts(tokens):
    """Turn command line style tokens into a list of transaction amounts."""
    amounts = []
    for token in tokens:
        cleaned = token.strip()
        if not cleaned:
            continue
        elif cleaned.startswith("$"):
            cleaned = cleaned[1:]
        try:
            amounts.append(float(cleaned))
        except ValueError:
            raise SystemExit("not a valid amount: %s" % token)
    return amounts


def format_report(drinks, points):
    """Human readable summary of a rewards result."""
    if drinks == 1:
        drink_text = "1 free drink"
    elif drinks == 0:
        drink_text = "no free drinks"
    else:
        drink_text = "%d free drinks" % drinks
    return "%s, %d points remaining" % (drink_text, points)


def main(argv):
    if len(argv) > 1:
        amounts = parse_amounts(argv[1:])
    else:
