def validate_reading(reading):
    """Check that a single reading is a 4-tuple of usable values."""
    if not isinstance(reading, tuple):
        raise TypeError("each reading must be a tuple")
    if len(reading) != 4:
        raise ValueError("each reading needs current, target, motion, windows")
    current, target, motion, windows = reading
    if not isinstance(current, (int, float)):
        raise TypeError("current temperature must be numeric")
    elif not isinstance(target, (int, float)):
        raise TypeError("target temperature must be numeric")
    if not isinstance(motion, bool):
        raise TypeError("motion flag must be a boolean")
    elif not isinstance(windows, bool):
        raise TypeError("windows flag must be a boolean")
    return current, target, motion, windows


def adjust_target(target, motion):
    """Occupied rooms keep their target, empty rooms are set back five degrees."""
    if motion:
        return target
    return target - 5


def decide_action(current, target, motion, windows):
    """Pick the action for one validated reading."""
    if windows:
        return "off"
    adjusted = adjust_target(target, motion)
    if current <= adjusted - 2:
        return "heat"
    elif current >= adjusted + 2:
        return "cool"
    return "standby"


def thermostat(readings):
    """Turn a list of sensor readings into a list of thermostat actions."""
    actions = []
    index = 0
    while index < len(readings):
        current, target, motion, windows = validate_reading(readings[index])
        if current == 0:
            break
        actions.append(decide_action(current, target, motion, windows))
        index += 1
    return actions


def summarize(actions):
    """Count how often each action was issued."""
    counts = {}
    for action in actions:
        if action in counts:
            counts[action] += 1
        else:
            counts[action] = 1
    return counts


def format_report(actions):
    """Render a short human readable report of the run."""
    if not actions:
        return "no actions issued"
    counts = summarize(actions)
    parts = []
    for action in sorted(counts):
        parts.append("%s x%d" % (action, counts[action]))
    return ", ".join(parts)


def main():
    readings = [(68, 72, True, False), (70, 72, False, False), (0, 0, False, False)]
    actions = thermostat(readings)
    print(actions)
    print(format_report(actions))
    remaining = len(readings) - len(actions)
    if remaining > 0:
        print("stopped early, %d reading(s) skipped" % remaining)


main()

