def _find_stop(assets):
    """Return the index of the 'stop' sentinel, or the list length if absent."""
    index = 0
    while index < len(assets) and str(assets[index][0]).lower() != "stop":
        index += 1
    return index


def _validate(entry):
    """Check a single (asset class, value, target) tuple."""
    if len(entry) != 3:
        raise ValueError("each entry needs an asset class, a value and a target")
    name, value, target = entry
    if not isinstance(name, str):
        raise TypeError("asset class must be a string")
    if not isinstance(value, (int, float)):
        raise TypeError("current value must be numeric")
    if value < 0:
        raise ValueError("current value cannot be negative")
    if not isinstance(target, (int, float)):
        raise TypeError("target percentage must be numeric")
    if target < 0 or target > 1:
        raise ValueError("target percentage must be a decimal between 0 and 1")
    return name.lower(), float(value), float(target)


def portfolio_total(assets):
    """Total value of every asset listed before the stop word."""
    stop = _find_stop(assets)
    total = 0.0
    for entry in assets[:stop]:
        total += _validate(entry)[1]
    return total


def rebalance(assets):
    """Dollar trades needed to bring each asset class back to its target."""
    stop = _find_stop(assets)
    total = portfolio_total(assets)
    trades = []
    for entry in assets[:stop]:
        name, value, target = _validate(entry)
        if total == 0:
            trades.append(0.0)
            continue
        current = value / total
        difference = abs(current - target)
        if name == "cash":
            action = 0.0
        elif difference < 0.05:
            action = 0.0
        elif name == "bonds" and difference <= 0.10:
            action = 0.0
        else:
            action = target * total - value
        trades.append(round(action, 2))
    return trades


def format_report(assets, trades):
    """Human readable lines describing the recommended trades."""
    lines = []
    for position, amount in enumerate(trades):
        name = assets[position][0]
        if amount > 0:
            lines.append("BUY  ${:.2f} of {}".format(amount, name))
        elif amount < 0:
            lines.append("SELL ${:.2f} of {}".format(abs(amount), name))
        else:
            lines.append("HOLD {}".format(name))
    return lines


def main():
    portfolio = [
        ("stocks", 6000, 0.50),
        ("bonds", 4000, 0.50),
        ("stop", 0, 0),
    ]
    trades = rebalance(portfolio)
    print("Portfolio value: ${:.2f}".format(portfolio_total(portfolio)))
    print(trades)
    for line in format_report(portfolio, trades):
        print(line)


