def validate_item(item):
    """Check that a cart entry has the shape (name, price, category, clearance)."""
    if not isinstance(item, tuple):
        raise TypeError("cart entries must be tuples")
    elif len(item) != 4:
        raise ValueError("cart entries must have exactly four fields")
    name, price, category, clearance = item
    if not isinstance(name, str):
        raise TypeError("item name must be a string")
    elif not isinstance(price, (int, float)):
        raise TypeError("item price must be a number")
    elif not isinstance(category, str):
        raise TypeError("item category must be a string")
    elif not isinstance(clearance, bool):
        raise TypeError("clearance flag must be a boolean")
    if price < 0:
        raise ValueError("item price must not be negative")
    return name, float(price), category, clearance


def item_final_price(price, category, clearance):
    """Apply the surcharge and discount rules to a single item."""
    final = price
    if category == "electronics":
        final += 5.0
    if clearance:
        final *= 0.8
    elif category == "clothing" and price > 50:
        final *= 0.9
    return final


def checkout(cart):
    """Total a cart, stopping at the sentinel item named 'done'."""
    subtotal = 0.0
    index = 0
    while index < len(cart):
        name, price, category, clearance = validate_item(cart[index])
        if name == "done":
            break
        subtotal += item_final_price(price, category, clearance)
        index += 1
    total = subtotal
    if subtotal > 200:
        total -= 20.0
    elif subtotal < 50:
        total += 10.0
    return total


def format_total(total):
    return "${:.2f}".format(total)


def main():
    carts = [
        ("mixed cart", [("shirt", 60, "clothing", False),
                        ("tv", 150, "electronics", True),
                        ("done", 0, "", False)]),
        ("small cart", [("socks", 12, "clothing", False),
                        ("done", 0, "", False)]),
        ("big cart", [("laptop", 900, "electronics", False),
                      ("coat", 120, "clothing", True),
                      ("done", 0, "", False),
                      ("ignored", 999, "electronics", False)]),
    ]
    biggest_label = None
    biggest_total = 0.0
    for label, cart in carts:
        total = checkout(cart)
        print("{}: {}".format(label, format_total(total)))
        if biggest_label is None:
            biggest_label = label
            biggest_total = total
        elif total > biggest_total:
            biggest_label = label
            biggest_total = total
    if biggest_label is not None:
        print("largest order: {} at {}".format(biggest_label, format_total(biggest_total)))


if __name__ == "__main__":
    main()

