START_SCORE = 1000
FREE_MINUTES = 60
PENALTY_PER_MINUTE = 10

DELTAS = {'minor hint': -50, 'major hint': -150, 'puzzle solved': 50}


def validate_action(action):
    """Check one (type, minutes) pair and return it unpacked."""
    if len(action) != 2:
        raise ValueError('each action needs an action type and a time')
    kind, minutes = action
    if not isinstance(kind, str):
        raise TypeError('action type must be a string')
    if isinstance(minutes, bool) or not isinstance(minutes, (int, float)):
        raise TypeError('action time must be a number of minutes')
    if minutes < 0:
        raise ValueError('action time cannot be negative')
    return kind, minutes


def overtime_penalty(minutes):
    """Ten points per whole minute spent beyond the allowed hour."""
    if minutes <= FREE_MINUTES:
        return 0
    return int(minutes - FREE_MINUTES) * PENALTY_PER_MINUTE


def score(actions):
    total = START_SCORE
    index = 0
    while index < len(actions):
        kind, minutes = validate_action(actions[index])
        if kind == 'escape':
            total -= overtime_penalty(minutes)
            if total < 0:
                total = 0
            return total
        elif kind in DELTAS:
            total += DELTAS[kind]
        else:
            raise ValueError('unknown action type: ' + kind)
        if total < 0:
            total = 0
        index += 1
    return total


def format_report(actions):
    """Build a line-by-line trace of the running score."""
    lines = []
    running = START_SCORE
    for action in actions:
        kind, minutes = validate_action(action)
        if kind == 'escape':
            penalty = overtime_penalty(minutes)
            running -= penalty
            if running < 0:
                running = 0
            lines.append('%6.1f  escape          -%-3d -> %d' % (minutes, penalty, running))
            break
        change = DELTAS.get(kind)
        if change is None:
            raise ValueError('unknown action type: ' + kind)
        running += change
        if running < 0:
            running = 0
        lines.append('%6.1f  %-14s %+4d -> %d' % (minutes, kind, change, running))
    return '\n'.join(lines)


def main():
    teams = {
        'Team Alpha': [('minor hint', 10), ('puzzle solved', 20),
                       ('major hint', 40), ('escape', 65)],
        'Team Bravo': [('major hint', 5), ('major hint', 15), ('major hint', 25),
                       ('major hint', 35), ('major hint', 45), ('major hint', 55),
                       ('major hint', 58), ('escape', 90), ('minor hint', 95)],
    }
    for name in sorted(teams):
        actions = teams[name]
        print(name)
        print(format_report(actions))
        final = score(actions)
        print('  final score: %d' % final)
        if final == 0:
            print('  verdict: eliminated')
        elif final < 700:
            print('  verdict: escaped')
        else:
            print('  verdict: escaped with honours')
        print()


main()

