START_RANK = 1000
MAX_RANK = 2000
MIN_RANK = 0
VALID_RESULTS = ('win', 'loss', 'exit')


def clamp(value):
    if value > MAX_RANK:
        return MAX_RANK
    elif value < MIN_RANK:
        return MIN_RANK
    return value


def validate_match(match):
    if len(match) != 3:
        raise ValueError('each match needs result, opponent rank and disconnect')
    result, opponent, disconnect = match
    if result not in VALID_RESULTS:
        raise ValueError('unknown result: %r' % (result,))
    elif not isinstance(opponent, int):
        raise ValueError('opponent rank must be an integer')
    elif opponent < MIN_RANK or opponent > MAX_RANK:
        raise ValueError('opponent rank out of range: %d' % opponent)
    if not isinstance(disconnect, bool):
        raise ValueError('disconnect must be a boolean')
    return result, opponent, disconnect


def rank(matches):
    current = START_RANK
    index = 0
    while index < len(matches):
        result, opponent, disconnect = validate_match(matches[index])
        if result == 'exit':
            break
        elif disconnect:
            current = clamp(current - 50)
        elif result == 'win':
            gain = 20
            if opponent > current:
                gain += 10
            current = clamp(current + gain)
        else:
            loss = 20
            if opponent > current:
                loss = 10
            current = clamp(current - loss)
        index += 1
    return current


def summarize(matches):
    counts = {'win': 0, 'loss': 0, 'disconnect': 0, 'skipped': 0}
    index = 0
    while index < len(matches):
        entry = validate_match(matches[index])
        if entry[0] == 'exit':
            counts['skipped'] = len(matches) - index - 1
            break
        if entry[2]:
            counts['disconnect'] += 1
        counts[entry[0]] += 1
        index += 1
    return counts


def parse_match(line):
    parts = [piece.strip() for piece in line.split(',')]
    if len(parts) != 3:
        raise ValueError('cannot parse match line: %r' % (line,))
    flag = parts[2].lower()
    if flag not in ('true', 'false'):
        raise ValueError('bad disconnect flag: %r' % (parts[2],))
    return (parts[0].lower(), int(parts[1]), flag == 'true')


def main():
    lines = ['win, 1200, false', 'loss, 900, false', 'win, 1000, true', 'exit, 0, false']
    matches = [parse_match(line) for line in lines]
    final = rank(matches)
    counts = summarize(matches)
    print('final rank: %d' % final)
    print('wins: %d  losses: %d  disconnects: %d' % (counts['win'], counts['loss'], counts['disconnect']))
    if counts['skipped'] > 0:
        print('matches ignored after exit: %d' % counts['skipped'])
    if final >= MAX_RANK:
        print('rank capped at the maximum')
    elif final <= MIN_RANK:
        print('rank bottomed out')


main()

