        raise ValueError("each offense needs a limit, a speed and a zone")
    limit, speed, zone = offense
    if (limit < 0):
        raise ValueError("speed limit cannot be negative")
    if (speed < 0):
        raise ValueError("measured speed cannot be negative")
    return limit, speed, normalize_zone(zone)


def base_fine(over):
    """Fine before any zone adjustment, based on miles per hour over."""
    if (over <= 5):
        return 0
    elif (over <= 15):
        return 100
    elif (over <= 25):
        return 200
    return 400


def zone_adjust(fine, zone):
    """School zones double the fine, construction zones add a flat 100."""
    if (zone == "school"):
        return fine * 2
    elif (zone == "construction"):
        return fine + 100
    return fine


def fine_for(limit, speed, zone):
    if (speed <= limit):
        return 0
    return zone_adjust(base_fine(speed - limit), zone)


def citations(offenses):
    """Evaluate offenses until a zero speed limit terminates the list."""
    fines = []
    index = 0
    while (index < len(offenses)):
        limit, speed, zone = parse_offense(offenses[index])
        if (limit == 0):
            break
        fines.append(fine_for(limit, speed, zone))
        index += 1
    return fines


def describe(fine):
    if (fine == 0):
        return "warning issued, no fine"
    return "fine of ${}".format(fine)


def main():
    offenses = [(30, 34, 'regular'), (50, 70, 'school'),
                (60, 80, 'construction'), (0, 0, 'none')]
    fines = citations(offenses)
    print(fines)
    position = 0
    while (position < len(fines)):
        print("offense {}: {}".format(position + 1, describe(fines[position])))
        position += 1
    total = sum(fines)
    if (total == 0):
        print("no money owed")
    else:
        print("total owed: ${}".format(total))


main()

