PRICES = {'general': 50.0, 'vip': 100.0, 'student': 30.0}


def validate_order(order):
    if len(order) != 3:
        raise ValueError('an order needs a ticket type, a quantity and a promo code')
    ticket_type, quantity, code = order
    if not isinstance(quantity, int):
        raise TypeError('quantity must be an integer')
    elif quantity < 0:
        raise ValueError('quantity cannot be negative')
    if not isinstance(code, str):
        raise TypeError('promo code must be a string')
    return ticket_type, quantity, code


def unit_price(ticket_type):
    if ticket_type not in PRICES:
        raise ValueError('unknown ticket type: ' + str(ticket_type))
    return PRICES[ticket_type]


def apply_bulk_discount(subtotal, quantity):
    if quantity >= 5:
        return subtotal * 0.9
    return subtotal


def apply_promo(total, quantity, code):
    if code == 'staff':
        return 0.0
    elif code == 'earlybird':
        return total - 10.0 * quantity
    return total


def tickets(orders):
    prices = []
    index = 0
    while index < len(orders):
        ticket_type, quantity, code = validate_order(orders[index])
        if quantity == 0:
            break
        total = apply_bulk_discount(unit_price(ticket_type) * quantity, quantity)
        prices.append(apply_promo(total, quantity, code))
        index += 1
    return prices


def describe_order(ticket_type, quantity, code, price):
    notes = []
    if quantity >= 5:
        notes.append('bulk -10%')
    if code == 'staff':
        notes.append('staff comp')
    elif code == 'earlybird':
        notes.append('earlybird -10/ticket')
    line = '{:>8} x{:<3} {:>8.2f}'.format(ticket_type, quantity, price)
    if notes:
        line += '  [' + ', '.join(notes) + ']'
    return line


def format_report(orders, prices):
    lines = []
    for index, price in enumerate(prices):
        ticket_type, quantity, code = orders[index]
        lines.append(describe_order(ticket_type, quantity, code, price))
    lines.append('{:>13} {:>8.2f}'.format('TOTAL', sum(prices)))
    return '\n'.join(lines)


def main():
    orders = [('vip', 2, 'earlybird'), ('general', 6, 'none'),
              ('student', 1, 'staff'), ('none', 0, 'none')]
    prices = tickets(orders)
    print(prices)
    print(format_report(orders, prices))
    skipped = len(orders) - len(prices)
    if skipped > 0:
        print('stopped early, {} order(s) not processed'.format(skipped))


if __name__ == '__main__':
    main()

