def validate_routine(routine):
    if len(routine) != 4:
        raise ValueError("each routine needs difficulty, execution, falls, overtime")
    difficulty, execution, falls, overtime = routine
    if difficulty < 0 or execution < 0:
        raise ValueError("scores cannot be negative")
    elif falls < 0:
        raise ValueError("fall count cannot be negative")
    elif not isinstance(overtime, bool):
        raise ValueError("overtime must be a boolean")
    return difficulty, execution, falls, overtime


def score_routine(difficulty, execution, falls, overtime):
    score = difficulty + execution
    score -= 0.5 * falls
    if falls >= 3:
        score -= 1.0
    if overtime:
        score -= 0.1
    if score > 20:
        score = 20.0
    elif score < 0:
        score = 0.0
    return round(score, 1)


def gymnastics(routines):
    finals = []
    index = 0
    while index < len(routines):
        difficulty, execution, falls, overtime = validate_routine(routines[index])
        if difficulty == 0:
            break
        finals.append(score_routine(difficulty, execution, falls, overtime))
        index += 1
    return finals


def medal_for(rank):
    if rank == 1:
        return "gold"
    elif rank == 2:
        return "silver"
    elif rank == 3:
        return "bronze"
    return "no medal"


def format_report(scores):
    ranked = sorted(range(len(scores)), key=lambda i: -scores[i])
    lines = []
    rank = 0
    previous = None
    for position, athlete in enumerate(ranked, start=1):
        if previous is None or scores[athlete] < previous:
            rank = position
            previous = scores[athlete]
        lines.append("#%d athlete %d: %.1f (%s)" % (rank, athlete + 1, scores[athlete], medal_for(rank)))
    if not lines:
        lines.append("no routines judged")
    return "\n".join(lines)


def main():
    routines = [(10.0, 9.5, 1, False), (5.0, 5.0, 4, True), (15.0, 9.0, 0, False), (0, 0, 0, False)]
    scores = gymnastics(routines)
    print(scores)
    print(format_report(scores))
    perfect = [s for s in scores if s == 20.0]
    if len(perfect) > 1:
        print("tie at the cap: %d athletes reached 20.0" % len(perfect))
    elif perfect:
        print("one athlete reached the capped 20.0")
    else:
        print("nobody reached the cap")


if __name__ == "__main__":
    main()

