def residential_charge(gallons):
    """Cost of water for a residential customer, before any penalty."""
    if gallons <= 1000:
        return 0.0
    elif gallons <= 5000:
        return (gallons - 1000) * 0.02
    else:
        return 4000 * 0.02 + (gallons - 5000) * 0.05


def commercial_charge(gallons):
    """Cost of water for a commercial customer, before any penalty."""
    return 50.0 + gallons * 0.03


def check_reading(reading):
    """Validate one raw reading and return (gallons, customer type, late flag)."""
    if not isinstance(reading, tuple):
        raise TypeError("each reading must be a tuple")
    if len(reading) != 3:
        raise ValueError("each reading needs gallons, customer type and late flag")
    gallons, kind, late = reading
    if not isinstance(gallons, int):
        raise TypeError("gallons used must be an integer")
    if gallons < -1:
        raise ValueError("gallons used cannot be below -1")
    return gallons, str(kind).strip().lower(), bool(late)


def water(readings):
    """Tally the final bill for every reading until the -1 sentinel appears."""
    bills = []
    index = 0
    while index < len(readings):
        gallons, kind, late = check_reading(readings[index])
        if gallons == -1:
            break
        elif kind == "residential":
            bill = residential_charge(gallons)
        elif kind == "commercial":
            bill = commercial_charge(gallons)
        else:
            raise ValueError("unknown customer type: " + kind)
        if late:
            bill *= 1.1
        bills.append(round(bill, 2))
        index += 1
    return bills


def format_report(readings, bills):
    """Render a short per-customer report plus a total line."""
    if not bills:
        return "No billable readings."
    lines = []
    position = 0
    while position < len(bills):
        gallons, kind, late = check_reading(readings[position])
        note = "late" if late else "on time"
        lines.append("%5d gal  %-11s %-7s $%8.2f" % (gallons, kind, note, bills[position]))
        position += 1
    lines.append("%s $%8.2f" % ("TOTAL".rjust(26), sum(bills)))
    return "\n".join(lines)


def main():
    readings = [
        (1500, "residential", False),
        (2000, "commercial", True),
        (7200, "Residential", True),
        (-1, "none", False),
        (9999, "commercial", False),
    ]
    bills = water(readings)
    print(bills)
    print(format_report(readings, bills))


main()

