def validate_patron(patron):
    """Check one input record and return it as (int age, bool matinee, bool three_d)."""
    if not isinstance(patron, tuple):
        raise TypeError("each patron must be a tuple")
    if len(patron) != 3:
        raise ValueError("each patron needs age, matinee and three_d")
    age, matinee, three_d = patron
    if not isinstance(age, int):
        raise TypeError("age must be an integer")
    if age < 0:
        raise ValueError("age must not be negative")
    return age, bool(matinee), bool(three_d)


def ticket_price(age, matinee, three_d):
    """Price for a single ticket following the house rules."""
    if age < 12:
        price = 10.0
    elif age >= 65:
        price = 12.0
    else:
        price = 15.0
    if matinee:
        price -= 3.0
    if three_d:
        price += 4.0
    return price


def age_category(age):
    if age < 12:
        return "child"
    elif age >= 65:
        return "senior"
    return "adult"


def boxoffice(patrons):
    """Sum the revenue of every ticket up to (but not including) the age-zero sentinel."""
    total = 0.0
    index = 0
    while index < len(patrons):
        age, matinee, three_d = validate_patron(patrons[index])
        if age == 0:
            break
        total += ticket_price(age, matinee, three_d)
        index += 1
    return total


def receipt_lines(patrons):
    """Build a human readable breakdown of the sales boxoffice() totals."""
    lines = []
    index = 0
    while index < len(patrons):
        age, matinee, three_d = validate_patron(patrons[index])
        if age == 0:
            break
        label = age_category(age)
        if matinee:
            label += " matinee"
        if three_d:
            label += " 3D"
        lines.append("{0:<22}{1:>7.2f}".format(label, ticket_price(age, matinee, three_d)))
        index += 1
    if not lines:
        lines.append("no tickets sold")
    lines.append("{0:<22}{1:>7.2f}".format("TOTAL", boxoffice(patrons)))
    return lines


def main():
    patrons = [(10, True, True), (30, False, True), (70, True, False), (0, False, False)]
    for line in receipt_lines(patrons):
        print(line)
    print("revenue:", boxoffice(patrons))


main()

