import sys

CATEGORIES = ("excellent", "good", "pass", "fail")


def parse_bool(text):
    value = text.strip().lower()
    if value in ("true", "yes", "y", "1"):
        return True
    elif value in ("false", "no", "n", "0"):
        return False
    raise ValueError("cannot read %r as a boolean" % text)


def parse_record(line):
    fields = [field.strip() for field in line.split(",")]
    if len(fields) != 4:
        raise ValueError("expected 4 fields, got %d" % len(fields))
    elif not fields[0]:
        raise ValueError("the student name must not be empty")
    return fields[0], float(fields[1]), parse_bool(fields[2]), int(fields[3])


def validate(score, late, absence):
    if isinstance(score, bool) or not isinstance(score, (int, float)):
        raise TypeError("score must be a number")
    elif score < 0 or score > 100:
        raise ValueError("score must lie between 0 and 100")
    if not isinstance(late, bool):
        raise TypeError("late must be a boolean")
    if isinstance(absence, bool) or not isinstance(absence, int):
        raise TypeError("absence must be an integer")
    elif absence < 0:
        raise ValueError("absence must not be negative")


def grade(score, late, absence):
    validate(score, late, absence)
    if absence > 5:
        return "fail"
    final = score
    if late:
        final -= 10
    if final >= 90:
        return "excellent"
    elif final >= 80:
        return "good"
    elif final >= 70:
        return "pass"
    return "fail"


def format_line(name, result, width):
    padded = name
    while len(padded) < width:
        padded += " "
    return "%s : %s" % (padded, result)


def format_report(counts):
    lines = []
    for category in CATEGORIES:
        total = counts.get(category, 0)
        if total == 1:
            lines.append("%s: 1 student" % category)
        elif total > 1:
            lines.append("%s: %d students" % (category, total))
    return "\n".join(lines)


def main():
    records = []
    for line in sys.stdin:
        stripped = line.strip()
        if not stripped:
            continue
        elif stripped.startswith("#"):
            continue
        records.append(parse_record(stripped))
    if not records:
        print("no records given")
        return
    width = max(len(record[0]) for record in records)
    counts = {}
    for name, score, late, absence in records:
        result = grade(score, late, absence)
        counts[result] = counts.get(result, 0) + 1
        print(format_line(name, result, width))
    print("-" * (width + 12))
    print(format_report(counts))


main()

