DIRECTIONS = ((0, 1), (1, 0), (0, -1), (-1, 0))
TURNS = {"L": -1, "R": 1}


def normalize(commands):
    """Turn a command string into a list of F/B/L/R letters."""
    if not isinstance(commands, str):
        raise TypeError("commands must be a string")
    letters = []
    for ch in commands:
        upper = ch.upper()
        if upper in "FBLR":
            letters.append(upper)
        elif ch.isspace():
            continue
        else:
            raise ValueError("unknown command: %r" % ch)
    return letters


def check_grid(grid):
    """Validate the grid and return its width."""
    if not grid:
        raise ValueError("grid must have at least one row")
    width = len(grid[0])
    if width == 0:
        raise ValueError("grid rows must not be empty")
    for row in grid:
        if len(row) != width:
            raise ValueError("grid rows must all have the same length")
        for cell in row:
            if cell not in (0, 1):
                raise ValueError("grid cells must be 0 or 1")
    return width


def in_bounds(row, col, height, width):
    if row < 0 or row >= height:
        return False
    return 0 <= col < width


def step(row, col, facing, command):
    """Return the coordinate reached by a forward or backward command."""
    drow, dcol = DIRECTIONS[facing]
    if command == "B":
        drow, dcol = -drow, -dcol
    return row + drow, col + dcol


def navigate(commands, grid):
    width = check_grid(grid)
    height = len(grid)
    moves = normalize(commands)
    row, col, facing = 0, 0, 0
    index = 0
    while index < len(moves):
        command = moves[index]
        index += 1
        if command in TURNS:
            facing = (facing + TURNS[command]) % 4
            continue
        nrow, ncol = step(row, col, facing, command)
        if not in_bounds(nrow, ncol, height, width):
            continue
        if grid[nrow][ncol] == 1:
            return (row, col)
        row, col = nrow, ncol
    return (row, col)

