TRUSTED_SSH_SOURCE = "203.0.113.5"
INTERNAL_PREFIXES = ("10.", "192.")
ALLOWED_TCP_PORTS = frozenset([80, 443])

RAW_RECORDS = [
    "198.51.100.7, 80, TCP",
    "# capture from border router, 2024-05-01",
    "10.0.0.9, 443, tcp",
    "192.168.1.4, 53, udp",
    "198.51.100.7, 22, tcp",
    "203.0.113.5, 22, tcp",
    "",
    "198.51.100.30, 53, UDP",
    "198.51.100.30, 8080, tcp",
    "198.51.100.30, ssh, tcp",
]


def is_internal(source):
    index = 0
    while index < len(INTERNAL_PREFIXES):
        if source.startswith(INTERNAL_PREFIXES[index]):
            return True
        index += 1
    return False


def parse_packet(text):
    fields = text.split(",")
    if len(fields) != 3:
        raise ValueError("expected 3 comma separated fields in %r" % text)
    source = fields[0].strip()
    port_text = fields[1].strip()
    protocol = fields[2].strip().lower()
    if not source:
        raise ValueError("missing source address in %r" % text)
    elif not port_text.isdigit():
        raise ValueError("port %r is not a number" % port_text)
    port = int(port_text)
    if port < 1 or port > 65535:
        raise ValueError("port %d is out of range" % port)
    return (source, port, protocol)


def verdict(packet):
    source, port, protocol = packet
    if is_internal(source):
        return "internal traffic"
    elif port == 22 and source != TRUSTED_SSH_SOURCE:
        return "ssh from untrusted source"
    elif protocol == "tcp" and port in ALLOWED_TCP_PORTS:
        return None
    elif protocol == "udp" and port == 53:
        return None
    return "no matching allow rule"


def filter(packets):
    allowed = []
    for packet in packets:
        if verdict(packet) is None:
            allowed.append(packet)
    return allowed


def format_report(packets):
    lines = []
    for source, port, protocol in packets:
        reason = verdict((source, port, protocol))
        label = "%-16s %-5d %s" % (source, port, protocol)
        if reason is None:
            lines.append("ALLOW " + label)
        else:
            lines.append("DROP  " + label + "  <- " + reason)
    return "\n".join(lines)


def main():
    packets = []
    index = 0
    while index < len(RAW_RECORDS):
        text = RAW_RECORDS[index].strip()
        index += 1
        if not text:
            continue
        elif text.startswith("#"):
            continue
        try:
            packets.append(parse_packet(text))
        except ValueError as error:
            print("skipping record: %s" % error)
    print(format_report(packets))
    allowed = filter(packets)
    print("allowed %d of %d packets" % (len(allowed), len(packets)))


main()

