        shift = 6
    elif (gid == group_id):
        shift = 3
    else:
        shift = 0
    return (bits >> shift) & 7


def access(user, file, action):
    """True if the user may perform the action on the file."""
    if (len(user) != 2):
        raise ValueError("user must be (uid, gid)")
    if (len(file) != 3):
        raise ValueError("file must be (owner_id, group_id, bits)")
    return permission_digit(user, file) & action_bit(action) != 0


def parse_mode(text):
    """Convert a mode written as octal digits, e.g. '0o640' or '640', to an int."""
    digits = text.strip()
    if (digits.startswith("0o")):
        digits = digits[2:]
    if (not digits):
        raise ValueError("empty mode")
    i = 0
    while (i < len(digits)):
        if (digits[i] not in "01234567"):
            raise ValueError("not an octal mode: " + text)
        i += 1
    return int(digits, 8)


def format_mode(bits):
    """Render the low nine permission bits as an rwx string."""
    out = []
    for shift in (6, 3, 0):
        digit = (bits >> shift) & 7
        for bit, letter in ((4, "r"), (2, "w"), (1, "x")):
            if (digit & bit):
                out.append(letter)
            else:
                out.append("-")
    return "".join(out)


def audit(user, file, actions):
    """Describe the outcome of each action for the given user and file."""
    lines = []
    for action in actions:
        if (access(user, file, action)):
            verdict = "granted"
        else:
            verdict = "denied"
        lines.append("%-8s %s" % (action, verdict))
    return lines


def main():
    requests = [
        ((1000, 1000), (1000, 1000, "0o640")),
        ((1001, 1000), (1000, 1000, "640")),
        ((1002, 1002), (1000, 1000, "751")),
    ]
    for user, raw_file in requests:
        bits = parse_mode(raw_file[2])
        file = (raw_file[0], raw_file[1], bits)
        print("user %s on file owner=%d group=%d mode=%s"
              % (user, file[0], file[1], format_mode(bits)))
        for line in audit(user, file, ("read", "write", "execute")):
            print("   " + line)


main()

