STAT_NAMES = ["STR", "DEX", "CON", "INT", "WIS", "CHA"]
RACE_BONUS = ("elf", "dwarf", "orc")
CLASSES = ("wizard", "fighter", "rogue")


def stats_in_range(stats):
    for value in stats:
        if value < 3 or value > 18:
            return False
    return True


def apply_race(stats, race):
    adjusted = list(stats)
    if race == "elf":
        adjusted[1] += 2
    elif race == "dwarf":
        adjusted[2] += 2
    elif race == "orc":
        adjusted[0] += 2
        adjusted[3] -= 2
    return adjusted


def meets_class_requirement(stats, classname):
    if classname == "wizard":
        return stats[3] >= 14
    elif classname == "fighter":
        return stats[0] >= 14 or stats[1] >= 14
    elif classname == "rogue":
        return stats[1] >= 14
    return True


def validate(stats, race, classname):
    if len(stats) != 6:
        return False
    if not stats_in_range(stats):
        return False
    adjusted = apply_race(stats, race)
    if not stats_in_range(adjusted):
        return False
    return meets_class_requirement(adjusted, classname)


def parse_character(line):
    parts = [piece.strip() for piece in line.split(":")]
    if len(parts) != 4:
        raise ValueError("expected 'name:race:class:s1,s2,s3,s4,s5,s6'")
    numbers = []
    for token in parts[3].split(","):
        token = token.strip()
        if not token.isdigit():
            raise ValueError("bad stat value: " + repr(token))
        numbers.append(int(token))
    return parts[0], parts[1].lower(), parts[2].lower(), numbers


def format_stats(stats):
    pieces = []
    index = 0
    while index < len(stats) and index < len(STAT_NAMES):
        pieces.append("%s %2d" % (STAT_NAMES[index], stats[index]))
        index += 1
    return "  ".join(pieces)


def report(name, race, classname, stats):
    lines = ["%s the %s %s" % (name, race, classname)]
    if race not in RACE_BONUS:
        lines.append("  no racial bonus applied")
    if classname not in CLASSES:
        lines.append("  no class requirement to check")
    lines.append("  " + format_stats(apply_race(stats, race)))
    if validate(stats, race, classname):
        lines.append("  ACCEPTED")
    else:
        lines.append("  REJECTED")
    return "\n".join(lines)


def main():
    roster = [
        "Fingol:elf:rogue:11,13,10,15,12,9",
        "Brok:dwarf:fighter:14,10,15,8,11,7",
        "Gurm:orc:wizard:15,9,14,16,10,6",
        "Mira:human:wizard:10,12,11,13,14,12",
        "Broken:dwarf:fighter:14,10,x,8,11,7",
    ]
    index = 0
    while index < len(roster):
        line = roster[index]
        index += 1
        try:
            name, race, classname, stats = parse_character(line)
        except ValueError as error:
            print("skipping %r: %s" % (line, error))
            continue
        print(report(name, race, classname, stats))


