def normalize_soil(soil):
    """Return a canonical lower-case soil name."""
    if not isinstance(soil, str):
        raise TypeError("soil must be a string")
    name = soil.strip().lower()
    if name == "":
        raise ValueError("soil must not be empty")
    return name


def predict(rainfall, temp, soil):
    """Estimate crop yield from rainfall, temperature and soil type."""
    if isinstance(rainfall, bool) or isinstance(temp, bool):
        raise TypeError("rainfall and temp must be numbers")
    if not isinstance(rainfall, (int, float)):
        raise TypeError("rainfall must be a number")
    if not isinstance(temp, (int, float)):
        raise TypeError("temp must be a number")

    ground = normalize_soil(soil)
    estimate = 100.0

    if rainfall < 20:
        estimate *= 0.5
    elif rainfall > 80:
        estimate *= 0.8

    if temp < 15:
        estimate -= 30
    elif temp > 35:
        estimate -= 40

    if ground == "clay" and rainfall > 80:
        estimate -= 10
    elif ground == "sandy" and rainfall < 20:
        estimate -= 15
    elif ground == "loam":
        estimate += 20

    return int(estimate)


def grade(yield_value):
    """Describe an estimated yield in words."""
    if yield_value >= 100:
        return "excellent"
    elif yield_value >= 70:
        return "good"
    elif yield_value >= 40:
        return "poor"
    return "failed"


def parse_record(line):
    """Parse 'rainfall, temp, soil' into a tuple of values."""
    parts = line.split(",")
    if len(parts) != 3:
        raise ValueError("expected three comma-separated fields: " + line)
    return float(parts[0]), float(parts[1]), parts[2]


def report(lines):
    """Turn a list of raw data lines into formatted report rows."""
    rows = []
    index = 0
    while index < len(lines):
        line = lines[index].strip()
        index += 1
        if line == "":
            continue
        elif line.startswith("#"):
            continue
        rainfall, temp, soil = parse_record(line)
        estimate = predict(rainfall, temp, soil)
        label = normalize_soil(soil).ljust(6)
        rows.append("%s rain=%5.1f temp=%5.1f -> %3d (%s)"
                    % (label, rainfall, temp, estimate, grade(estimate)))
    return rows


def main():
    data = [
        "# rainfall, temp, soil",
        "50, 22, loam",
        "15, 20, sandy",
        "90, 25, clay",
        "",
        "45, 10, clay",
        "60, 40, loam",
    ]
    for row in report(data):
        print(row)


main()

