VALID_PASSENGERS = ("adult", "child", "senior")
PEAK_MULTIPLIER = 1.5
MINIMUM_FARE = 5.0


def is_peak(time):
    if 7 <= time <= 9:
        return True
    elif 16 <= time <= 18:
        return True
    return False


def validate(distance, time, passenger):
    if not isinstance(distance, (int, float)):
        raise TypeError("distance must be a number")
    if distance < 0:
        raise ValueError("distance must not be negative")
    if not isinstance(time, int):
        raise TypeError("time must be an integer hour of day")
    if time < 0 or time > 23:
        raise ValueError("time must be an hour between 0 and 23")
    if passenger not in VALID_PASSENGERS:
        raise ValueError("unknown passenger type: %s" % passenger)


def price(distance, time, passenger):
    validate(distance, time, passenger)
    peak = is_peak(time)
    fare = distance * 0.2
    if peak:
        fare *= PEAK_MULTIPLIER
    if passenger == "child":
        fare *= 0.5
    elif passenger == "senior" and not peak:
        fare *= 0.7
    if fare < MINIMUM_FARE:
        fare = MINIMUM_FARE
    if distance > 200:
        fare -= 10
    return round(fare, 2)


def parse_trip(text):
    parts = [piece.strip() for piece in text.split(",")]
    if len(parts) != 3:
        raise ValueError("expected 'distance,hour,passenger' but got %r" % text)
    return float(parts[0]), int(parts[1]), parts[2].lower()


def format_row(distance, time, passenger, amount):
    if is_peak(time):
        tag = "peak"
    else:
        tag = "off-peak"
    return "%8.1f km  %02d:00  %-7s %-9s %8.2f" % (distance, time, passenger, tag, amount)


def cheapest_hour(distance, passenger):
    best_hour = 0
    best_price = price(distance, 0, passenger)
    hour = 1
    while hour < 24:
        candidate = price(distance, hour, passenger)
        if candidate < best_price:
            best_price = candidate
            best_hour = hour
        hour += 1
    return best_hour, best_price


def main():
    bookings = ["12.5, 8, adult", "250, 17, senior", "3, 11, child", "80, 22, senior"]
    total = 0.0
    index = 0
    while index < len(bookings):
        distance, time, passenger = parse_trip(bookings[index])
        amount = price(distance, time, passenger)
        total += amount
        print(format_row(distance, time, passenger, amount))
        index += 1
    print("total: %.2f" % round(total, 2))
    hour, amount = cheapest_hour(250, "senior")
    print("cheapest hour for a 250 km senior trip: %02d:00 at %.2f" % (hour, amount))


main()

