VALID_LETTERS = "acgt"
START_CODON = "atg"
STOP_CODONS = ("taa", "tag", "tga")

INVALID_LENGTH = "error: sequence length is not a multiple of three"
INVALID_CHARACTER = "error: sequence contains an invalid character"
PREMATURE_STOP = "error: stop codon found before any start codon"
MISSING_STOP = "error: sequence ends without a stop codon"


def normalize(sequence):
    """Drop layout whitespace and fold the sequence to lower case."""
    cleaned = []
    for letter in sequence:
        if letter.isspace():
            continue
        cleaned.append(letter.lower())
    return "".join(cleaned)


def is_valid_codon(codon):
    """True when every letter of the codon is one of a, c, g, t."""
    index = 0
    while index < len(codon):
        if codon[index] not in VALID_LETTERS:
            return False
        index += 1
    return True


def analyze(sequence):
    seq = normalize(sequence)
    if len(seq) % 3 != 0:
        return INVALID_LENGTH
    starts = 0
    stops = 0
    position = 0
    while position < len(seq):
        codon = seq[position:position + 3]
        if not is_valid_codon(codon):
            return INVALID_CHARACTER
        if codon == START_CODON:
            starts += 1
        elif codon in STOP_CODONS:
            if starts == 0:
                return PREMATURE_STOP
            stops += 1
        position += 3
    if stops == 0:
        return MISSING_STOP
    return (starts, stops)


def format_report(label, result):
    if isinstance(result, tuple):
        starts, stops = result
        return "{0}: {1} start codon(s), {2} stop codon(s)".format(label, starts, stops)
    return "{0}: {1}".format(label, result)


def main():
    samples = [
        "atg gca taa",
        "ATGATGGCCTGA",
        "atg gc taa",
        "atg gxa taa",
        "taa atg gca tag",
        "atg gca gcc",
    ]
    accepted = 0
    for sample in samples:
        result = analyze(sample)
        if isinstance(result, tuple):
            accepted += 1
        print(format_report(sample, result))
    print("{0} of {1} sequences accepted".format(accepted, len(samples)))


main()

