from fractions import Fraction

UNIT_ALIASES = {
    "teaspoon": "teaspoon", "tsp": "teaspoon", "t": "teaspoon",
    "tablespoon": "tablespoon", "tbsp": "tablespoon", "T": "tablespoon",
    "cup": "cup", "c": "cup",
    "ounce": "ounce", "oz": "ounce",
    "pound": "pound", "lb": "pound",
    "quart": "quart", "qt": "quart",
}


def normalize_unit(unit):
    key = str(unit).strip()
    if key in UNIT_ALIASES:
        return UNIT_ALIASES[key]
    key = key.lower()
    if key in UNIT_ALIASES:
        return UNIT_ALIASES[key]
    elif key.endswith("s") and key[:-1] in UNIT_ALIASES:
        return UNIT_ALIASES[key[:-1]]
    return key


def convert(amount, unit):
    while unit == "teaspoon" and amount >= 3:
        amount, unit = amount / 3.0, "tablespoon"
    while unit == "tablespoon" and amount >= 16:
        amount, unit = amount / 16.0, "cup"
    while unit == "ounce" and amount >= 16:
        amount, unit = amount / 16.0, "pound"
    while unit == "cup" and amount > 4:
        amount, unit = amount / 4.0, "quart"
    return amount, unit


def scale(ingredients, multiplier):
    if multiplier <= 0:
