CAP = 5.0


def validate_trip(zones, transfers, time):
    """Reject trip descriptions that cannot be priced."""
    if zones < 1:
        raise ValueError("a commute must cross at least one zone")
    if transfers < 0:
        raise ValueError("transfers cannot be negative")
    if time < 0.0 or time >= 24.0:
        raise ValueError("time must be an hour in [0, 24)")


def commute(zones, transfers, time):
    validate_trip(zones, transfers, time)
    total = 2.0
    if zones == 2:
        total += 1.0
    elif zones >= 3:
        total += 2.0
    if 8.0 <= time <= 10.0:
        total += 0.5
    elif 0.0 < time < 5.0:
        total += 1.0
    if transfers == 1:
        total += 0.25
    elif transfers >= 2:
        total += 0.5
    if total > CAP:
        total = CAP
    return total


def parse_trip(text):
    """Turn "zones,transfers,hour" into the argument triple for commute."""
    parts = text.split(",")
    if len(parts) != 3:
        raise ValueError("expected zones,transfers,hour but got %r" % text)
    return int(parts[0]), int(parts[1]), float(parts[2])


def format_time(time):
    hour = int(time)
    minute = int(round((time - hour) * 60))
    if minute == 60:
        minute = 0
        hour += 1
    suffix = "am"
    if hour >= 12:
        suffix = "pm"
    display = hour
    if hour == 0:
        display = 12
    elif hour > 12:
        display = hour - 12
    return "%2d:%02d%s" % (display, minute, suffix)


def summarize(lines):
    """Price every non-empty trip line and return rows plus the grand total."""
    rows = []
    grand_total = 0.0
    index = 0
    while index < len(lines):
        line = lines[index].strip()
        index += 1
        if not line:
            continue
        zones, transfers, time = parse_trip(line)
        fare = commute(zones, transfers, time)
        rows.append((zones, transfers, time, fare))
        grand_total += fare
    return rows, grand_total


