VOWELS = "aeiou"
CLUSTERS = ("ch", "sh", "th")


def has_digit(word):
    """Return True if the word contains at least one digit character."""
    index = 0
    while index < len(word):
        if word[index].isdigit():
            return True
        index += 1
    return False


def translate_word(word):
    """Translate a single word into pig latin, preserving capitalization."""
    if has_digit(word):
        return word
    lowered = word.lower()
    if lowered[0] in VOWELS:
        moved = lowered + "way"
    elif lowered[:2] in CLUSTERS:
        moved = lowered[2:] + lowered[:2] + "ay"
    else:
        moved = lowered[1:] + lowered[0] + "ay"
    if word[0].isupper():
        moved = moved.capitalize()
    return moved


def translate(sentence):
    """Translate every word of a space separated sentence into pig latin."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")
    words = sentence.split()
    results = []
    for word in words:
        results.append(translate_word(word))
    return " ".join(results)


def report(sentence):
    """Build a per-word report showing how each word was translated."""
    originals = sentence.split()
    translated = translate(sentence).split()
    width = 0
    for word in originals:
        if len(word) > width:
            width = len(word)
    lines = []
    index = 0
    while index < len(originals):
        original = originals[index]
        result = translated[index]
        if original == result:
            lines.append("%-*s  (unchanged)" % (width, original))
        else:
            lines.append("%-*s  ->  %s" % (width, original, result))
        index += 1
    return lines


def main():
    samples = [
        "Hello world",
        "The cheerful shark ate 3 apples",
        "I think this is a thorough test",
    ]
    for sample in samples:
        print("input : %s" % sample)
        print("output: %s" % translate(sample))
        for line in report(sample):
            print("  " + line)
        print()


main()

