def _normalise(moisture, humidity, species):
    """Check the sensor readings and return the canonical species name."""
    if not isinstance(moisture, int) or not isinstance(humidity, int):
        raise TypeError("moisture and humidity must be integer percentages")
    if not 0 <= moisture <= 100:
        raise ValueError("moisture must be a percentage between 0 and 100")
    if not 0 <= humidity <= 100:
        raise ValueError("humidity must be a percentage between 0 and 100")
    name = species.strip().lower()
    if not name:
        raise ValueError("species must not be empty")
    return name


def _amount_label(factor):
    if factor >= 2.0:
        return "water heavily"
    elif factor >= 1.0:
        return "water normally"
    return "water lightly"


def water(moisture, humidity, species):
    """Return the watering verdict for one plant reading."""
    name = _normalise(moisture, humidity, species)
    factor = 1.0
    if humidity > 80:
        factor = 0.5
    elif humidity < 30:
        factor = 2.0

    urgent = False
    if name == "cactus" and moisture > 10:
        return "do not water"
    elif name == "fern" and moisture < 50:
        urgent = True
    elif name == "orchid" and moisture < 30:
        if humidity >= 40:
            return "do not water"
        urgent = True
    elif name == "tomato" and moisture < 40:
        urgent = True

    if urgent:
        factor *= 2
    return _amount_label(factor)


def parse_reading(line):
    """Parse a 'moisture,humidity,species' line into its three values."""
    parts = [piece.strip() for piece in line.split(",")]
    if len(parts) != 3:
        raise ValueError("expected three comma separated fields: " + line)
    return int(parts[0]), int(parts[1]), parts[2]


def report(lines):
    """Print a verdict per reading and a count of the plants left dry."""
    index = 0
    dry = 0
    while index < len(lines):
        moisture, humidity, species = parse_reading(lines[index])
        verdict = water(moisture, humidity, species)
        if verdict == "do not water":
            dry += 1
        print("%-8s moisture=%3d%% humidity=%3d%% -> %s" % (species, moisture, humidity, verdict))
        index += 1
    if dry == 1:
        print("1 plant needs no water today.")
    elif dry > 1:
        print("%d plants need no water today." % dry)
    else:
        print("Every plant needs some water today.")


