import sys

VOWELS = "aeiou"


def shift_letter(ch, amount):
    if ch.isupper():
        base = ord('A')
    else:
        base = ord('a')
    return chr(base + (ord(ch) - base + amount) % 26)


def is_vowel(ch):
    return ch.lower() in VOWELS


def transform_char(ch, shift):
    if ch == ' ':
        return '_'
    elif ch.isdigit():
        return str(9 - int(ch))
    elif ch.isalpha():
        if is_vowel(ch):
            return shift_letter(ch, shift * 2)
        return shift_letter(ch, shift)
    return ch


def cipher(text, shift):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if isinstance(shift, bool) or not isinstance(shift, int):
        raise TypeError("shift must be an integer")
    pieces = []
    index = 0
    while index < len(text):
        pieces.append(transform_char(text[index], shift))
        index += 1
    return "".join(pieces)


def parse_shift(token):
    token = token.strip()
    if token == "":
        raise ValueError("shift is missing")
    negative = False
    if token[0] == '-':
        negative = True
        token = token[1:]
    elif token[0] == '+':
        token = token[1:]
    if not token.isdigit():
        raise ValueError("shift must be an integer, got %r" % token)
    value = int(token)
    if negative:
        return -value
    return value


def report(original, shift):
    encoded = cipher(original, shift)
    changed = sum(1 for a, b in zip(original, encoded) if a != b)
    return "%s -> %s  (shift=%d, %d of %d characters changed)" % (
        original, encoded, shift, changed, len(original))


def main(argv):
    shift = 3
    if len(argv) > 1:
        shift = parse_shift(argv[1])
    lines = [line.rstrip("\n") for line in sys.stdin]
    if not lines:
        lines = ["Attack at dawn, 5 units!"]
    for line in lines:
        if line.strip() == "":
            continue
        print(report(line, shift))


main(sys.argv)

