LETTER_BONUS_ALIASES = {
    "": "normal",
    "-": "normal",
    "plain": "normal",
    "dl": "double letter",
    "tl": "triple letter",
    "dw": "double word",
    "tw": "triple word",
}
VALID_SQUARES = ("normal", "double letter", "triple letter", "double word", "triple word")


def letter_value(letter):
    """Base Scrabble value of a single letter."""
    ch = letter.lower()
    if len(ch) != 1 or not ch.isalpha():
        raise ValueError("not a single letter: %r" % letter)
    if ch in "aeiou":
        return 1
    elif ch in "zq":
        return 10
    elif ch in "dg":
        return 2
    elif ch in "bcmp":
        return 3
    elif ch in "fhvwy":
        return 4
    elif ch == "k":
        return 5
    elif ch in "jx":
        return 8
    return 1


def normalize_square(square):
    """Turn a square description into one of VALID_SQUARES."""
    key = square.strip().lower().replace("_", " ").replace("-", " ")
    while "  " in key:
        key = key.replace("  ", " ")
    if key in LETTER_BONUS_ALIASES:
        return LETTER_BONUS_ALIASES[key]
    elif key in VALID_SQUARES:
        return key
    raise ValueError("unknown square type: %r" % square)


def score(word, squares):
    """Score `word` where squares[i] is the tile under word[i]."""
    if len(squares) != len(word):
        raise ValueError("need one square per letter")
    total = 0
    word_multiplier = 1
    index = 0
