HOME_COUNTRY = "US"
HIGH_RISK_COUNTRIES = {"NG", "RU", "KP", "IR", "VE"}

BLOCKED = "blocked"
REVIEW = "review"
APPROVED = "approved"


def normalize_location(location):
    """Validate and canonicalise a two letter country code."""
    if not isinstance(location, str):
        raise ValueError("location must be a string country code")
    code = location.strip().upper()
    if len(code) != 2:
        raise ValueError("location must be exactly two letters: %r" % location)
    if not code.isalpha():
        raise ValueError("location must contain letters only: %r" % location)
    return code


def normalize_time(time):
    """Validate the transaction hour and return it as an int."""
    if isinstance(time, bool) or not isinstance(time, int):
        raise ValueError("time must be an integer hour")
    if time < 0 or time > 23:
        raise ValueError("time must be an hour between 0 and 23: %r" % time)
    return time


def normalize_amount(amount):
    """Validate the transaction amount and return it as a float."""
    if isinstance(amount, bool) or not isinstance(amount, (int, float)):
        raise ValueError("amount must be a number")
    value = float(amount)
    if value < 0:
        raise ValueError("amount must not be negative: %r" % amount)
    return value


def threat_score(amount, location, time):
    """Add up the risk points for one transaction."""
    score = 0
    if amount > 1000:
        score += 3
    if amount < 1:
        score += 1
    if location != HOME_COUNTRY:
        score += 4
    if location in HIGH_RISK_COUNTRIES:
        score += 2
    if time < 4:
        score += 3
    return score


def detect(amount, location, time):
    """Return blocked, review or approved for a single transaction."""
    value = normalize_amount(amount)
    code = normalize_location(location)
    hour = normalize_time(time)
    score = threat_score(value, code, hour)
    if score >= 5:
        return BLOCKED
    elif score >= 3:
        return REVIEW
    return APPROVED


def format_row(amount, location, time, verdict):
    return "%10.2f  %-4s %02d:00  %s" % (amount, location, time, verdict)


def main():
    transactions = [
        (2500.00, "us", 14),
        (0.50, "US", 9),
        (75.00, "de", 11),
        (40.00, "RU", 2),
        (120.00, "US", 3),
        (10.00, "USA", 8),
        (60.00, "FR", 30),
    ]
    index = 0
    while index < len(transactions):
        amount, location, time = transactions[index]
        try:
            verdict = detect(amount, location, time)
        except ValueError as error:
            print("rejected input #%d: %s" % (index + 1, error))
        else:
            print(format_row(amount, location.upper(), time, verdict))
        index += 1


main()

