EXPECTED_DROP = 1.5
HISTORY_LIMIT = 5

_oxygen_history = []


def record_oxygen(level):
    """Keep a short rolling window of oxygen readings."""
    _oxygen_history.append(level)
    while len(_oxygen_history) > HISTORY_LIMIT:
        _oxygen_history.pop(0)


def oxygen_drop_rate():
    """Percentage points lost since the previous reading (0 if rising)."""
    if len(_oxygen_history) < 2:
        return 0.0
    drop = _oxygen_history[-2] - _oxygen_history[-1]
    if drop < 0:
        return 0.0
    return drop


def validate_reading(oxygen, power, crew):
    if not isinstance(crew, int):
        raise TypeError("crew must be an integer")
    elif crew < 0:
        raise ValueError("crew cannot be negative")
    if oxygen < 0 or oxygen > 100:
        raise ValueError("oxygen must be a percentage")
    elif power < 0 or power > 100:
        raise ValueError("power must be a percentage")


def monitor(oxygen, power, crew):
    validate_reading(oxygen, power, crew)
    record_oxygen(oxygen)
    if crew == 0:
        return "STANDBY: no crew aboard, switching to standby mode"
    elif oxygen < 10 and power < 10:
        return "EVACUATION: oxygen and power critical, evacuation protocols initiated"
    elif oxygen < 20:
        return "CRITICAL: oxygen below 20%, critical alarm triggered"
    elif power < 15:
        return "WARNING: power below 15%, non essential systems off"
    elif oxygen_drop_rate() > EXPECTED_DROP and crew > 2:
        return "CAUTION: oxygen dropping fast, backup scrubbers activated"
    elif power > 90:
        return "CHARGING: emergency batteries charging"
    elif oxygen > 80 and power > 80:
        return "NOMINAL: all systems nominal"
    return "STABLE: systems within operating range"


def severity_mark(status):
    if status.startswith("EVACUATION"):
        return "!!!"
    elif status.startswith("CRITICAL"):
        return "!! "
    elif status.startswith("STANDBY"):
        return "-- "
    return "   "


def format_report(tick, oxygen, power, crew, status):
    return "%s[%02d] O2=%5.1f%% PWR=%5.1f%% crew=%d -> %s" % (
        severity_mark(status), tick, oxygen, power, crew, status)


