    readings = [
        (95.0, 96.0, 4),
        (93.0, 88.0, 4),
        (89.5, 85.0, 4),
        (84.0, 60.0, 3),
        (18.0, 40.0, 3),
        (9.0, 8.0, 2),
        (50.0, 50.0, 0),
    ]
