VALID_ABO = ("A", "B", "AB", "O")
POSITIVE_WORDS = ("+", "pos", "positive")
NEGATIVE_WORDS = ("-", "neg", "negative")


def normalize_abo(value):
    if not isinstance(value, str):
        raise TypeError("ABO group must be given as text, got %r" % (value,))
    cleaned = value.strip().upper()
    if cleaned not in VALID_ABO:
        raise ValueError("unknown ABO group: %r" % (value,))
    return cleaned


def normalize_rh(value):
    if not isinstance(value, str):
        raise TypeError("rh factor must be given as text, got %r" % (value,))
    cleaned = value.strip().lower()
    if cleaned in POSITIVE_WORDS:
        return "+"
    elif cleaned in NEGATIVE_WORDS:
        return "-"
    raise ValueError("unknown rh factor: %r" % (value,))


def abo_compatible(donor, recipient):
    if recipient == "AB":
        return True
    elif recipient == "O":
        return donor == "O"
    elif recipient == "A":
        return donor in ("A", "O")
    return donor in ("B", "O")


def rh_compatible(donor, recipient):
    if recipient == "+":
        return True
    return donor == "-"


def transfuse(requests):
    results = []
    index = 0
    while index < len(requests):
        request = requests[index]
        if len(request) != 4:
            raise ValueError("request %d needs exactly 4 fields" % index)
        donor_abo = normalize_abo(request[0])
        donor_rh = normalize_rh(request[1])
        recipient_abo = normalize_abo(request[2])
        recipient_rh = normalize_rh(request[3])
        if donor_abo == "O" and donor_rh == "-":
            results.append(True)
        elif recipient_abo == "AB" and recipient_rh == "+":
            results.append(True)
        else:
            abo_ok = abo_compatible(donor_abo, recipient_abo)
            rh_ok = rh_compatible(donor_rh, recipient_rh)
            results.append(abo_ok and rh_ok)
        index += 1
    return results


def parse_request(line):
    fields = line.replace(",", " ").split()
    if len(fields) != 4:
        raise ValueError("cannot parse request: %r" % (line,))
    return tuple(fields)


def format_report(requests, results):
    lines = []
    for request, safe in zip(requests, results):
        donor = "%s%s" % (normalize_abo(request[0]), normalize_rh(request[1]))
        recipient = "%s%s" % (normalize_abo(request[2]), normalize_rh(request[3]))
        if safe:
            verdict = "SAFE"
        else:
            verdict = "UNSAFE"
        lines.append("%-4s -> %-4s : %s" % (donor, recipient, verdict))
    return "\n".join(lines)


def main():
    raw = ["O, negative, A, positive", "A neg AB pos", "B + B -", "AB, +, O, -",
