def classify_gradient(gradient):
    if gradient >= 8.0:
        return "steep uphill"
    elif gradient > 0.5:
        return "uphill"
    elif gradient < -0.5:
        return "downhill"
    return "flat"


def validate_state(state):
    if len(state) != 5:
        raise ValueError("each state needs cadence, gradient, speed, terrain, posture")
    cadence, gradient, speed, terrain, posture = state
    if cadence < 0:
        raise ValueError("cadence cannot be negative")
    elif speed < 0:
        raise ValueError("speed cannot be negative")
    return cadence, float(gradient), float(speed), terrain.strip().lower(), posture.strip().lower()


def advise(metrics):
    actions = []
    previous_speed = None
    index = 0
    while index < len(metrics):
        cadence, gradient, speed, terrain, posture = validate_state(metrics[index])
        slope = classify_gradient(gradient)
        dropping = previous_speed is not None and previous_speed - speed >= 3.0
        if posture == "sprinting":
            action = "shift to highest gear immediately"
        elif posture == "standing":
            action = "maintain current gear"
        elif cadence > 90 and slope == "flat":
            action = "shift up one gear"
        elif cadence < 70 and slope == "uphill":
            action = "shift down one gear"
        elif speed > 20 and slope == "downhill":
            action = "shift up two gears"
        elif slope == "steep uphill" and dropping:
            action = "shift front derailleur down"
        elif speed < 5 and posture == "approaching stop":
            action = "shift down to lowest gear"
        elif terrain == "gravel" and speed > 15:
            action = "shift down once for better torque"
        elif terrain == "crosswind":
            action = "shift down to maintain control"
        else:
            action = "hold current gear"
        actions.append(action)
        previous_speed = speed
        index += 1
    return actions


def format_report(metrics, actions):
    if len(metrics) != len(actions):
        raise ValueError("metrics and actions must have the same length")
    lines = []
    for row, action in enumerate(actions):
        cadence, gradient, speed, terrain, posture = validate_state(metrics[row])
        lines.append("%2d) cad=%3d grad=%+5.1f%% (%-12s) spd=%5.1f %s/%s -> %s"
                     % (row + 1, cadence, gradient, classify_gradient(gradient),
                        speed, terrain, posture, action))
    return "\n".join(lines)


