STANDARD_COLORS = {"black", "black and tan", "fawn", "brindle", "white", "red"}


def parse_dog(entry):
    """Normalise one competitor record into a list of comparable fields."""
    if len(entry) != 8:
        raise ValueError("each dog needs 8 attributes")
    height, weight, coat, gait, teeth, ears, tail, behavior = entry
    if height <= 0 or weight <= 0:
        raise ValueError("height and weight must be positive")
    text = [coat, gait, teeth, ears, tail, behavior]
    cleaned = [field.strip().lower() for field in text]
    return [float(height), float(weight)] + cleaned


def evaluate(entry):
    """Return (score, faults) for a single dog."""
    height, weight, coat, gait, teeth, ears, tail, behavior = parse_dog(entry)
    faults = []
    if behavior == "aggressive":
        faults.append("DQ: aggression toward the judge")
        return 0, faults
    if coat not in STANDARD_COLORS:
        faults.append("DQ: non-standard coat color (" + coat + ")")
        return 0, faults
    score = 100
    if height > 20:
        score -= 5
        faults.append("oversize: -5")
    if weight < 30:
        score -= 3
        faults.append("underweight: -3")
    if gait == "pacing":
        score -= 10
        faults.append("movement fault, pacing: -10")
    if teeth == "overshot":
        score -= 2
        faults.append("overshot bite: -2")
    elif teeth == "undershot":
        score -= 8
        faults.append("major fault, undershot bite: -8")
    if ears != "erect":
        score -= 4
        faults.append("ears not erect: -4")
    if tail == "docked improperly":
        score -= 6
        faults.append("improper tail dock: -6")
    return score, faults


def judge(dogs):
    scores = []
    index = 0
    while index < len(dogs):
        scores.append(evaluate(dogs[index])[0])
        index += 1
    return scores


def format_report(dogs):
    lines = []
    index = 0
    while index < len(dogs):
        score, faults = evaluate(dogs[index])
        label = "Dog " + str(index + 1)
        if score == 0:
            lines.append(label + ": DISQUALIFIED - " + faults[0])
        elif not faults:
            lines.append(label + ": 100 - flawless specimen")
        else:
            lines.append(label + ": " + str(score) + " - " + "; ".join(faults))
        index += 1
    return lines


def main():
    ring = [
        (19.0, 34.0, "Black", "trotting", "scissor", "erect", "natural", "calm"),
        (22.5, 28.0, "fawn", "pacing", "undershot", "dropped", "docked improperly", "calm"),
        (18.0, 31.0, "merle", "trotting", "scissor", "erect", "natural", "calm"),
        (20.5, 40.0, "brindle", "trotting", "overshot", "erect", "natural", "aggressive"),
    ]
    for line in format_report(ring):
        print(line)
    print("Scores:", judge(ring))


main()

