import sys

NOTE_NAMES = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]


def mode_intervals(mode):
    """Return the seven ascending intervals of the requested mode."""
    if mode == "major":
        return [2, 2, 1, 2, 2, 2, 1]
    elif mode == "natural minor":
        return [2, 1, 2, 2, 1, 2, 2]
    elif mode == "harmonic minor":
        pattern = [2, 1, 2, 2, 1, 2, 2]
        pattern[6] += 1
        return pattern
    elif mode == "melodic minor ascending":
        pattern = [2, 1, 2, 2, 1, 2, 2]
        pattern[5] += 1
        pattern[6] += 1
        return pattern
    elif mode == "dorian":
        return [2, 1, 2, 2, 2, 1, 2]
    elif mode == "phrygian":
        return [1, 2, 2, 2, 1, 2, 2]
    elif mode == "lydian":
        return [2, 2, 2, 1, 2, 2, 1]
    raise ValueError("unknown mode: %r" % (mode,))


def generate(parameters):
    """Build an eight note scale from (starting note number, mode)."""
    if not isinstance(parameters, tuple):
        raise TypeError("parameters must be a tuple")
    if len(parameters) != 2:
        raise ValueError("parameters must hold a note number and a mode")
    start, mode = parameters
    if not isinstance(start, int):
        raise TypeError("the starting note must be an integer")
    if start < 0:
        raise ValueError("the starting note must not be negative")
    intervals = mode_intervals(mode)
    notes = [start]
    step = 0
    while step < 7:
        notes.append(notes[-1] + intervals[step])
        step += 1
    return notes


def note_name(number):
    """Name a MIDI style note number, e.g. 60 -> C4."""
    return NOTE_NAMES[number % 12] + str(number // 12 - 1)


def intervals_between(notes):
    gaps = []
    index = 1
    while index < len(notes):
        gaps.append(notes[index] - notes[index - 1])
        index += 1
    return gaps


def format_scale(parameters):
    notes = generate(parameters)
    names = " ".join(note_name(note) for note in notes)
    steps = "-".join(str(gap) for gap in intervals_between(notes))
    line = "%-24s %-30s %s" % (parameters[1], names, steps)
    span = notes[-1] - notes[0]
    if span != 12:
        line += "  [spans %d semitones]" % span
    return line


def main():
    if len(sys.argv) == 3:
        cases = [(int(sys.argv[1]), sys.argv[2])]
    else:
        cases = [(60, "major"), (57, "natural minor"), (57, "harmonic minor"),
                 (57, "melodic minor ascending"), (62, "dorian"),
                 (64, "phrygian"), (65, "lydian")]
    for case in cases:
        print(format_scale(case))


main()

