text_nat:
MAX_SAFE_WIND = 20.0
MIN_AIRSPACE_DISTANCE = 100.0
LOW_BATTERY = 15.0
CRITICAL_BATTERY = 5.0
HEAVY_PAYLOAD = 4.0
FAST_DRAIN = 2.0
MIN_GPS_STRENGTH = 3
MAX_MOTOR_TEMP = 85.0


def parse_frame(frame):
    """Unpack one telemetry frame, allowing an optional collision-sensor flag."""
    if not isinstance(frame, (tuple, list)):
        raise TypeError("telemetry frame must be a tuple or list")
    if len(frame) < 6:
        raise ValueError("telemetry frame needs at least 6 readings")
    battery, wind, distance, payload, gps, motor = frame[:6]
    collision = False
    if len(frame) > 6:
        collision = bool(frame[6])
    return float(battery), float(wind), float(distance), float(payload), float(gps), float(motor), collision


def control(telemetry):
    """Return the list of safety commands generated for the telemetry stream."""
    commands = []
    previous_battery = None
    index = 0
    while index < len(telemetry):
        battery, wind, distance, payload, gps, motor, collision = parse_frame(telemetry[index])
        drain = 0.0
        if previous_battery is not None and previous_battery > battery:
            drain = previous_battery - battery
        previous_battery = battery
        index += 1
        if battery < CRITICAL_BATTERY:
            commands.append("EMERGENCY LAND")
            continue
        elif battery < LOW_BATTERY:
            commands.append("RETURN TO HOME")
        if wind > MAX_SAFE_WIND:
            commands.append("REDUCE ALTITUDE")
        if distance < MIN_AIRSPACE_DISTANCE:
            commands.append("REVERSE COURSE")
        if payload > HEAVY_PAYLOAD and drain > FAST_DRAIN:
            commands.append("REDUCE SPEED")
        if gps < MIN_GPS_STRENGTH:
            commands.append("HOVER IN PLACE")
        if collision:
            commands.append("EVADE UPWARD")
        if motor > MAX_MOTOR_TEMP:
            commands.append("REDUCE THROTTLE")
    return commands


def summarize(commands):
    """Build a human readable report of how often each command was issued."""
    counts = {}
    for command in commands:
        if command not in counts:
            counts[command] = 1
        else:
            counts[command] += 1
    lines = []
    if not commands:
        lines.append("no safety commands issued")
    for command in sorted(counts):
        lines.append("%-16s x%d" % (command, counts[command]))
    return "\n".join(lines)


def main():
    telemetry = [
        (92.0, 8.0, 900.0, 5.5, 9, 61.0, False),
