    if depth < 0:
        raise ValueError("road %d has a negative snow depth" % index)
    if not isinstance(hour, int):
        raise TypeError("road %d has a non-integer hour" % index)
    if hour < 0 or hour > 23:
        raise ValueError("road %d has an hour outside 0-23" % index)
