RING_VALUES = {"x": 10, "inner gold": 10, "outer gold": 9, "inner red": 8,
               "outer red": 7, "inner blue": 6, "outer blue": 5, "miss": 0}
SEQUENCE_WORDS = {"out of sequence", "sequence", "early"}
BOUNCE_WORDS = {"bounce", "bouncer", "bounce out"}


def normalize_ring(ring):
    key = ring.strip().lower().replace("-", " ")
    if (key.endswith(" ring")):
        key = key[:-5].strip()
    if (key == "center" or key == "centre"):
        key = "x"
    if (key not in RING_VALUES):
        raise ValueError("unknown ring: " + ring)
    return key


def normalize_penalties(penalties):
    if (penalties is None):
        items = []
    elif (isinstance(penalties, str)):
        items = penalties.split("+")
    else:
        items = list(penalties)
    tags = set()
    for item in items:
        tag = str(item).strip().lower().replace("_", " ")
        if (tag == "" or tag == "none"):
            continue
        elif (tag in SEQUENCE_WORDS):
            tags.add("out of sequence")
        elif (tag in BOUNCE_WORDS):
            tags.add("bounce")
        else:
            raise ValueError("unknown penalty: " + tag)
    return tags


def score_arrow(ring, line_breaker):
    key = normalize_ring(ring)
    points = RING_VALUES[key]
    if (line_breaker and key != "miss"):
        points += 1
        if (points > 10):
            points = 10
    return points, key == "x"


def tally(arrows):
    total = 0
    x_count = 0
    reshoots = []
    index = 0
    while (index < len(arrows)):
        ring, line_breaker, penalties = arrows[index]
        index += 1
        tags = normalize_penalties(penalties)
        if ("bounce" in tags):
            reshoots.append(index)
            continue
        points, is_x = score_arrow(ring, line_breaker)
        if (is_x):
            x_count += 1
        if ("out of sequence" in tags):
            points -= 2
        total += points
    return total, x_count, reshoots


def evaluate(arrows):
