    return result[0], result[1]


def format_report(arrows):
    total, x_count, reshoots = tally(arrows)
    report = ["arrows shot: %d" % len(arrows), "total score: %d" % total,
              "x ring hits: %d" % x_count]
    if (reshoots):
        report.append("re-shoot arrows: " + ", ".join(str(n) for n in reshoots))
    else:
        report.append("re-shoot arrows: none")
    return "\n".join(report)


