def validate_throw(throw):
    target, multiplier = throw
    if target == 25 or target == 50:
        if multiplier != 1:
            raise ValueError("bullseye segments only allow a multiplier of one")
    elif 1 <= target <= 20:
        if multiplier < 1 or multiplier > 3:
            raise ValueError("standard segments allow multipliers one to three")
    else:
        raise ValueError("unknown target segment: {0}".format(target))
    return target, multiplier


def is_finishing_throw(target, multiplier):
    if multiplier == 2:
        return True
    elif target == 50:
        return True
    return False


def score(throws):
    current = START_SCORE
    index = 0
    while index < len(throws):
        turn_start = current
        turn_end = min(index + 3, len(throws))
        while index < turn_end:
            target, multiplier = validate_throw(throws[index])
            current -= target * multiplier
            if current == 0 and is_finishing_throw(target, multiplier):
                return WIN_MESSAGE
            elif current <= 1:
                current = turn_start
                index = turn_end
