PLAYER_NAMES = ("player one", "player two")
POINT_NAMES = ("love", "fifteen", "thirty", "forty")


def parse_point(label):
    """Return 0 for a point won by player one, 1 for player two."""
    if not isinstance(label, str):
        raise TypeError("each point must be a string, got " + type(label).__name__)
    key = " ".join(label.strip().lower().split())
    index = 0
    while index < len(PLAYER_NAMES):
        if key == PLAYER_NAMES[index]:
            return index
        index += 1
    raise ValueError("unknown player: " + repr(label))


def point_name(count):
    """Name of a raw point count below deuce (0..3), clamped at forty."""
    if count >= len(POINT_NAMES):
        return POINT_NAMES[-1]
    return POINT_NAMES[count]


def is_finished(scores):
    one, two = scores
    if one < 4 and two < 4:
        return False
    return abs(one - two) >= 2


def describe(scores):
    one, two = scores
    lead = one - two
    if one >= 4 or two >= 4:
        if lead >= 2:
            return "player one wins"
        elif lead <= -2:
            return "player two wins"
        elif lead == 1:
            return "advantage player one"
        elif lead == -1:
            return "advantage player two"
        return "deuce"
    elif one == 3 and two == 3:
        return "deuce"
    return point_name(one) + " to " + point_name(two)


def track(points):
    if not isinstance(points, list):
        raise TypeError("points must be a list of strings")
    scores = [0, 0]
    index = 0
    while index < len(points):
        if is_finished(scores):
            raise ValueError("point played after the game was already won")
        scores[parse_point(points[index])] += 1
        index += 1
    return describe(scores)


def format_report(points):
    """One line per point, showing the running state of the game."""
    lines = []
    played = []
    for label in points:
        winner = PLAYER_NAMES[parse_point(label)]
        played.append(label)
        lines.append("%2d. %-10s -> %s" % (len(played), winner, track(played)))
    return "\n".join(lines)


def main():
    matches = [
        ["player one", "player one", "player one", "player one"],
        ["player one", "player two", "player one", "player two"],
        ["player one", "player two", "player one", "player two",
         "player one", "player two", "player two", "player two"],
    ]
    for sequence in matches:
        print(format_report(sequence))
        print("final: " + track(sequence))
        print()


main()

