import sys

POINTS = {
    "try": 5,
    "conversion": 2,
    "penalty kick": 3,
    "penalty": 3,
    "drop goal": 3,
    "yellow card": -1,
    "red card": -3,
}


def normalize_event(event):
    """Validate a raw (team, event type) pair and return it in canonical form."""
    if len(event) != 2:
        raise ValueError("each event needs a team and an event type: %r" % (event,))
    team, kind = event
    if team not in (1, 2):
        raise ValueError("team must be 1 or 2, got %r" % (team,))
    name = " ".join(str(kind).lower().split())
    if name not in POINTS:
        raise ValueError("unknown event type: %r" % (kind,))
    return team, name


def score(events):
    """Return the final (team one, team two) score for a list of scoring events."""
    totals = {1: 0, 2: 0}
    try_scorer = None
    index = 0
    while index < len(events):
        team, kind = normalize_event(events[index])
        if kind != "conversion":
            totals[team] += POINTS[kind]
        elif try_scorer == team:
            totals[team] += POINTS[kind]
        if kind == "try":
            try_scorer = team
        else:
            try_scorer = None
        if totals[team] < 0:
            totals[team] = 0
        index += 1
    return totals[1], totals[2]


def parse_line(line):
    """Turn a '<team> <event type>' text line into an event tuple, or None if blank."""
    text = line.strip()
    if not text:
        return None
    parts = text.split(None, 1)
    if len(parts) != 2:
        raise ValueError("expected '<team> <event type>', got %r" % (text,))
    if not parts[0].isdigit():
        raise ValueError("team must be numeric, got %r" % (parts[0],))
    return int(parts[0]), parts[1]


def describe(team_one, team_two):
    if team_one > team_two:
        return "Team one wins %d-%d" % (team_one, team_two)
    elif team_two > team_one:
        return "Team two wins %d-%d" % (team_two, team_one)
    return "Draw %d-%d" % (team_one, team_two)


def main():
    events = []
    for line in sys.stdin:
        event = parse_line(line)
        if event is not None:
            events.append(event)
    team_one, team_two = score(events)
    print("Team one: %d" % team_one)
    print("Team two: %d" % team_two)
    print(describe(team_one, team_two))


main()

