BASE_PRICE = 100.0
SEASONS = ("peak", "regular", "spring")


def validate(attributes):
    if len(attributes) != 5:
        raise ValueError("expected [age, season, days_ahead, resident, student]")
    age, season, days_ahead = attributes[0], attributes[1], attributes[2]
    if not isinstance(age, int):
        raise TypeError("age must be an integer")
    elif age < 0 or age > 120:
        raise ValueError("age out of range")
    if season not in SEASONS:
        raise ValueError("unknown season: %r" % (season,))
    if not isinstance(days_ahead, int):
        raise TypeError("days booked in advance must be an integer")
    elif days_ahead < 0:
        raise ValueError("days booked in advance cannot be negative")


def age_factor(age):
    if age < 12 or age > 65:
        return 0.5
    return 1.0


def season_adjust(subtotal, season):
    if season == "peak":
        return subtotal + 20.0
    elif season == "spring":
        return subtotal - 10.0
    return subtotal


def advance_adjust(subtotal, days_ahead):
    if days_ahead > 30:
        return subtotal * 0.8
    elif days_ahead >= 7:
        return subtotal * 0.9
    return subtotal


def status_adjust(subtotal, resident, student):
    if resident:
        return subtotal - 15.0
    elif student:
        return subtotal - 10.0
    return subtotal


def price(attributes):
    validate(attributes)
    age, season, days_ahead, resident, student = attributes
    total = BASE_PRICE * age_factor(age)
    total = season_adjust(total, season)
    total = advance_adjust(total, days_ahead)
    total = status_adjust(total, resident, student)
    return int(total + 0.5)


def format_receipt(attributes):
    age, season, days_ahead, resident, student = attributes
    if age < 12:
        category = "child"
    elif age > 65:
        category = "senior"
    else:
        category = "adult"
    notes = [category, season]
    if days_ahead > 30:
        notes.append("early booking")
    elif days_ahead >= 7:
        notes.append("advance booking")
    if resident:
        notes.append("resident")
    elif student:
        notes.append("student")
    return "%-38s $%3d" % (", ".join(notes), price(attributes))


def main():
    bookings = [
        [34, "peak", 45, False, False],
        [8, "spring", 3, True, False],
        [70, "regular", 10, False, True],
        [21, "peak", 0, True, True],
    ]
    index = 0
    while index < len(bookings):
        print(format_receipt(bookings[index]))
        index += 1


main()

