MONTH_NAMES = {
    "january": 1, "february": 2, "march": 3, "april": 4,
    "may": 5, "june": 6, "july": 7, "august": 8,
    "september": 9, "october": 10, "november": 11, "december": 12,
}


def parse_month(value):
    """Turn a month given as a number, numeric string or name into 1..12."""
    if isinstance(value, int):
        return value
    text = str(value).strip().lower()
    if text in MONTH_NAMES:
        return MONTH_NAMES[text]
    elif text.isdigit():
        return int(text)
    return 0


def validate(catch):
    """Return 'approved' or the reason the catch must be released."""
    if len(catch) != 5:
        return "invalid catch"
    species = str(catch[0]).strip().lower()
    length = catch[1]
    month = parse_month(catch[2])
    location = str(catch[3]).strip().lower()
    tier = str(catch[4]).strip().lower()
    if month < 1 or month > 12:
