RATINGS = {"laser": 0.9, "catamaran": 0.8, "dinghy": 1.1}
TRUE_WORDS = {"yes", "y", "true", "1"}
FALSE_WORDS = {"no", "n", "false", "0"}


def to_flag(token):
    word = token.strip().lower()
    if word in TRUE_WORDS:
        return True
    elif word in FALSE_WORDS:
        return False
    raise ValueError("cannot read false-start flag: " + token)


def parse_entry(line):
    fields = [part.strip() for part in line.split(",")]
    if len(fields) != 5:
        raise ValueError("expected 5 fields, got " + str(len(fields)))
    return [fields[0], float(fields[1]), float(fields[2]), to_flag(fields[3]), int(fields[4])]


def read_entries(lines):
    entries = []
    index = 0
    while index < len(lines):
        line = lines[index].strip()
        index += 1
        if not line:
            continue
        entries.append(parse_entry(line))
    return entries


def handicap(data):
    if len(data) != 5:
        raise ValueError("a race entry needs exactly 5 values")
    boat_class, elapsed, wind, false_start, buoys = data
    if elapsed < 0:
        raise ValueError("elapsed time cannot be negative")
    if buoys < 0:
        raise ValueError("buoy count cannot be negative")
    time = float(elapsed)
    name = str(boat_class).strip().lower()
    if name in RATINGS:
        time *= RATINGS[name]
    if wind < 5:
        time *= 1.05
    elif wind > 20:
        time *= 0.95
    time += 5.0 * buoys
    if false_start:
        time += 10.0
    return round(time, 1)


def leaderboard(entries):
    scored = [(handicap(entry), entry[0]) for entry in entries]
    scored.sort(key=lambda item: item[0])
    placed = []
    place = 0
    previous = None
    position = 0
    while position < len(scored):
        corrected, boat_class = scored[position]
        position += 1
        if corrected != previous:
            place = position
            previous = corrected
        placed.append((place, boat_class, corrected))
    return placed


def main():
    lines = [
        "laser, 95, 3.5, no, 0",
        "catamaran, 88, 24, no, 1",
        "dinghy, 101, 12, yes, 2",
        "",
        "keelboat, 97, 18, no, 1",
    ]
    for place, boat_class, corrected in leaderboard(read_entries(lines)):
        print("{0:>2}. {1:<10} {2:>7.1f} min".format(place, boat_class, corrected))


main()

