def parse_telemetry(line):
    """Turn a comma separated telemetry line into a list of five floats."""
    fields = [field.strip() for field in line.split(",")]
    if len(fields) != 5:
        raise ValueError("expected 5 telemetry fields, got %d" % len(fields))
    values = []
    index = 0
    while index < len(fields):
        try:
            values.append(float(fields[index]))
        except ValueError:
            raise ValueError("field %d is not a number: %r" % (index, fields[index]))
        index += 1
    return values


def validate_telemetry(telemetry):
    """Check the reading has five numeric channels and return it as a list."""
    if isinstance(telemetry, str):
        return parse_telemetry(telemetry)
    readings = list(telemetry)
    if len(readings) != 5:
        raise ValueError("telemetry must hold exactly 5 readings")
    position = 0
    while position < 5:
        value = readings[position]
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("reading %d is not a number: %r" % (position, value))
        position += 1
    return readings


def monitor(telemetry):
    """Evaluate spacecraft health and return warnings or a status message."""
    altitude, velocity, temperature, fuel, signal = validate_telemetry(telemetry)
    warnings = []
    if altitude < 50 and velocity > 2000:
        warnings.append("WARNING: velocity too high for altitude")
    if temperature > 1500:
        warnings.append("CRITICAL: heat shield temperature exceeded")
    elif temperature < -50:
        warnings.append("WARNING: heat shield freezing")
    if fuel < 10:
        warnings.append("WARNING: low fuel")
    if signal < 20:
        warnings.append("WARNING: signal loss")
    if not warnings:
        if altitude == 0 and velocity < 10:
            return ["Safe landing achieved"]
        return ["Nominal"]
    return warnings


def format_report(label, messages):
    """Build a numbered, human readable report for one telemetry sample."""
    lines = ["%s:" % label]
    number = 1
    while number <= len(messages):
        lines.append("  %d. %s" % (number, messages[number - 1]))
        number += 1
    if len(messages) > 1:
        lines.append("  -> %d issues detected" % len(messages))
    return "\n".join(lines)


def main():
    samples = [
        "120, 1800, 900, 55, 88",
        "30, 2400, 1600, 8, 12",
        "0, 2, 40, 31, 77",
        "10, 500, -70, 45, 60",
    ]
    for label, sample in enumerate(samples, start=1):
        try:
            messages = monitor(sample)
        except (ValueError, TypeError) as error:
            print("Sample %d rejected: %s" % (label, error))
            continue
        print(format_report("Sample %d" % label, messages))


main()

