MAIN_LANE = 50.0
LOWER_LANE = 40.0
MAX_WEIGHT = 100.0
DECKS = {"main": MAIN_LANE, "lower": LOWER_LANE}


def validate(vehicle):
    if len(vehicle) != 4:
        raise ValueError("a vehicle needs type, length, weight and hazard flag")
    kind, length, weight, hazardous = vehicle
    if length <= 0:
        raise ValueError("vehicle length must be positive")
    elif weight <= 0:
        raise ValueError("vehicle weight must be positive")
    return str(kind).lower(), float(length), float(weight), bool(hazardous)


def required_deck(kind, weight, hazardous):
    if hazardous:
        return "main", True
    elif kind == "truck" and weight > 10.0:
        return "main", True
    elif kind == "car":
        return "lower", False
    return "main", False


def other_deck(deck):
    if deck == "main":
        return "lower"
    return "main"


def fits(used, deck, length):
    return used[deck] + length <= DECKS[deck]


def load(vehicles):
    plan = []
    used = {"main": 0.0, "lower": 0.0}
    total_weight = 0.0
    index = 0
    while index < len(vehicles):
        vehicle = vehicles[index]
        index += 1
        kind, length, weight, hazardous = validate(vehicle)
        if weight > MAX_WEIGHT - total_weight:
            continue
        deck, restricted = required_deck(kind, weight, hazardous)
        if not fits(used, deck, length):
            if restricted:
                continue
            deck = other_deck(deck)
            if not fits(used, deck, length):
                continue
        used[deck] += length
        total_weight += weight
        plan.append((vehicle, deck))
    return plan


def report(vehicles, plan):
    lines = []
    for vehicle, deck in plan:
        lines.append("%-8s %5.1f m %5.1f t -> %s deck" % (vehicle[0], vehicle[1], vehicle[2], deck))
    for deck in ("main", "lower"):
        usage = sum(item[0][1] for item in plan if item[1] == deck)
        lines.append("%s deck: %.1f/%.1f m used" % (deck, usage, DECKS[deck]))
    lines.append("weight: %.1f/%.1f t" % (sum(item[0][2] for item in plan), MAX_WEIGHT))
    rejected = len(vehicles) - len(plan)
    if rejected > 0:
        lines.append("%d vehicle(s) could not be loaded" % rejected)
    return "\n".join(lines)


def main():
    queue = [
        ("car", 4.5, 1.5, False),
        ("truck", 14.0, 22.0, False),
        ("tanker", 12.0, 18.0, True),
        ("car", 4.0, 1.4, False),
        ("bus", 11.0, 12.0, False),
        ("car", 4.2, 1.6, False),
        ("truck", 15.0, 30.0, False),
        ("van", 6.0, 3.0, False),
    ]
    print(report(queue, load(queue)))


main()

