PACKAGES = ("basic", "standard", "premium")
DIRT_LEVELS = ("low", "medium", "high")
SIZES = ("small", "medium", "large")


def validate_settings(settings):
    """Unpack and check a [package, dirt level, size] triple."""
    if not isinstance(settings, (list, tuple)):
        raise ValueError("settings must be a list of three values")
    if len(settings) != 3:
        raise ValueError("settings must contain package, dirt level and size")
    package, dirt, size = settings
    if package not in PACKAGES:
        raise ValueError("unknown package: %s" % package)
    if dirt not in DIRT_LEVELS:
        raise ValueError("unknown dirt level: %s" % dirt)
    if size not in SIZES:
        raise ValueError("unknown vehicle size: %s" % size)
    return package, dirt, size


def wash(settings):
    """Build the ordered list of washing stages for one vehicle."""
    package, dirt, size = validate_settings(settings)
    stages = ["undercarriage spray"]
    if dirt == "high":
        stages.append("heavy pre-soak")
    elif package != "basic" or dirt != "low" or size != "small":
        stages.append("standard pre-soak")
    stages.append("soap application")
    if size == "large":
        stages.append("extended scrubbing")
    else:
        stages.append("regular scrubbing")
    stages.append("high pressure rinse")
    if package == "standard" or package == "premium":
        stages.append("tire cleaning")
        stages.append("wax application")
    if package == "premium":
        stages.append("ceramic coating")
    if size == "large" or package == "premium":
        stages.append("extended heated dry")
    else:
        stages.append("standard dry")
    return stages


def format_sequence(settings, stages):
    """Render a wash program as a numbered, human readable block."""
    package, dirt, size = settings
    lines = ["%s package / %s dirt / %s vehicle" % (package, dirt, size)]
    number = 1
    while number <= len(stages):
        lines.append("  %d. %s" % (number, stages[number - 1]))
        number += 1
    return "\n".join(lines)


def main():
    queue = [
        ["basic", "low", "small"],
        ["basic", "high", "medium"],
        ["standard", "medium", "large"],
        ["premium", "low", "small"],
        ["deluxe", "low", "small"],
    ]
    total = 0
    while queue:
        settings = queue.pop(0)
        try:
            stages = wash(settings)
        except ValueError as exc:
            print("skipping %r: %s" % (settings, exc))
            continue
        total += len(stages)
        print(format_sequence(settings, stages))
    if total:
        print("total stages scheduled: %d" % total)


if __name__ == "__main__":
    main()

