text_nat:
def normalize_order(order):
    """Validate a raw order and return (color, finish, litres)."""
    if len(order) != 3:
        raise ValueError("an order needs a colour, a finish and a volume")
    color, finish, liters = order
    color = str(color).strip().lower()
    finish = str(finish).strip().lower()
    liters = float(liters)
    if not color:
        raise ValueError("missing colour name")
    if liters <= 0:
        raise ValueError("requested volume must be positive")
    return color, finish, liters


def finish_additive(finish):
    """Return (additive name, fraction of the volume) or None for flat finishes."""
    if finish == "gloss":
        return "gloss additive", 0.10
    elif finish == "matte":
        return "flattening agent", 0.05
    elif finish == "satin":
        return "smoothing agent", 0.02
    return None


def colorant_recipe(color):
    """Return the colorants for a colour as (name, millilitres per litre) pairs."""
    if color == "crimson":
        return [("red colorant", 10.0), ("blue colorant", 2.0)]
    elif color == "mint":
        return [("green colorant", 5.0), ("yellow colorant", 1.0)]
    elif color == "navy":
        return [("blue colorant", 12.0), ("black colorant", 3.0)]
    elif color == "mustard":
        return [("yellow colorant", 8.0), ("brown colorant", 2.0)]
    return []


def dispense(order):
    """Calculate the base paint and colorant volumes (in ml) for one order."""
    color, finish, liters = normalize_order(order)
    base = liters * 1000.0
    ingredients = []
    additive = finish_additive(finish)
    if additive is not None:
        name, fraction = additive
        amount = base * fraction
        base -= amount
        ingredients.append((name, round(amount, 2)))
    factor = 1.0
    if liters > 20:
        factor = 0.95
    colorant_total = 0.0
    for name, per_liter in colorant_recipe(color):
        amount = per_liter * liters * factor
        colorant_total += amount
        ingredients.append((name, round(amount, 2)))
    base -= colorant_total
    return [("base paint", round(base, 2))] + ingredients


def format_report(ticket):
    """Turn a dispensing ticket into an aligned, printable block of text."""
    lines = []
    index = 0
    while index < len(ticket):
        name, milliliters = ticket[index]
        lines.append("{:<18}{:>9.2f} ml".format(name, milliliters))
        index += 1
    total = sum(item[1] for item in ticket)
    lines.append("{:<18}{:>9.2f} ml".format("total", total))
    return "\n".join(lines)


def main():
    queue = [
        ["crimson", "gloss", 4],
        ["mint", "matte", 10],
        ["navy", "satin", 25],
        ["mustard", "flat", 1],
        ["white", "gloss", 0],
    ]
    while queue:
        order = queue.pop(0)
        print("order: {} {} {} L".format(*order))
        try:
            print(format_report(dispense(order)))
        except ValueError as problem:
            print("rejected: {}".format(problem))
        print()


main()

