def parse_parameters(text):
    """Turn a comma separated instrument line into a list of five floats."""
    parts = text.split(",")
    if len(parts) != 5:
        raise ValueError("expected 5 readings, got %d" % len(parts))
    values = []
    index = 0
    while index < len(parts):
        values.append(float(parts[index].strip()))
        index += 1
    return values


def check(parameters):
    """Return the take-off verdict for [main RPM, tail RPM, temp C, oil PSI, wind kt]."""
    if len(parameters) != 5:
        raise ValueError("check() needs exactly 5 parameters")
    main_rpm, tail_rpm, engine_temp, oil_pressure, wind_speed = parameters
    if engine_temp < 40:
        return "WARM UP: engine at %.1f C, warm up before take-off" % engine_temp
    elif engine_temp > 110:
        return "SHUT DOWN: engine overheating at %.1f C" % engine_temp
    elif oil_pressure < 50:
        return "LOW OIL PRESSURE: %.1f PSI, do not take off" % oil_pressure
    elif wind_speed > 35:
        return "WEATHER HOLD: winds at %.1f knots" % wind_speed
    elif main_rpm < 300 or tail_rpm < 1500:
        return "SPOOLING UP: rotors have not reached flight speed"
    elif wind_speed >= 20:
        return "CAUTION: marginal weather, winds at %.1f knots" % wind_speed
    return "CLEAR FOR TAKEOFF"


def severity(message):
    """Classify a verdict message so reports can be sorted and coloured."""
    if message.startswith("CLEAR"):
        return "OK"
    elif message.startswith("CAUTION"):
        return "CAUTION"
    return "NO-GO"


def format_report(label, parameters, message):
    level = severity(message)
    report = "%-9s [%-7s] %s" % (label, level, message)
    if level != "OK":
        report += "\n%-9s  rotors %.0f/%.0f rpm, oil %.0f PSI, wind %.0f kt" % (
            "", parameters[0], parameters[1], parameters[3], parameters[4])
    return report


def main():
    readings = [
