import sys

TARGETS = ("planet", "nebula", "galaxy")
FIELDS = ("target", "tracking", "seeing", "filter", "moon")


def parse_observation(line):
    parts = [item.strip().lower() for item in line.split(",")]
    while parts and parts[-1] == "":
        parts.pop()
    if len(parts) != len(FIELDS):
        raise ValueError("expected %d fields, got %d" % (len(FIELDS), len(parts)))
    if parts[0] not in TARGETS:
        raise ValueError("unknown target type: %s" % parts[0])
    if parts[1] == "":
        raise ValueError("tracking mode must not be empty")
    return parts


def calibrate(observation):
    target, tracking, seeing, installed_filter, moon = parse_observation(",".join(observation))
    instructions = []
    if target == "planet":
        instructions.append("set focal length to long")
        instructions.append("set tracking to planetary")
        required_tracking = "planetary"
    else:
        instructions.append("set focal length to short")
        instructions.append("set tracking to sidereal")
        required_tracking = "sidereal"
    if seeing == "poor":
        instructions.append("activate adaptive optics")
    elif seeing == "excellent":
        instructions.append("bypass adaptive optics")
    if target == "nebula" and installed_filter == "none":
        instructions.append("insert narrowband filter")
    elif target == "planet" and installed_filter == "narrowband":
        instructions.append("switch to color filter")
    if installed_filter == "infrared" and target != "planet":
        instructions.append("remove infrared filter")
    if target == "galaxy" and moon == "full":
        instructions.append("warning: light pollution from full moon")
    if tracking != required_tracking:
        instructions.append("warning: tracking mismatch, %s requested" % tracking)
    return instructions


def format_report(observation, instructions):
    lines = ["observation: " + " | ".join(observation)]
    for number, text in enumerate(instructions, 1):
        if text.startswith("warning:"):
            lines.append("  !! %s" % text[len("warning:"):].strip())
        else:
            lines.append("  %d. %s" % (number, text))
    return "\n".join(lines)


def run(stream):
    reports = []
    while True:
        line = stream.readline()
        if line == "":
            break
        line = line.strip()
        if line == "" or line.startswith("#"):
            continue
        try:
            observation = parse_observation(line)
        except ValueError as problem:
            reports.append("observation: %s\n  !! invalid input: %s" % (line, problem))
            continue
        reports.append(format_report(observation, calibrate(observation)))
    return reports


def main():
    reports = run(sys.stdin)
    if not reports:
        print("no observations supplied")
        return
    print("\n\n".join(reports))


if __name__ == "__main__":
    main()

