VALUES = {
    "red": 1,
    "yellow": 2,
    "green": 3,
    "brown": 4,
    "blue": 5,
    "pink": 6,
    "black": 7,
}


def normalise(name):
    key = name.strip().lower()
    if key not in VALUES:
        raise ValueError("unknown ball colour: %r" % name)
    return key


def parse_break(text):
    tokens = text.replace(",", " ").split()
    if not tokens:
        raise ValueError("a break must contain at least one ball")
    return [normalise(token) for token in tokens]


def score(balls):
    total = 0
    reds = 0
    expect_red = True
    last_colour = VALUES["red"]
    index = 0
    while index < len(balls):
        name = normalise(balls[index])
        if reds < 15 or not expect_red:
            if expect_red:
                if name != "red":
                    break
                reds += 1
            elif name == "red":
                break
            total += VALUES[name]
            expect_red = not expect_red
        else:
            value = VALUES[name]
            if value <= last_colour:
                break
            last_colour = value
            total += value
        index += 1
    return total


def describe(points):
    if points >= 147:
        return "maximum"
    elif points >= 100:
        return "century"
    elif points >= 50:
        return "half-century"
    else:
        return "small break"


def main():
    maximum = "red black " * 15 + "yellow green brown blue pink black"
    breaks = [
        "red",
        "red black red blue red pink",
