import sys

SIDES = ('left', 'right')
KINDS = ('attack', 'parry', 'touch', 'miss', 'off')

def parse_action(action):
    """Turn a phrase such as 'attack left' or 'off target' into (kind, side)."""
    text = ' '.join(str(action).lower().split())
    if text.startswith('off target'):
        kind = 'off'
        side = text[len('off target'):].strip()
    else:
        words = text.split()
        if len(words) != 2:
            raise ValueError('cannot parse action: %r' % action)
        kind, side = words
    if kind not in KINDS:
        raise ValueError('unknown action: %r' % action)
    if side == '':
        side = None
    elif side not in SIDES:
        raise ValueError('unknown fencer: %r' % action)
    return kind, side

def opponent(side):
    if side == 'left':
        return 'right'
    return 'left'

def track(actions):
    row = None
    contested = False
    touched = set()
    index = 0
    while index < len(actions):
        kind, side = parse_action(actions[index])
        if side is None and row is None:
            raise ValueError('action without a fencer: %r' % actions[index])
        elif side is None:
            side = row
        index += 1
        if kind == 'attack':
            if row is None or row == side:
                row = side
            else:
                contested = True
                touched.clear()
        elif kind == 'parry':
            row = side
            contested = False
            touched.clear()
        elif kind == 'touch':
            if contested:
                touched.add(side)
                if len(touched) == 2:
                    return (0, 0)
            elif side == row or row is None:
                if side == 'left':
                    return (1, 0)
                return (0, 1)
        elif contested:
            contested = False
            row = opponent(side)
            touched.clear()
        elif side == row:
            if kind == 'off':
                return (0, 0)
            row = None
    return (0, 0)

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        left, right = track([part.strip() for part in line.split(',')])
        print('%d-%d' % (left, right))

main()

