def validate_element(element):
    """Check one routine entry and return it as a normalised tuple."""
    if len(element) != 4:
        raise ValueError("each element needs a name, base value, GOE and fall flag")
    name, base, goe, fall = element
    if not isinstance(name, str) or not name.strip():
        raise ValueError("element name must be a non-empty string")
    if base < 0:
        raise ValueError("base value cannot be negative: %r" % (base,))
    if goe < -5 or goe > 5:
        raise ValueError("grade of execution must be between -5 and +5")
    return name.strip(), float(base), int(goe), bool(fall)


def element_score(name, base, goe, fall, index, count):
    """Score a single element that sits at `index` in a routine of `count` elements."""
    if "jump" in name.lower() and index > count // 2:
        base *= 1.1
    if fall and goe > -3:
        goe = -3
    if goe > 0:
        score = base + base * 0.1 * goe
    elif goe < 0:
        score = base - base * 0.1 * abs(goe)
    else:
        score = base
    if fall:
        score -= 1.0
    if score < 0:
        score = 0.0
    return score


def evaluate(routine):
    """Total technical score of a figure skating program, rounded to two decimals."""
    count = len(routine)
    total = 0.0
    index = 0
    while index < count:
        name, base, goe, fall = validate_element(routine[index])
        total += element_score(name, base, goe, fall, index, count)
        index += 1
    return round(total, 2)


def format_report(routine):
    """Build a protocol-style table for the routine plus its total score."""
    count = len(routine)
    lines = ["%-22s %6s %5s %8s  %s" % ("ELEMENT", "BASE", "GOE", "SCORE", "NOTE")]
    for index, element in enumerate(routine):
        name, base, goe, fall = validate_element(element)
        score = element_score(name, base, goe, fall, index, count)
        if fall:
            note = "fall (-1.00)"
        elif goe >= 3:
            note = "excellent"
        elif goe <= -3:
            note = "major error"
        else:
            note = ""
        lines.append("%-22s %6.2f %+5d %8.2f  %s" % (name, base, goe, score, note))
    lines.append("%-22s %6s %5s %8.2f" % ("TOTAL", "", "", evaluate(routine)))
    return "\n".join(lines)


def main():
    routine = [
        ("Triple Axel jump", 8.00, 2, False),
        ("Flying Camel Spin", 3.20, 1, False),
        ("Step Sequence", 3.90, 0, False),
        ("Triple Lutz jump", 5.90, -2, True),
        ("Double Toe Loop jump", 1.30, 3, False),
        ("Choreo Sequence", 3.00, -1, False),
    ]
    print(format_report(routine))


main()

