import sys


def validate_scene(scene):
    if len(scene) != 3:
        raise ValueError("a scene needs lux, speed and depth of field")
    lux, speed, depth = scene
    if lux < 0:
        raise ValueError("light level cannot be negative")
    if speed < 0:
        raise ValueError("subject speed cannot be negative")
    if depth not in ("shallow", "deep"):
        raise ValueError("depth of field must be 'shallow' or 'deep'")


def parse_scene(text):
    fields = [field.strip() for field in text.split(",")]
    if len(fields) != 3:
        raise ValueError("expected 'lux, speed, depth'")
    scene = [float(fields[0]), float(fields[1]), fields[2].lower()]
    validate_scene(scene)
    return scene


def advise(scene):
    validate_scene(scene)
    lux, speed, depth = scene
    iso = 100
    aperture = 8.0
    shutter = 1.0 / 200.0
    if speed > 50:
        shutter = 1.0 / 1000.0
        iso = 800
    elif speed >= 10:
        shutter = 1.0 / 500.0
        iso = 400
    elif speed == 0:
        shutter = 1.0 / 50.0
    if depth == "shallow":
        aperture = 2.8
        iso = max(100, iso // 2)
    elif depth == "deep":
        aperture = 16.0
        iso = iso * 2
    if lux < 1000:
        iso = iso * 2
    if lux < 100:
        shutter = 1.0
        aperture = 1.4
    return [iso, aperture, shutter]


def needs_tripod(scene):
    return scene[0] < 100


def describe_shutter(shutter):
    if shutter >= 1:
        return "%g s" % shutter
    return "1/%d s" % round(1.0 / shutter)


def format_advice(scene):
    iso, aperture, shutter = advise(scene)
    parts = ["ISO %d" % iso, "f/%g" % aperture, describe_shutter(shutter)]
    if needs_tripod(scene):
        parts.append("tripod required")
    return ", ".join(parts)


def main():
    lines = sys.stdin.read().splitlines()
    index = 0
    while index < len(lines):
        line = lines[index].strip()
        index += 1
        if not line:
            continue
        try:
            scene = parse_scene(line)
        except ValueError as error:
            print("%s -> error: %s" % (line, error))
            continue
        print("%s -> %s" % (line, format_advice(scene)))


main()

