MANUAL_CHUTE = "MANUAL INSPECTION CHUTE"
OVERSIZED_CHUTE = "OVERSIZED FREIGHT CHUTE"
FRAGILE_BELT = "FRAGILE HANDLING BELT"
UNKNOWN_CHUTE = "UNKNOWN DESTINATION CHUTE"


def _to_number(value, field):
    """Accept a plain number or a string such as '18.5 kg' / '110cm'."""
    if isinstance(value, bool):
        raise ValueError("%s must be numeric" % field)
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip().lower()
    while text and text[-1].isalpha():
        text = text[:-1]
    text = text.strip()
    if not text:
        raise ValueError("%s is missing a numeric value" % field)
    return float(text)


def validate(baggage):
    """Normalise one baggage record into a usable tuple of attributes."""
    if not isinstance(baggage, (list, tuple)):
        raise TypeError("baggage must be a list of six attributes")
    if len(baggage) != 6:
        raise ValueError("baggage needs exactly six attributes")
    code = str(baggage[0]).strip().upper()
    if not code:
        raise ValueError("destination code is empty")
    weight = _to_number(baggage[1], "weight")
    length = _to_number(baggage[2], "length")
    if weight < 0:
        raise ValueError("weight cannot be negative")
    if length <= 0:
        raise ValueError("length must be positive")
    priority = str(baggage[3]).strip().lower()
    scan = str(baggage[5]).strip().lower()
    return code, weight, length, priority, bool(baggage[4]), scan


def route(baggage):
    code, weight, length, priority, fragile, scan = validate(baggage)
    if scan == "fail":
        return MANUAL_CHUTE
    if length > 120 or weight > 32:
        return OVERSIZED_CHUTE
    if fragile:
        return FRAGILE_BELT
    tag = ""
    if priority == "first" or priority == "business":
        tag = "PRIORITY "
    elif priority == "economy" and weight < 10:
        tag = "EXPRESS "
    if code.startswith("L"):
        return tag + "CAROUSEL 1"
    elif code.startswith("D"):
        return tag + "CAROUSEL 2"
    elif code.startswith("I"):
        return tag + "CAROUSEL 3"
    return tag + UNKNOWN_CHUTE


def main():
    queue = [
        ["LHR-201", 8, 70, "economy", False, "pass"],
        ["DFW-118", "15.5 kg", "95 cm", "first", False, "pass"],
        ["IST-770", 41, 110, "business", False, "pass"],
        ["LAX-004", 12, 130, "economy", True, "pass"],
        ["IAD-556", 6, 60, "economy", True, "pass"],
        ["DEN-900", 22, 88, "economy", False, "fail"],
        ["XYZ-001", 19, 80, "business", False, "pass"],
        ["BAD-000", 19, 80, "economy", False],
    ]
    processed = 0
    while queue:
        bag = queue.pop(0)
        try:
            destination = route(bag)
        except (TypeError, ValueError) as error:
            print("%-10s -> REJECTED (%s)" % (bag[0], error))
            continue
        processed += 1
        print("%-10s -> %s" % (bag[0], destination))
    print("routed %d of the presented bags" % processed)


main()

