    if swim_time <= 0:
        raise ValueError("swim time must be positive: %r" % (swim_time,))
    return age, gender.strip().lower(), swim_time


def classify(age, gender, swim_time):
    """Return the wave name for a single validated athlete."""
    if swim_time > 60:
        return "final wave"
    if gender == "male":
        if age < 30:
            if swim_time < 30:
                return "wave one"
        elif age <= 50:
            if swim_time < 35:
                return "wave two"
        else:
