import sys


def parse_bool(text):
    token = text.strip().lower()
    if token in ("true", "yes", "y", "1"):
        return True
    elif token in ("false", "no", "n", "0"):
        return False
    raise ValueError("not a boolean: " + text)


def normalize_echo(echo):
    if not isinstance(echo, str):
        raise TypeError("radar echo must be a string")
    text = echo.strip().lower()
    while "  " in text:
        text = text.replace("  ", " ")
    if text in ("debris ball", "debris_ball", "debrisball"):
        return "debris ball"
    return text


def validate_reading(reading):
    if len(reading) != 3:
        raise ValueError("each reading needs speed, funnel flag and echo type")
    speed = float(reading[0])
    if speed < 0:
        raise ValueError("rotation speed cannot be negative")
    return speed, bool(reading[1]), normalize_echo(reading[2])


def classify(speed, funnel, echo):
    if echo == "debris ball":
        return "catastrophic tornado emergency"
    elif speed > 100 and funnel:
        return "tornado emergency"
    elif speed > 100:
        return "tornado warning"
    elif speed >= 60 and echo == "hook":
        return "tornado warning"
    elif speed >= 60 and echo == "bow":
        return "severe thunderstorm warning"
    elif speed >= 20 and echo == "hook":
        return "severe weather statement"
    elif speed < 60 and funnel:
        return "spotter investigation request"
    elif echo == "clear" and speed < 20:
        return "all clear"
    return "weather watch"


def warn(readings):
    alerts = []
    index = 0
    while index < len(readings):
        speed, funnel, echo = validate_reading(readings[index])
        alerts.append(classify(speed, funnel, echo))
        index += 1
    return alerts


def summarize(alerts):
    counts = {}
    for alert in alerts:
        if alert in counts:
            counts[alert] += 1
        else:
            counts[alert] = 1
    return ["%3d x %s" % (counts[name], name) for name in sorted(counts)]


def parse_reading(line):
    parts = line.split(",")
    if len(parts) != 3:
        raise ValueError("expected 'speed, funnel, echo': " + line)
    return (float(parts[0]), parse_bool(parts[1]), parts[2])


def main():
