    genus, leaf, root, humidity = entry
    if (not isinstance(humidity, (int, float))):
        raise TypeError("humidity must be a number")
    if (humidity < 0 or humidity > 100):
        raise ValueError("humidity must be a percentage between 0 and 100")
    return normalize(genus), normalize(leaf), normalize(root), float(humidity)


def advise(genus, leaf, root, humidity):
    """Return the single care instruction that applies to one orchid."""
    if (root == "mushy"):
        return "unpot and trim dead roots immediately"
    elif (genus == "phalaenopsis" and leaf == "dark green"):
        return "increase light exposure immediately"
    elif (genus == "phalaenopsis" and root == "brown"):
        return "stop watering and apply fungicide"
    elif (genus == "cattleya" and humidity < 40):
        return "add a humidifier and mist daily"
    elif (genus == "cattleya" and leaf == "yellow"):
        return "reduce light exposure"
    elif (genus == "vanda" and root == "silvery"):
        return "water heavily until roots turn green"
    elif (genus == "paphiopedilum" and leaf == "pale"):
        return "apply a weak magnesium fertilizer"
    elif (genus == "dendrobium" and humidity > 80):
        return "increase air circulation to prevent rot"
    return "maintain current care routine"


def guide(orchids):
    """Map a list of orchid records to a list of care instructions."""
    instructions = []
    for entry in orchids:
        genus, leaf, root, humidity = check_entry(entry)
        instructions.append(advise(genus, leaf, root, humidity))
    return instructions


def format_report(orchids, instructions):
    """Build a numbered, human readable care sheet."""
    lines = []
    index = 0
    while (index < len(orchids)):
        genus = normalize(orchids[index][0])
        lines.append("%d. %s: %s" % (index + 1, genus, instructions[index]))
        index += 1
    if (not lines):
        lines.append("no orchids on record")
    return "\n".join(lines)


def main():
    greenhouse = [
        ("phalaenopsis", "dark green", "green", 50),
        ("Phalaenopsis", "light green", "brown", 55),
        ("cattleya", "green", "green", 35),
        ("cattleya", "yellow", "green", 60),
        ("vanda", "green", "silvery", 65),
        ("paphiopedilum", "pale", "green", 70),
        ("dendrobium", "green", "green", 85),
        ("oncidium", "green", "mushy", 60),
        ("oncidium", "green", "green", 60),
    ]
    instructions = guide(greenhouse)
    print(format_report(greenhouse, instructions))
    urgent = [text for text in instructions if text.endswith("immediately")]
    if (urgent):
        print("urgent actions pending: %d" % len(urgent))


if __name__ == "__main__":
    main()

