def normalize_gravity(gravity):
    if not isinstance(gravity, str):
        raise TypeError("gravity must be described with a string")
    return " ".join(gravity.lower().split())


def parse_batch(batch):
    if len(batch) != 4:
        raise ValueError("each batch needs ph, temperature, gravity and days active")
    ph, temp, gravity, days = batch
    if not isinstance(ph, (int, float)):
        raise TypeError("ph level must be numeric")
    elif not isinstance(temp, (int, float)):
        raise TypeError("temperature must be numeric")
    elif not isinstance(days, int):
        raise TypeError("days active must be a whole number")
    elif days < 0:
        raise ValueError("days active cannot be negative")
    return ph, temp, normalize_gravity(gravity), days


def classify(ph, temp, gravity, days):
    if ph < 4 and gravity == "stable":
        return "ready for bottling"
    elif ph > 5 and days > 7:
        return "stalled, add yeast nutrient"
    elif temp > 35 and days > 3:
        return "heat damaged, discard"
    elif temp > 30 and ph < 4:
        return "at risk of fusel alcohols, chill immediately"
    elif temp < 15 and gravity == "dropping slowly":
        return "slow ferment, warm the vessel"
    elif days > 14 and gravity != "stable":
        return "struggling, rouse the yeast"
    elif ph < 3.2:
        return "overly acidic, consider blending"
    elif gravity == "extremely high" and days == 0:
        return "ready to pitch yeast"
    return "actively fermenting"


def validate(batches):
    statuses = []
    index = 0
    while index < len(batches):
        ph, temp, gravity, days = parse_batch(batches[index])
        statuses.append(classify(ph, temp, gravity, days))
        index += 1
    return statuses


def format_report(statuses):
    counts = {}
    for status in statuses:
        counts[status] = counts.get(status, 0) + 1
    lines = []
    for status in sorted(counts):
        amount = counts[status]
        if amount == 1:
            lines.append("1 batch: " + status)
        else:
            lines.append(str(amount) + " batches: " + status)
    return "\n".join(lines)


def main():
    batches = [
        (3.8, 20, "stable", 10),
        (5.4, 22, "dropping slowly", 12),
        (4.5, 38, "dropping slowly", 5),
        (3.9, 33, "dropping fast", 2),
        (4.2, 12, "dropping slowly", 6),
        (4.6, 19, "dropping slowly", 20),
        (3.0, 21, "dropping fast", 4),
        (4.8, 18, "extremely high", 0),
        (4.4, 21, "dropping fast", 3),
    ]
    statuses = validate(batches)
    position = 0
    while position < len(statuses):
        status = statuses[position]
        if status.startswith("heat damaged") or status.startswith("stalled"):
            prefix = "ACTION"
        elif status == "actively fermenting":
            prefix = "OK    "
        else:
            prefix = "CHECK "
        print(prefix, "batch", position + 1, "-", status)
        position += 1
    print()
    print(format_report(statuses))


main()

