DEPTHS = ("shallow", "deep", "very deep")


def _clean(value, field):
    if not isinstance(value, str):
        raise TypeError("%s must be a string, got %r" % (field, value))
    text = value.strip().lower()
    while "  " in text:
        text = text.replace("  ", " ")
    if not text:
        raise ValueError("%s must not be empty" % field)
    return text


def _normalize_job(job):
    if not isinstance(job, tuple):
        raise TypeError("each job must be a tuple, got %r" % (job,))
    if len(job) != 4:
        raise ValueError("each job needs 4 fields, got %d" % len(job))
    soil = _clean(job[0], "soil type")
    depth = _clean(job[1], "digging depth")
    if depth not in DEPTHS:
        raise ValueError("unknown digging depth: %r" % depth)
    return soil, depth, bool(job[2]), bool(job[3])


def choose_attachment(soil, depth, rocks, precision):
    if soil == "frozen":
        return "hydraulic breaker attachment"
    elif soil == "clay" and rocks:
        return "heavy duty rock bucket with teeth"
    elif soil == "clay":
        return "standard digging bucket"
    elif soil == "sand" and depth == "shallow":
        return "wide grading bucket"
    elif soil == "sand" and precision:
        return "tilt bucket"
    elif soil == "gravel" and depth == "shallow":
        return "skeleton sifting bucket"
    elif rocks and precision:
        return "hydraulic thumb attachment"
    elif depth == "very deep" and soil == "loose":
        return "long reach boom extension"
    return "general purpose bucket"


def select(jobs):
    if isinstance(jobs, tuple) or not hasattr(jobs, "__iter__"):
        raise TypeError("jobs must be a list of tuples")
    jobs = list(jobs)
    picks = []
    index = 0
    while index < len(jobs):
        soil, depth, rocks, precision = _normalize_job(jobs[index])
        picks.append(choose_attachment(soil, depth, rocks, precision))
        index += 1
    return picks


def describe(job):
    soil, depth, rocks, precision = _normalize_job(job)
    notes = []
    if rocks:
        notes.append("rocks")
    if precision:
        notes.append("precision")
    if not notes:
        notes.append("no special conditions")
    return "%s soil, %s (%s)" % (soil, depth, ", ".join(notes))


def format_report(jobs):
    picks = select(jobs)
    lines = []
    for job, pick in zip(jobs, picks):
        lines.append("%-42s -> %s" % (describe(job), pick))
    generic = picks.count("general purpose bucket")
    if generic == len(picks):
        lines.append("No specialised attachment matched any job.")
    elif generic > 0:
        lines.append("%d of %d jobs fell back to the general purpose bucket." % (generic, len(picks)))
    else:
        lines.append("Every job matched a specialised attachment.")
    return "\n".join(lines)


def main():
    jobs = [
        ("clay", "deep", True, False),
        ("clay", "shallow", False, False),
        ("sand", "shallow", False, False),
        ("sand", "deep", False, True),
        ("gravel", "shallow", True, False),
        ("loose", "very deep", False, False),
        ("frozen", "deep", True, True),
        ("silt", "deep", True, True),
        ("silt", "deep", False, False),
    ]
    print(format_report(jobs))


main()

