NOTE_BASE = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}


def note_value(note):
    """Return a MIDI-style integer for a note name such as 'C4', 'Eb3' or 'F#5'."""
    text = str(note).strip()
    if not text:
        raise ValueError("empty note name")
    letter = text[0].upper()
    if letter not in NOTE_BASE:
        raise ValueError("unknown note letter: " + text[0])
    semitone = NOTE_BASE[letter]
    index = 1
    while index < len(text) and text[index] in "#b":
        if text[index] == "#":
            semitone += 1
        else:
            semitone -= 1
        index += 1
    octave_text = text[index:]
    if not octave_text.lstrip("-").isdigit():
        raise ValueError("missing octave in note name: " + text)
    return (int(octave_text) + 1) * 12 + semitone


def classify(lowest, highest, timbre, agility):
    """Return the classical role for a single singer."""
    low = note_value(lowest)
    high = note_value(highest)
    colour = timbre.strip().lower()
    speed = agility.strip().lower()
    if low > high:
        raise ValueError("lowest note is above highest note")
    if low == note_value("E2") and high == note_value("E4") and colour == "dark":
        return "dramatic bass"
    elif low == note_value("C3") and high == note_value("G4") and colour == "bright":
        return "lyric tenor"
    elif low == note_value("F3") and high == note_value("D5") and colour == "dark":
        return "dramatic contralto"
    elif low == note_value("G3") and high == note_value("B5") and colour == "dark":
        return "dramatic soprano"
    elif low == note_value("C4") and high == note_value("C6") and speed == "high":
        return "coloratura soprano"
    elif high > note_value("C6") and speed == "exceptional":
        return "Queen of the Night role"
    elif low < note_value("C2"):
        return "basso profondo specialist"
    elif low == note_value("A2") and high == note_value("A4"):
        return "lyric baritone"
    return "ensemble chorus member"


def cast(singers):
    """Cast every singer described by (lowest, highest, timbre, agility)."""
    roles = []
    for singer in singers:
        if len(singer) != 4:
            raise ValueError("each singer needs lowest, highest, timbre and agility")
        lowest, highest, timbre, agility = singer
        roles.append(classify(lowest, highest, timbre, agility))
    return roles


def format_report(singers, roles):
    """Build printable lines pairing each range with the role it earned."""
    if not roles:
        return ["No singers auditioned."]
    lines = []
    position = 0
    while position < len(roles):
        lowest, highest = singers[position][0], singers[position][1]
        lines.append("{0}-{1}: {2}".format(lowest, highest, roles[position]))
        position += 1
    soloists = [role for role in roles if role != "ensemble chorus member"]
    if len(soloists) == len(roles):
        lines.append("Every singer received a solo role.")
    elif soloists:
        lines.append("{0} soloists, {1} in the chorus.".format(len(soloists), len(roles) - len(soloists)))
    else:
        lines.append("The whole audition group joins the chorus.")
    return lines


def main():
    auditions = [
        ("C4", "C6", "bright", "high"),
        ("E2", "E4", "dark", "moderate"),
        ("D4", "F6", "bright", "exceptional"),
        ("A1", "D4", "dark", "low"),
        ("A2", "A4", "warm", "moderate"),
        ("D3", "F4", "bright", "moderate"),
    ]
    for line in format_report(auditions, cast(auditions)):
        print(line)


