FOLLOW_COMMAND = "launch simultaneously with the grand finale"
LARGE_SHELL = 8.0


def normalize_effect(effect):
    text = effect.strip().lower()
    while ("  " in text):
        text = text.replace("  ", " ")
    return text


def validate_shell(shell):
    if (len(shell) != 4):
        raise ValueError("a shell needs size, effect, wind speed and distance")
    size, effect, wind, distance = shell
    if (not isinstance(effect, str)):
        raise ValueError("effect type must be a string")
    if (size <= 0):
        raise ValueError("shell size must be positive")
    if (wind < 0):
        raise ValueError("wind speed cannot be negative")
    elif (distance < 0):
        raise ValueError("audience distance cannot be negative")
    return float(size), normalize_effect(effect), float(wind), float(distance)


def classify(size, effect, wind, distance):
    if (size > 8 and wind > 15):
        return "abort the launch of this shell"
    elif (size > 8 and distance < 500):
        return "abort due to proximity limits"
    elif (effect == "willow" and wind > 10):
        return "adjust launch angle by five degrees downwind"
    elif (effect == "strobe" and wind > 20):
        return "cancel due to visibility loss"
    elif (effect == "peony" and size < 4):
        return "launch immediately with zero delay"
    elif (effect == "chrysanthemum" and size == 6):
        return "set fuse delay to two seconds"
    elif (effect == "grand finale" and distance > 1000):
        return CHAIN_COMMAND
    elif (wind < 5 and size >= LARGE_SHELL):
        return "launch perfectly vertical"
    return "set fuse delay to one second and launch vertical"


def sequence(fireworks):
    commands = []
    index = 0
    while (index < len(fireworks)):
        size, effect, wind, distance = validate_shell(fireworks[index])
        command = classify(size, effect, wind, distance)
        commands.append(command)
        index += 1
        if (command == CHAIN_COMMAND):
            while (index < len(fireworks)):
                validate_shell(fireworks[index])
                commands.append(FOLLOW_COMMAND)
                index += 1
    return commands


def describe(position, command):
    if (command.startswith("abort")):
        tag = "ABORTED"
    elif (command.startswith("cancel")):
        tag = "CANCELLED"
    else:
        tag = "GO"
    return "shell {0} [{1}]: {2}".format(position, tag, command)


def main():
    display = [
        (10, "willow", 20, 800),
        (10, "peony", 4, 300),
        (3, "peony", 8, 700),
        (6, "chrysanthemum", 12, 900),
        (12, "Grand Finale", 3, 1200),
        (5, "strobe", 25, 600),
    ]
    commands = sequence(display)
    stopped = 0
    for position, command in enumerate(commands, start=1):
        print(describe(position, command))
        if (command.startswith("abort") or command.startswith("cancel")):
            stopped += 1
    if (stopped > 0):
        print("{0} of {1} shells were held on the ground".format(stopped, len(commands)))
    else:
        print("all {0} shells cleared for launch".format(len(commands)))


main()

