def normalize_usage(value):
    if not isinstance(value, str):
        return ""
    return value.strip().lower()


def get_measurement(prop, key):
    value = prop.get(key)
    if isinstance(value, bool):
        return None
    elif isinstance(value, (int, float)):
        return float(value)
    return None


def setback_minimum(usage, height):
    if usage == "residential":
        if height > 30:
            return 15.0
        return 10.0
    elif usage == "commercial":
        return 20.0
    elif usage == "industrial":
        return 30.0
    return None


def violation(prop):
    usage = normalize_usage(prop.get("usage"))
    lot = get_measurement(prop, "lot_size")
    height = get_measurement(prop, "height")
    setback = get_measurement(prop, "setback")
    if lot is None or height is None or setback is None:
        return "incomplete measurements"
    if usage == "residential":
        if lot <= 5000:
            return "lot size must exceed 5000 sq ft"
        elif height >= 40:
            return "height must stay under 40 ft"
    elif usage == "commercial":
        if lot <= 10000:
            return "lot size must exceed 10000 sq ft"
        elif height >= 100:
            return "height must stay under 100 ft"
    elif usage == "industrial":
        if lot <= 20000:
            return "lot size must exceed 20000 sq ft"
        elif height > 50:
            return "height must not exceed 50 ft"
    else:
        return "unknown usage type"
    minimum = setback_minimum(usage, height)
    if setback < minimum:
        return "front setback must be at least %g ft" % minimum
    return ""


def zone(properties):
    statuses = []
    for prop in properties:
        if violation(prop):
            statuses.append("rejected")
        else:
            statuses.append("accepted")
    return statuses


def review(proposals):
    queue = list(proposals)
    lines = []
    while queue:
        prop = queue.pop(0)
        label = prop.get("id", "unnamed")
        reason = violation(prop)
        if reason:
            lines.append("%s: rejected (%s)" % (label, reason))
        else:
            lines.append("%s: accepted" % label)
    return lines


def main():
    proposals = [
        {"id": "A", "usage": "commercial", "lot_size": 12000, "height": 80, "setback": 25},
        {"id": "B", "usage": "residential", "lot_size": 6000, "height": 35, "setback": 12},
        {"id": "C", "usage": "industrial", "lot_size": 40000, "height": 45, "setback": 30},
        {"id": "D", "usage": "agricultural", "lot_size": 90000, "height": 20, "setback": 60},
    ]
    for line in review(proposals):
        print(line)
    print("summary:", zone(proposals))


if __name__ == "__main__":
    main()

