REQUIRED_FIELDS = ("name", "rate", "hours")

def validate_shift(shift):
    if not isinstance(shift, dict):
        raise TypeError("each shift must be a dictionary")
    for field in REQUIRED_FIELDS:
        if field not in shift:
            raise KeyError("shift is missing the field '%s'" % field)
    if shift["rate"] < 0:
        raise ValueError("rate cannot be negative")
    elif shift["hours"] < 0:
        raise ValueError("hours cannot be negative")

def shift_multiplier(shift):
    multiplier = 1.0
    if shift.get("weekend"):
        multiplier += 0.5
    if shift.get("night") and shift.get("holiday"):
        multiplier += 1.0
    elif shift.get("night"):
        multiplier += 0.2
    return multiplier

def shift_pay(shift):
    validate_shift(shift)
    rate = float(shift["rate"])
    hours = float(shift["hours"])
    if shift.get("on_call") and not shift.get("called_in"):
        pay = rate * hours * 0.2
    else:
        regular = min(hours, 8.0)
        overtime = hours - regular
        pay = regular * rate * shift_multiplier(shift)
        if overtime > 0:
            pay += overtime * rate * 1.5
        if hours > 16:
            pay += 50.0
    if shift.get("trainee") and pay > 100.0:
        pay = 100.0
    return round(pay, 2)

def payroll(shifts):
    totals = []
    index = 0
    while index < len(shifts):
        totals.append(shift_pay(shifts[index]))
        index += 1
    return totals

def describe_shift(shift):
    if shift.get("on_call") and not shift.get("called_in"):
        return "standby"
    tags = []
    if shift.get("weekend"):
        tags.append("weekend")
    if shift.get("night") and shift.get("holiday"):
        tags.append("holiday night")
    elif shift.get("night"):
        tags.append("night")
    if shift["hours"] > 16:
        tags.append("double")
    elif shift["hours"] > 8:
        tags.append("overtime")
    if shift.get("trainee"):
        tags.append("trainee")
    return ", ".join(tags) or "standard"

def main():
    shifts = [
        {"name": "Ada", "rate": 10, "hours": 8, "weekend": True, "night": True},
        {"name": "Bo", "rate": 20, "hours": 12, "holiday": True, "night": True},
        {"name": "Cleo", "rate": 15, "hours": 18, "weekend": True},
        {"name": "Dev", "rate": 30, "hours": 10, "on_call": True, "called_in": False},
        {"name": "Eli", "rate": 12, "hours": 9, "night": True, "trainee": True},
    ]
    totals = payroll(shifts)
    for shift, total in zip(shifts, totals):
        print("%-10s %5.1fh  %-24s $%8.2f"
              % (shift["name"], shift["hours"], describe_shift(shift), total))
    print("%-10s %30s $%8.2f" % ("TOTAL", "", sum(totals)))

main()

