ADD_TWO = "add two servers"
ADD_ONE = "add one server"
REMOVE_ONE = "remove one server"
REMOVE_TWO = "remove two servers"
SHUTDOWN = "shut down all servers except one"
KEEP = "keep current count"


def _extract(entry):
    if isinstance(entry, dict):
        missing = [k for k in ("cpu", "memory", "connections") if k not in entry]
        if missing:
            raise ValueError("metric is missing fields: " + ", ".join(missing))
        return float(entry["cpu"]), float(entry["memory"]), int(entry["connections"])
    elif len(entry) == 3:
        cpu, memory, connections = entry
        return float(cpu), float(memory), int(connections)
    raise ValueError("a metric sample needs cpu, memory and connections")


def _validate(cpu, memory, connections):
    if cpu < 0 or cpu > 100:
        raise ValueError("cpu percentage out of range: %r" % cpu)
    elif memory < 0 or memory > 100:
        raise ValueError("memory percentage out of range: %r" % memory)
    elif connections < 0:
        raise ValueError("connections cannot be negative: %r" % connections)


def scale(metrics):
    actions = []
    low_cpu_streak = 0
    for entry in metrics:
        cpu, memory, connections = _extract(entry)
        _validate(cpu, memory, connections)
        if cpu < 10:
            low_cpu_streak += 1
        else:
            low_cpu_streak = 0
        if cpu > 80 or memory > 90:
            actions.append(ADD_TWO)
        elif cpu > 70 and connections > 1000:
            actions.append(ADD_ONE)
        elif connections == 0:
            actions.append(SHUTDOWN)
        elif low_cpu_streak >= 3:
            actions.append(REMOVE_TWO)
        elif cpu < 20 and memory < 30 and connections < 100:
            actions.append(REMOVE_ONE)
        else:
            actions.append(KEEP)
    return actions


def simulate(servers, actions):
    for action in actions:
        if action == ADD_TWO:
            servers += 2
        elif action == ADD_ONE:
            servers += 1
        elif action == REMOVE_ONE:
            servers -= 1
        elif action == REMOVE_TWO:
            servers -= 2
        elif action == SHUTDOWN:
            servers = 1
        if servers < 1:
            servers = 1
    return servers


def format_report(actions):
    lines = []
    index = 0
    while index < len(actions):
        end = index
        while end + 1 < len(actions) and actions[end + 1] == actions[index]:
            end += 1
        if end == index:
            lines.append("minute %d: %s" % (index + 1, actions[index]))
        else:
            lines.append("minutes %d-%d: %s" % (index + 1, end + 1, actions[index]))
        index = end + 1
    return lines


def main():
    samples = [
        {"cpu": 40.0, "memory": 95.0, "connections": 800},
        {"cpu": 75.0, "memory": 60.0, "connections": 1500},
        (5.0, 25.0, 50),
        (8.0, 20.0, 40),
        (4.0, 15.0, 30),
        (12.0, 55.0, 0),
        (45.0, 50.0, 300),
    ]
    actions = scale(samples)
    for line in format_report(actions):
        print(line)
    print("servers after the window: %d" % simulate(4, actions))


main()

