GROUP_COUNT = 4
GROUP_CAPACITY = 4
REGION_LIMIT = 2


def normalize_team(team):
    """Accept a dict or a (name, rank, region[, wild_card]) sequence."""
    if isinstance(team, dict):
        name = team.get("name")
        rank = team.get("rank")
        region = team.get("region")
        wild = bool(team.get("wild_card", False))
    else:
        if len(team) < 3:
            raise ValueError("a team needs a name, a rank and a region")
        name, rank, region = team[0], team[1], team[2]
        wild = False
        if len(team) > 3:
            wild = bool(team[3])
    if name is None:
        raise ValueError("team name is missing")
    if region is None:
        raise ValueError("region is missing for team %r" % (name,))
    if not isinstance(rank, int):
        raise TypeError("rank of %r must be an integer" % (name,))
    return {"name": str(name), "rank": rank, "region": str(region), "wild_card": wild}


def region_tally(group, region):
    return sum(1 for member in group if member["region"] == region)


def open_groups(groups, region):
    allowed = [i for i in range(GROUP_COUNT)
               if region_tally(groups[i], region) < REGION_LIMIT and len(groups[i]) < GROUP_CAPACITY]
    if not allowed:
        allowed = [i for i in range(GROUP_COUNT) if len(groups[i]) < GROUP_CAPACITY]
    if not allowed:
        allowed = list(range(GROUP_COUNT))
    return allowed


def choose_group(groups, team):
    region = team["region"]
    if team["wild_card"] and len(groups[GROUP_COUNT - 1]) < GROUP_CAPACITY:
        return GROUP_COUNT - 1
    candidates = open_groups(groups, region)
    best = candidates[0]
    for idx in candidates[1:]:
        if len(groups[idx]) < len(groups[best]):
            best = idx
        elif len(groups[idx]) == len(groups[best]) and region_tally(groups[idx], region) < region_tally(groups[best], region):
            best = idx
    return best


def seed(teams):
    roster = [normalize_team(team) for team in teams]
    roster.sort(key=lambda entry: entry["rank"])
    groups = [[] for _ in range(GROUP_COUNT)]
    position = 0
    while position < len(roster):
        team = roster[position]
        groups[choose_group(groups, team)].append(team)
        position += 1
    return groups


