ISOLATION = "isolation zone"
MANUAL = "manual handling"
HEAVY = "heavy zone"
EXPRESS = "express zone"
CAREFUL = "careful zone"
STANDARD = "standard zone"
BULK = "bulk overflow zone"
STANDARD_LIMIT = 10


def parse_weight(value):
    if isinstance(value, (int, float)):
        weight = float(value)
    elif isinstance(value, str):
        text = value.strip().lower()
        while text and text[-1].isalpha():
            text = text[:-1]
        weight = float(text.strip())
    else:
        raise TypeError("weight must be a number or a string")
    if weight < 0:
        raise ValueError("weight cannot be negative")
    return weight


def flag(task, name):
    value = task.get(name, False)
    if isinstance(value, str):
        return value.strip().lower() in ("yes", "true", "1")
    return bool(value)


def priority_is_high(task):
    value = task.get("priority", "normal")
    if isinstance(value, str):
        return value.strip().lower() == "high"
    return bool(value)


def classify(task, standard_count):
    weight = parse_weight(task.get("weight", 0))
    if flag(task, "hazardous"):
        return ISOLATION
    if weight > 50:
        if flag(task, "fragile"):
            return MANUAL
        return HEAVY
    if priority_is_high(task) and weight < 10:
        return EXPRESS
    elif flag(task, "fragile") and weight < 50:
        return CAREFUL
    elif standard_count >= STANDARD_LIMIT:
        return BULK
    return STANDARD


def route(tasks):
    zones = []
    standard_count = 0
    index = 0
    while index < len(tasks):
        zone = classify(tasks[index], standard_count)
        if zone == STANDARD:
            standard_count += 1
        zones.append(zone)
        index += 1
    return zones


def summarize(zones):
    counts = {}
    for zone in zones:
        counts[zone] = counts.get(zone, 0) + 1
    lines = []
    for zone in sorted(counts):
        if counts[zone] == 1:
            lines.append("%s: 1 task" % zone)
        else:
            lines.append("%s: %d tasks" % (zone, counts[zone]))
    return lines


def main():
    tasks = [
        {"id": "A1", "weight": 5, "priority": "high"},
        {"id": "A2", "weight": "80 lbs"},
        {"id": "A3", "weight": 62, "fragile": True},
        {"id": "A4", "weight": 12, "fragile": "yes"},
        {"id": "A5", "weight": 3, "hazardous": True, "priority": "high"},
    ]
    tasks.extend({"id": "B%d" % n, "weight": 20} for n in range(12))
    zones = route(tasks)
    for task, zone in zip(tasks, zones):
        print("%-4s -> %s" % (task["id"], zone))
    print("---")
    for line in summarize(zones):
        print(line)
    if MANUAL in zones:
        print("Warning: some items need a human operator.")


if __name__ == "__main__":
    main()

