REFUND_CLASSES = ("non_refundable", "standard", "fully_flexible")
FIELD_DEFAULTS = {"base": 0.0, "days": 0.0, "meal": 0.0}


def parse_ticket(spec):
    parts = spec.split()
    if not parts:
        raise ValueError("empty ticket specification")
    ticket = {"class": parts[0].strip().lower().replace("-", "_")}
    ticket.update(FIELD_DEFAULTS)
    index = 1
    while index < len(parts):
        token = parts[index]
        if "=" not in token:
            raise ValueError("expected key=value, got " + token)
        key, value = token.split("=", 1)
        if key not in FIELD_DEFAULTS:
            raise ValueError("unknown field " + key)
        ticket[key] = float(value)
        index += 1
    return ticket


def validate_ticket(ticket):
    kind = str(ticket.get("class", "")).strip().lower().replace("-", "_")
    if kind not in REFUND_CLASSES:
        raise ValueError("unsupported ticket class: " + str(ticket.get("class")))
    base = float(ticket.get("base", 0.0))
    days = float(ticket.get("days", 0.0))
    meal = float(ticket.get("meal", 0.0))
    if base < 0.0:
        raise ValueError("base price cannot be negative")
    elif meal < 0.0:
        raise ValueError("meal price cannot be negative")
    if days < 0.0:
        raise ValueError("days until departure cannot be negative")
    return kind, base, days, meal


def base_refund(kind, base, days):
    if kind == "non_refundable":
        return 0.0
    elif kind == "fully_flexible":
        return base
    if days > 14.0:
        return base * 0.90
    elif days >= 7.0:
        return base * 0.50
    return 0.0


def meal_refund(meal, days):
    if days < 1.0:
        return 0.0
    return meal


def refund(tickets):
    amounts = []
    for ticket in tickets:
        if isinstance(ticket, str):
            ticket = parse_ticket(ticket)
        kind, base, days, meal = validate_ticket(ticket)
        total = base_refund(kind, base, days) + meal_refund(meal, days)
        amounts.append(round(total, 2))
    return amounts


def format_report(tickets, amounts):
    lines = []
    index = 0
    while index < len(amounts):
        ticket = tickets[index]
        if isinstance(ticket, str):
            ticket = parse_ticket(ticket)
        kind, base, days, meal = validate_ticket(ticket)
        paid = base + meal
        note = "full refund"
        if amounts[index] <= 0.0:
            note = "nothing returned"
        elif amounts[index] < paid:
            note = "partial refund"
        lines.append("%-15s paid %7.2f, %5.1f days out -> %7.2f (%s)"
                     % (kind, paid, days, amounts[index], note))
        index += 1
    return "\n".join(lines)


def main():
    tickets = [
        "standard base=50 days=10",
        "standard base=120 days=20 meal=15",
        "standard base=80 days=3 meal=10",
        "non-refundable base=40 days=30 meal=8",
        "fully-flexible base=200 days=0.5 meal=25",
        {"class": "standard", "base": 60.0, "days": 14.0},
    ]
    print(format_report(tickets, refund(tickets)))


main()

