SLIDING = "sliding"


def normalize_inputs(inputs):
    """Turn a raw sequence of button presses into clean lower-case tokens."""
    if isinstance(inputs, str):
        raise TypeError("inputs must be a sequence of button names, not a single string")
    cleaned = []
    for raw in inputs:
        if not isinstance(raw, str):
            raise TypeError("every button press must be a string, got %r" % (raw,))
        token = raw.strip().lower()
        if token not in VALID_INPUTS:
            raise ValueError("unknown button press: %r" % (raw,))
        cleaned.append(token)
    return cleaned


def next_state(state, action):
    """Return the state reached from `state` after the button press `action`."""
    if state == IN_AIR:
        if action == "land":
            return IDLE
        return IN_AIR
    if action == "land":
        return state
    if action == "jump":
        if state == CROUCHING:
            return IDLE
        return IN_AIR
    if action == "crouch":
        if state == RUNNING:
            return SLIDING
        elif state == IDLE or state == WALKING:
            return CROUCHING
        return state
    if action == "forward" and state == IDLE:
        return WALKING
    elif action == "sprint" and state == WALKING:
        return RUNNING
    return state


