LETTERS = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}


def note_value(note):
    if isinstance(note, int):
        return note % 12
    text = str(note).strip()
    if not text:
        raise ValueError("empty note name")
    letter = text[0].upper()
    if letter not in LETTERS:
        raise ValueError("unknown note letter: " + text[0])
    value = LETTERS[letter]
    index = 1
    while index < len(text):
        mark = text[index]
        if mark == "#":
            value += 1
        elif mark == "b":
            value -= 1
        else:
            raise ValueError("unknown accidental: " + mark)
        index += 1
    return value % 12


def interval(low, high):
    return (note_value(high) - note_value(low)) % 12


def triad_name(first, second):
    if first == 4 and second == 3:
        return "major"
    elif first == 3 and second == 4:
        return "minor"
    elif first == 3 and second == 3:
        return "diminished"
    elif first == 4 and second == 4:
        return "augmented"
    return "unknown"


def seventh_name(from_root):
    if from_root == 10:
        return "dominant seventh"
    elif from_root == 11:
        return "major seventh"
    elif from_root == 9:
        return "diminished seventh"
    return None


def identify(chords):
    names = []
    for chord in chords:
        if len(chord) < 3:
            names.append("unknown")
            continue
        name = triad_name(interval(chord[0], chord[1]), interval(chord[1], chord[2]))
        if name == "unknown":
            names.append("unknown")
            continue
        if len(chord) > 3:
            extra = seventh_name(interval(chord[0], chord[3]))
            if extra is not None:
                name = name + " " + extra
        names.append(name)
    return names


