def validate_speech(speech):
    if len(speech) != 3:
        raise ValueError("a speech needs duration, interruptions and vocabulary")
    duration, interruptions, vocabulary = speech
    if duration < 0:
        raise ValueError("duration cannot be negative")
    elif interruptions < 0:
        raise ValueError("interruptions cannot be negative")
    elif vocabulary < 0:
        raise ValueError("vocabulary score cannot be negative")

def score_speech(duration, interruptions, vocabulary):
    if duration == 0:
        return 0
    total = 100
    if duration > 10:
        total -= 5
    elif duration < 3:
        total -= 10
    if interruptions > 5:
        total -= 20
    if vocabulary > 90:
        total += 15
    if duration == 5:
        total += 10
    if total > 100:
        total = 100
    elif total < 0:
        total = 0
    return total

def score(speeches):
    results = []
    for speech in speeches:
        validate_speech(speech)
        results.append(score_speech(*speech))
    return results

def parse_entries(lines):
    names = []
    speeches = []
    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        elif line.startswith('#'):
            continue
        parts = line.split(',')
        if len(parts) != 4:
            raise ValueError("expected 'name, duration, interruptions, vocabulary'")
        names.append(parts[0].strip())
        speeches.append(tuple(float(part) for part in parts[1:]))
    return names, speeches

def format_report(names, scores):
    lines = []
    index = 0
    while index < len(names):
        lines.append("%-10s %3d" % (names[index], scores[index]))
        index += 1
    return lines

def leaders(names, scores):
    if not scores:
        return []
    best = max(scores)
    return [name for name, value in zip(names, scores) if value == best]

