def parse_capsule(line):
    parts = line.split()
    if len(parts) < 2:
        raise ValueError("manifest line needs a color and a weight: " + line)
    color = parts[0].lower()
    weight = int(parts[1])
    fragile = False
    if len(parts) > 2 and parts[2].lower() in ("fragile", "yes", "true"):
        fragile = True
    return (color, weight, fragile)


def is_fragile(capsule):
    if len(capsule) > 2:
        return bool(capsule[2])
    return False


def destination(color, weight):
    if weight > 10:
        return "rejected"
    elif weight < 1:
        return "rejected"
    elif color == "red":
        return "emergency"
    elif color == "blue" and weight > 5:
        return "logistics"
    elif color == "green":
        return "administration"
    elif color == "yellow":
        return "logistics"
    return "rejected"


def route(capsules):
    counts = {"emergency": 0, "logistics": 0, "administration": 0,
              "rejected": 0, "halted": False}
    consecutive_rejects = 0
    index = 0
    while index < len(capsules):
        capsule = capsules[index]
        if len(capsule) < 2:
            raise ValueError("capsule needs a color and a weight: " + repr(capsule))
        color = capsule[0].lower()
        weight = capsule[1]
        target = destination(color, weight)
        if target != "rejected" and is_fragile(capsule):
            target = "emergency"
        counts[target] += 1
        if target == "rejected":
            consecutive_rejects += 1
        else:
            consecutive_rejects = 0
        if consecutive_rejects > 3:
            counts["halted"] = True
            break
        index += 1
    return counts


def format_report(counts):
    lines = []
    for name in ("emergency", "logistics", "administration", "rejected"):
        lines.append("{:<15}{:>3}".format(name, counts[name]))
    if counts["halted"]:
        lines.append("SYSTEM HALTED: too many consecutive rejects")
    else:
        lines.append("system nominal")
    return "\n".join(lines)


