        "blue 7",
        "green 3 fragile",
        "yellow 1",
        "blue 12",
        "green 0",
        "red 11",
        "yellow 14",
        "red 4",
    ]
    capsules = [parse_capsule(line) for line in manifest]
    print(format_report(route(capsules)))


