RADIOACTIVE = {"radioactive", "uranium", "thorium", "plutonium"}


def normalise(entry):
    """Unpack and sanity-check one asteroid record."""
    composition, mass, scanned = entry
    if not isinstance(composition, str):
        raise TypeError("composition must be a string")
    if not isinstance(mass, int):
        raise TypeError("mass must be an integer")
    if mass < 0:
        raise ValueError("mass cannot be negative")
    return composition.strip().lower(), mass, bool(scanned)


def apply_penalty(amount, mass):
    """Heavy rocks lose a tenth of the yield during extraction."""
    if mass > 1000:
        return amount * 0.9
    return float(amount)


def mine(asteroids):
    metals = 0.0
    water = 0.0
    quarantine = False
    index = 0
    while index < len(asteroids):
        composition, mass, scanned = normalise(asteroids[index])
        index += 1
        if not scanned:
            continue
        if composition == "alien":
            quarantine = True
            break
        if composition in RADIOACTIVE:
            continue
        if mass == 0:
            continue
        if composition == "iron":
            metals += apply_penalty(mass, mass)
        elif composition == "ice":
            water += apply_penalty(mass, mass)
        elif composition == "gold":
            metals += apply_penalty(mass * 3, mass)
    return {"metals": metals, "water": water, "quarantine": quarantine}


def format_report(result):
    lines = []
    if result["quarantine"]:
        lines.append("QUARANTINE: alien material found, mining halted early.")
    lines.append("metals yield: {0:.1f} t".format(result["metals"]))
    lines.append("water yield:  {0:.1f} t".format(result["water"]))
    if result["metals"] == 0.0 and result["water"] == 0.0:
        lines.append("verdict: nothing recovered from this belt.")
    elif result["metals"] > result["water"]:
        lines.append("verdict: metals-dominant haul.")
    elif result["water"] > result["metals"]:
        lines.append("verdict: water-dominant haul.")
    else:
        lines.append("verdict: balanced haul.")
    return "\n".join(lines)


def main():
    belt = [
        ("iron", 500, True),
        ("ice", 2000, True),
        ("gold", 300, True),
        ("iron", 40, False),
        ("uranium", 800, True),
        ("ice", 0, True),
        ("gold", 1500, True),
        ("alien", 120, True),
        ("iron", 999, True),
    ]
    print(format_report(mine(belt)))


main()

