def base_strength(material):
    name = material.strip().lower()
    if name == "nylon":
        return 100
    elif name == "hemp":
        return 60
    raise ValueError("unknown rope material: " + material)


def knot_factor(knot):
    style = knot.strip().lower()
    if style == "bowline":
        return 0.8
    elif style == "square knot":
        return 0.5
    elif style == "figure eight":
        return 0.9
    return 1.0


def parse_conditions(item):
    if len(item) < 4:
        return set()
    raw = item[3]
    if isinstance(raw, str):
        parts = raw.replace(";", ",").split(",")
    else:
        parts = list(raw)
    return set(str(part).strip().lower() for part in parts if str(part).strip())


def evaluate(ropes):
    results = []
    position = 0
    while position < len(ropes):
        item = ropes[position]
        if len(item) < 3:
            raise ValueError("rope entry needs material, thickness and knot")
        material, thickness, knot = item[0], item[1], item[2]
        if thickness <= 0:
            raise ValueError("thickness must be positive millimetres")
        strength = base_strength(material) * knot_factor(knot)
        if thickness < 5:
            strength -= 10
        flags = parse_conditions(item)
        if "wet" in flags:
            strength -= 5
        if "frayed" in flags:
            strength /= 2
        results.append(round(strength, 1))
        position += 1
    return results


def rating(strength):
    if strength >= 80:
        return "excellent"
    elif strength >= 50:
        return "adequate"
    return "unsafe"


def format_report(ropes, strengths):
    lines = []
    for item, strength in zip(ropes, strengths):
        flags = parse_conditions(item)
        if flags:
            state = ", ".join(sorted(flags))
        else:
            state = "dry and sound"
        lines.append("%s %dmm %s (%s): %s -> %s" % (item[0], item[1], item[2], state, strength, rating(strength)))
    return "\n".join(lines)


def main():
    ropes = [
        ("nylon", 8, "square knot"),
        ("nylon", 10, "figure eight"),
        ("hemp", 4, "bowline", "wet"),
        ("hemp", 12, "figure eight", ["wet", "frayed"]),
        ("nylon", 6, "clove hitch"),
    ]
    strengths = evaluate(ropes)
    print(format_report(ropes, strengths))
    weakest = min(strengths)
    if weakest < 50:
        print("Warning: replace the weakest rope, it holds only %s points." % weakest)


main()

