BOUNDARY = 8
IMPURITY_SIZES = frozenset({7, 13})


def parse_lattice(lattice):
    """Turn the raw list of (coordinate, atomic size) tuples into a lookup table."""
    sites = {}
    for entry in lattice:
        if (len(entry) != 2):
            raise ValueError("each lattice entry needs a coordinate and an atomic size")
        coord, size = entry
        if (not isinstance(coord, int)):
            raise ValueError("coordinate %r is not an integer" % (coord,))
        if (not isinstance(size, int)):
            raise ValueError("atomic size %r is not an integer" % (size,))
        if (coord in sites):
            raise ValueError("coordinate %d was measured twice" % coord)
        sites[coord] = size
    return sites


def is_shifted_row(coords):
    """True when the whole row sits one coordinate away from the origin."""
    if (not coords):
        return False
    index = 0
    while (index < len(coords)):
        if (coords[index] != index + 1):
            return False
        index += 1
    return True


