CARDINALS = ("north", "south", "east", "west")
MAIN_DOOR = "north"
WINDOW_WALLS = ("west",)


def normalize(item):
    """Turn a raw furniture tuple into (kind, color, direction) in lower case."""
    if len(item) != 3:
        raise ValueError("each furniture entry needs a type, a color and a direction")
    kind, color, direction = [str(part).strip().lower() for part in item]
    while "  " in kind:
        kind = kind.replace("  ", " ")
    if direction not in CARDINALS:
        raise ValueError("unknown compass direction: " + direction)
    if not kind:
        raise ValueError("furniture type must not be empty")
    return kind, color, direction


def score_item(kind, color, direction):
    """Harmony points contributed by a single piece of furniture."""
    points = 0
    if "mirror" in kind and direction == MAIN_DOOR:
        points -= 5
    elif "bed" in kind and direction == "north":
        points += 3
    elif "fountain" in kind and direction == "south":
        points -= 2
    if "sharp corner" in kind:
        points -= 4
    if "plant" in kind and "dying" in kind:
        points -= 3
    if color == "red" and direction == "east":
        points += 2
    if "wardrobe" in kind and "large" in kind and direction in WINDOW_WALLS:
        points -= 6
    return points


def is_symmetric(directions):
    """Perfect symmetry means opposite walls carry the same number of pieces."""
    if not directions:
        return False
    pairs = [("north", "south"), ("east", "west")]
    index = 0
    while index < len(pairs):
        near, far = pairs[index]
        if directions.count(near) != directions.count(far):
            return False
        index += 1
    return True


def assess(room):
    score = 0
    directions = []
    index = 0
    while index < len(room):
        kind, color, direction = normalize(room[index])
        score += score_item(kind, color, direction)
        directions.append(direction)
        index += 1
    if is_symmetric(directions):
        score += 10
    return score


def report(room):
    lines = []
    directions = []
    for item in room:
        kind, color, direction = normalize(item)
        delta = score_item(kind, color, direction)
        directions.append(direction)
        if delta > 0:
            label = "boost"
        elif delta < 0:
            label = "drain"
        else:
            label = "neutral"
        lines.append("%-22s %-7s %-5s %+3d  %s" % (kind, color, direction, delta, label))
    if is_symmetric(directions):
        lines.append("perfect symmetry bonus            +10")
    lines.append("total harmony: %d" % assess(room))
    return "\n".join(lines)


def main():
    rooms = {
        "study": [
            ("bed", "white", "north"),
            ("mirror", "silver", "north"),
            ("large wardrobe", "brown", "west"),
            ("dying plant", "green", "east"),
        ],
        "salon": [
            ("bed", "oak", "north"),
            ("lamp", "red", "east"),
            ("water fountain", "blue", "south"),
            ("sharp corner shelf", "black", "west"),
        ],
    }
    for name in sorted(rooms):
        print(name.upper())
        print(report(rooms[name]))
        print()


if __name__ == "__main__":
    main()

