def letter_position(ch):
    return ord(ch.lower()) - ord('a') + 1


def running_sum(serial):
    total = 0
    index = 0
    while index < len(serial):
        ch = serial[index]
        if ch.isalpha():
            value = letter_position(ch)
        elif ch.isdigit():
            value = int(ch)
        else:
            return None
        if index % 2 == 0:
            value *= 2
        total += value
        index += 1
    if serial.startswith("0"):
        total -= 5
    return total


def inspect(serial, damage=0):
    if damage < 0 or damage > 10:
        raise ValueError("damage rating must be between 0 and 10")
    flags = []
    if len(serial) != 10:
        flags.append("INVALID_LENGTH")
    total = running_sum(serial)
    if total is None:
        flags.append("COUNTERFEIT")
    elif total % 10 != 0:
        flags.append("BAD_CHECKSUM")
    valid = len(flags) == 0
    if valid and damage >= 7:
        flags.append("LOW_CONDITION")
    return valid, flags


def authenticate(serial):
    return inspect(serial)[0]


def format_line(serial, valid, flags):
    if valid:
        status = "AUTHENTIC"
    else:
        status = "REJECTED"
    if flags:
        return "%-12s %-10s %s" % (serial, status, ", ".join(flags))
    return "%-12s %s" % (serial, status)


def report(notes):
    lines = []
    for serial, damage in notes:
        valid, flags = inspect(serial, damage)
        lines.append(format_line(serial, valid, flags))
    return lines


def main():
    notes = [
        ("1234567890", 2),
        ("0123456789", 9),
        ("AB12345678", 1),
        ("12-4567890", 0),
        ("12345", 4),
        ("9876543210", 8),
    ]
    for line in report(notes):
        print(line)
    authentic = 0
    for serial, damage in notes:
        if authenticate(serial):
            authentic += 1
    print("authentic notes: %d of %d" % (authentic, len(notes)))
    if authentic == 0:
        print("warning: the whole batch failed authentication")
    elif authentic < len(notes):
        print("set aside the rejected notes for manual review")


main()

