MAX_CAPACITY = 500
WIND_PENALTY = 0.8
HIGH_WIND = False


def set_high_wind(active):
    global HIGH_WIND
    HIGH_WIND = active


def validate_queue(passengers):
    for entry in passengers:
        if not isinstance(entry, tuple) or len(entry) != 3:
            raise ValueError("each passenger must be a (weight, vip, pregnant) tuple")
        weight, vip, pregnant = entry
        if not isinstance(weight, int):
            raise TypeError("weight must be an integer")
        elif weight < 0:
            raise ValueError("weight cannot be negative")
        if not isinstance(vip, bool) or not isinstance(pregnant, bool):
            raise TypeError("vip and pregnant flags must be booleans")


def lift_capacity():
    if HIGH_WIND:
        return int(MAX_CAPACITY * WIND_PENALTY)
    return MAX_CAPACITY


def prioritize(passengers):
    return sorted(passengers, key=lambda person: not person[1])


def seat_for(weight, pregnant):
    if pregnant:
        return "seated"
    elif weight > 100:
        return "center"
    elif weight < 50:
        return "edge"
    return "standing"


def balance(passengers):
    validate_queue(passengers)
    capacity = lift_capacity()
    queue = prioritize(passengers)
    boarded, denied, left_behind = [], [], []
    total, index, pending_light = 0, 0, None
    while index < len(queue):
        weight, vip, pregnant = queue[index]
        if weight == 0:
            denied.append(queue[index])
            index += 1
            continue
        if total + weight > capacity:
            left_behind.extend(queue[index:])
            break
        spot = seat_for(weight, pregnant)
        boarded.append({"weight": weight, "vip": vip, "spot": spot, "partner": None})
        if spot == "edge" and pending_light is None:
            pending_light = len(boarded) - 1
        elif spot == "edge":
            boarded[pending_light]["partner"] = len(boarded) - 1
            boarded[-1]["partner"] = pending_light
            pending_light = None
        total += weight
        index += 1
    return {"boarded": boarded, "denied": denied, "left_behind": left_behind,
            "total_weight": total, "capacity": capacity, "cancelled": len(boarded) == 0}


def format_report(result):
    if result["cancelled"]:
        return "Flight cancelled: the basket is completely empty at launch."
    lines = ["Lift capacity: %d kg, loaded: %d kg" % (result["capacity"], result["total_weight"])]
    seat = 0
    while seat < len(result["boarded"]):
        person = result["boarded"][seat]
        label = "VIP" if person["vip"] else "passenger"
        line = "Seat %d: %s %d kg -> %s" % (seat + 1, label, person["weight"], person["spot"])
        if person["partner"] is not None:
            line += " (paired with seat %d)" % (person["partner"] + 1)
        elif person["spot"] == "edge":
            line += " (waiting for a light partner)"
        lines.append(line)
        seat += 1
    if result["denied"]:
        lines.append("Denied boarding (zero weight): %d" % len(result["denied"]))
    if result["left_behind"]:
        lines.append("Left behind (over capacity): %d" % len(result["left_behind"]))
    return "\n".join(lines)


def main():
    queue = [(120, False, False), (45, False, False), (80, True, False),
             (0, False, False), (48, False, False), (70, False, True), (95, False, False)]
    print(format_report(balance(queue)))
    print("--- high wind ---")
    set_high_wind(True)
    print(format_report(balance(queue)))
    set_high_wind(False)
    print("--- empty basket ---")
    print(format_report(balance([(0, False, False)])))


main()

