text_nat:
MAX_WATER = 100

COSTS = {
    "desert": 5,
    "mountain": 8,
    "sandstorm": 2,
    "oasis": 0,
    "river": 0,
    "plain": 0,
}

MODIFIERS = {"heatwave", "bandit"}

ALIASES = {
    "river_crossing": "river",
    "crossing": "river",
    "storm": "sandstorm",
    "sand_storm": "sandstorm",
    "bandits": "bandit",
    "bandit_attack": "bandit",
    "heat_wave": "heatwave",
    "severe_heatwave": "heatwave",
    "flatland": "plain",
}


def parse_segment(text):
    if not isinstance(text, str):
        raise TypeError("route segments must be strings, got %r" % (text,))
    parts = [p.strip().replace(" ", "_") for p in text.lower().replace("+", ",").split(",")]
    terrain = None
    flags = set()
    for part in parts:
        if not part:
            continue
        name = ALIASES.get(part, part)
        if name in COSTS and terrain is None:
            terrain = name
        elif name in MODIFIERS:
            flags.add(name)
        else:
            raise ValueError("unknown route token: " + part)
    if terrain is None:
        raise ValueError("no terrain found in segment: " + text)
    return terrain, flags


def plan(route):
    water = MAX_WATER
    days = 0
    log = []
    i = 0
    while i < len(route):
        terrain, flags = parse_segment(route[i])
        cost = COSTS[terrain]
        if "heatwave" in flags:
            cost *= 2
        if terrain == "oasis":
            water = MAX_WATER
        else:
            water -= cost
        if "bandit" in flags:
            water -= 10
        days += 1
        if terrain == "sandstorm" or terrain == "river":
            days += 1
        log.append((i + 1, terrain, water, days))
        if water < 0:
            return {"status": "failed", "water": water, "days": days, "segments": i + 1, "log": log}
        i += 1
    return {"status": "success", "water": water, "days": days, "segments": len(route), "log": log}


def report(route):
    result = plan(route)
