def validate_dive(dive):
    if len(dive) != 2:
        raise ValueError("each dive needs exactly a depth and a time: %r" % (dive,))
    depth, time = dive
    if depth < 0:
        raise ValueError("depth cannot be negative: %r" % (depth,))
    if time <= 0:
        raise ValueError("time must be positive: %r" % (time,))
    return float(depth), float(time)


def parse_dives(text):
    lines = text.splitlines()
    records = []
    index = 0
    while index < len(lines):
        line = lines[index].strip()
        index += 1
        if not line:
            continue
        if line.startswith("#"):
            continue
        parts = line.replace(",", " ").split()
        if len(parts) != 2:
            raise ValueError("cannot read dive from line: %r" % (line,))
        records.append((float(parts[0]), float(parts[1])))
    return records


def plan(dives):
    statuses = []
    load = 0.0
    previous_deep = False
    for dive in dives:
        depth, time = validate_dive(dive)
        if depth > 30:
            load += 20
        if time > 45:
            load += 10
        if depth < 10:
            load -= 5
        if time < 20:
            load -= 2
        if load < 0:
            load = 0.0
        stop_required = load > 100
        deep = depth > 25
        if stop_required and time > 60:
            statuses.append("dangerous")
        elif deep and previous_deep:
            statuses.append("restricted")
        elif stop_required:
            statuses.append("stop required")
        else:
            statuses.append("safe")
        previous_deep = deep
    return statuses


def format_report(dives, statuses):
    lines = []
    for number, (dive, status) in enumerate(zip(dives, statuses), start=1):
        depth, time = validate_dive(dive)
        if status == "dangerous":
            mark = "!!"
        elif status == "restricted":
            mark = "><"
        elif status == "stop required":
            mark = "^ "
        else:
            mark = "  "
        lines.append("%s dive %d: %5.1f m for %4.1f min -> %s" % (mark, number, depth, time, status))
    return lines


def main():
    log = """
    # depth(m), time(min)
    12, 30
    35, 50
    32, 70
    28, 40
    27, 25
    8, 15
    """
    dives = parse_dives(log)
    statuses = plan(dives)
    for line in format_report(dives, statuses):
        print(line)
    unsafe = [status for status in statuses if status != "safe"]
    if unsafe:
        print("attention needed on %d of %d dives" % (len(unsafe), len(statuses)))
    else:
        print("all %d dives are within safe limits" % len(statuses))


if __name__ == "__main__":
    main()

