        if line.startswith("#"):
            continue
        parts = [piece.strip() for piece in line.split(",")]
        if len(parts) != 3:
            raise ValueError("expected 'family, style, age' but got: " + line)
        family, style, age_text = parts
        if not age_text.isdigit():
            raise ValueError("age must be a whole number of years: " + age_text)
        orders.append((family.lower(), style.lower(), int(age_text)))
    return orders


def temperature(family, style, age):
    """Brewing temperature in Celsius for one tea."""
    temp = DEFAULT_TEMPERATURE
    if family == "green":
        temp = 80
        if style == "powdered":
            temp = 70
    elif family == "black":
        temp = 95
        if style == "broken":
            temp = 90
    elif family == "oolong":
        if age > 5:
            temp = 100
    elif family == "white":
        temp = 85
        if style == "buds":
            temp = 75
    elif family == "herbal":
        temp = 100
    elif family == "yellow":
