        if style:
            label = family + " " + style
        labels.append(label)
    width = max(len(label) for label in labels)
    lines = []
    for label, temp in zip(labels, temperatures):
        note = "standard"
        if temp >= 100:
            note = "boiling"
        elif temp <= 75:
            note = "gentle"
        lines.append(label.ljust(width) + "  " + str(temp) + "C  " + note)
    return "\n".join(lines)


