text_nat:
KNIGHTS = ("red", "blue")
HIT_POINTS = {"shield": 1, "helmet": 2, "chest": 3, "miss": 0}
UNHORSE_BONUS = 5
WINNING_SCORE = 10


def normalize_pass(entry):
    """Validate one pass and return (color, location, unhorsed)."""
    if len(entry) != 3:
        raise ValueError("each pass needs a color, a location and an unhorsed flag")
    color, location, unhorsed = entry
    color = str(color).strip().lower()
    location = str(location).strip().lower()
    if color not in KNIGHTS:
        raise ValueError("unknown knight color: %r" % color)
    if location not in HIT_POINTS:
        raise ValueError("unknown hit location: %r" % location)
    return color, location, bool(unhorsed)


def points_for(location, unhorsed):
    """Points earned by a single pass."""
    gained = HIT_POINTS[location]
    if unhorsed:
        gained += UNHORSE_BONUS
    return gained


def describe_pass(number, color, location, unhorsed, gained):
    text = "Pass %d: %s knight hit the %s for %d" % (number, color, location, gained)
    if location == "miss":
        text = "Pass %d: %s knight missed for %d" % (number, color, gained)
    if unhorsed:
        text += " and unhorsed the opponent"
    return text


def run_match(passes):
    """Score every pass, stopping as soon as a knight passes the winning score."""
    red = 0
    blue = 0
    log = []
    index = 0
    while index < len(passes):
        color, location, unhorsed = normalize_pass(passes[index])
        gained = points_for(location, unhorsed)
        if color == "red":
            red += gained
        elif color == "blue":
            blue += gained
        index += 1
        log.append(describe_pass(index, color, location, unhorsed, gained))
        if red > WINNING_SCORE or blue > WINNING_SCORE:
            log.append("The match ends early after pass %d." % index)
            break
    return (red, blue), log


def score(passes):
    totals, _log = run_match(passes)
    return totals


def format_report(totals, log):
    red, blue = totals
    lines = list(log)
    lines.append("Final score - red: %d, blue: %d" % (red, blue))
    if red > blue:
        lines.append("The red knight takes the tournament.")
    elif blue > red:
        lines.append("The blue knight takes the tournament.")
    else:
        lines.append("The joust ends in a draw.")
    return "\n".join(lines)


def main():
    passes = [
        ("red", "shield", False),
        ("blue", "helmet", False),
        ("red", "chest", False),
        ("blue", "miss", False),
        ("red", "helmet", True),
        ("blue", "chest", True),
        ("red", "shield", False),
    ]
    totals, log = run_match(passes)
    print(format_report(totals, log))


if __name__ == "__main__":
    main()

