    return number


def is_ex_library(markings):
    if not isinstance(markings, str):
        return False
    return "ex library" in markings.lower().replace("-", " ")


def downgrade(condition):
    index = LADDER.index(condition)
    if index > 0:
        index -= 1
    return LADDER[index]


def condition_of(creases, tears, markings, water):
    marked = as_bool(markings)
    if water:
        return "poor"
    elif is_ex_library(markings):
        return "acceptable"
    elif tears > 5:
        return "fair"
    if creases == 0 and not marked and tears == 0:
        result = "mint"
    elif creases < 3 and tears == 0:
        result = "very good"
    elif marked and tears == 0 and creases < 5:
        result = "good"
    elif creases > 10:
        result = "reading copy"
    else:
        result = "acceptable"
    if tears == 1:
        result = downgrade(result)
    return result


def grade(books):
    conditions = []
    for book in books:
        if len(book) != 4:
            raise ValueError("each book needs creases, tears, markings and water damage")
        creases, tears, markings, water = book
