    records = []
    position = 0
    while position < len(lines):
        line = lines[position].strip()
        position += 1
        if not line:
            continue
        elif line.startswith("#"):
            continue
        records.append(tuple(field.strip() for field in line.split(",")))
    return records


def report(records, conditions):
    lines = []
    tally = {}
    for record, condition in zip(records, conditions):
        lines.append("creases=%s tears=%s markings=%s water=%s -> %s" % (record + (condition,)))
        if condition in tally:
            tally[condition] += 1
        else:
            tally[condition] = 1
    for name in ["poor"] + LADDER:
        if name in tally:
            lines.append("%3d x %s" % (tally[name], name))
    return "\n".join(lines)


