FAMOUS_MAKERS = {"rolex", "patek philippe", "breguet", "audemars piguet"}
UNKNOWN_MAKERS = {"unknown", "unmarked", "anonymous", ""}


def check_clock(clock):
    if len(clock) != 4:
        raise ValueError("each clock needs maker, year, condition, working")
    maker, year, condition, working = clock
    if not isinstance(maker, str):
        raise TypeError("maker must be a string")
    elif not isinstance(year, int):
        raise TypeError("year must be an integer")
    elif not isinstance(condition, str):
        raise TypeError("condition must be a string")
    elif not isinstance(working, bool):
        raise TypeError("working must be a boolean")
    return maker.strip().lower(), year, condition.strip().lower(), working


def maker_adjustment(maker):
    if maker in FAMOUS_MAKERS:
        return 1000
    elif maker in UNKNOWN_MAKERS:
        return -50
    return 0


def apply_year(amount, year):
    if year < 1800:
        return amount * 2
    elif year > 1950:
        return amount / 2
    return amount


def condition_adjustment(condition):
    if condition == "mint":
        return 500
    elif condition == "poor":
        return -200
    return 0


def value(clocks):
    results = []
    index = 0
    while index < len(clocks):
        maker, year, condition, working = check_clock(clocks[index])
        amount = 100 + maker_adjustment(maker)
        amount = apply_year(amount, year)
        amount += condition_adjustment(condition)
        if not working:
            amount = amount / 2
        elif condition == "mint":
            amount += 300
        results.append(int(amount))
        index += 1
    return results


def format_report(clocks, values):
    lines = []
    for clock, amount in zip(clocks, values):
        maker = clock[0].strip()
        if not maker:
            maker = "unmarked"
        state = "working" if clock[3] else "stopped"
        lines.append("%-16s %4d  %-5s %-8s $%d" % (maker, clock[1], clock[2], state, amount))
    return "\n".join(lines)


def main():
    collection = [
        ("Rolex", 1965, "mint", True),
        ("unknown", 1790, "poor", False),
        ("Breguet", 1780, "good", True),
        ("Smith & Sons", 1972, "fair", False),
        ("", 1955, "mint", True),
    ]
    values = value(collection)
    print(format_report(collection, values))
    total = sum(values)
    print("total: $%d" % total)
    if total > 5000:
        print("insurance appraisal recommended")
    elif total > 1000:
        print("worth a written inventory")


