TOLERANCE = 5.0
EXTREME = 20.0


def normalize_flour(name):
    if not isinstance(name, str):
        raise TypeError("flour type must be a string")
    text = name.strip().lower().replace("-", " ").replace("_", " ")
    while "  " in text:
        text = text.replace("  ", " ")
    return text


def target_for(flour_type):
    kind = normalize_flour(flour_type)
    if kind == "gluten free":
        return 90.0
    elif kind == "rye":
        return 80.0
    elif kind == "whole wheat":
        return 75.0
    elif kind == "bread":
        return 70.0
    elif kind == "pastry":
        return 60.0
    raise ValueError("unknown flour type: " + kind)


def hydration(flour_weight, water_weight):
    if flour_weight <= 0:
        raise ValueError("flour weight must be positive")
    elif water_weight < 0:
        raise ValueError("water weight cannot be negative")
    return 100.0 * water_weight / flour_weight


def classify(value, target):
    difference = value - target
    if abs(difference) > EXTREME:
        return "extreme - rejected"
    elif difference == 0:
        return "perfect"
    elif difference < -TOLERANCE:
        return "add water"
    elif difference > TOLERANCE:
        return "add flour"
    return "within tolerance"


def calculate(recipes):
    results = []
    for recipe in recipes:
        if len(recipe) != 3:
            raise ValueError("each recipe needs flour, water and a flour type")
        flour_weight, water_weight, flour_type = recipe
        results.append(classify(hydration(flour_weight, water_weight), target_for(flour_type)))
    return results


def format_report(recipes, results):
    lines = []
    index = 0
    while index < len(results):
        flour_weight, water_weight, flour_type = recipes[index]
        value = hydration(flour_weight, water_weight)
        lines.append("%-12s %6.1f%% (target %4.1f%%) -> %s"
                     % (normalize_flour(flour_type), value,
                        target_for(flour_type), results[index]))
        index += 1
    return lines


def main():
    recipes = [
        (1000, 800, "rye"),
        (1000, 750, "Whole-Wheat"),
        (1000, 620, "bread"),
        (500, 250, "pastry"),
        (1000, 900, "gluten free"),
        (1000, 450, "rye"),
    ]
    results = calculate(recipes)
    rejected = 0
    for line in format_report(recipes, results):
        print(line)
    for result in results:
        if result.endswith("rejected"):
            rejected += 1
    print("%d of %d recipes rejected" % (rejected, len(results)))


main()

