import sys

PREMIUM = "premium mixed blend"


def normalize(name):
    if not isinstance(name, str):
        raise TypeError("bird species must be given as strings")
    cleaned = name.strip().lower()
    while "  " in cleaned:
        cleaned = cleaned.replace("  ", " ")
    return cleaned


def seed_for(species):
    if species == "cardinal":
        return "black oil sunflower"
    elif species == "goldfinch":
        return "nyjer"
    elif species == "woodpecker":
        return "suet"
    elif species == "mourning dove":
        return "white proso millet"
    elif species == "jay":
        return "peanuts"
    elif species == "hummingbird":
        return "nectar"
    elif species == "sparrow":
        return "cracked corn"
    elif species == "crow":
        return "whole corn"
    return None


def recommend(birds):
    seeds = []
    for bird in birds:
        species = normalize(bird)
        if not species:
            continue
        seed = seed_for(species)
        if seed is None:
            continue
        if seed not in seeds:
            seeds.append(seed)
        if len(seeds) > 4:
            seeds.clear()
            seeds.append(PREMIUM)
            break
