INF = float("inf")
EXTREME_CM = 8.0
DELAY = "delay pruning to protect buds"
SEASONS = ("spring", "summer", "autumn", "winter")
DECIDUOUS = ("deciduous", "maple", "oak", "elm", "birch", "beech")
FLOWERING = ("flowering", "cherry", "azalea", "lilac", "magnolia")


def _clean(value):
    if not isinstance(value, str):
        raise TypeError("species and season must be strings, got %r" % (value,))
    return value.strip().lower()


def parse_thickness(value):
    """Accept a number, a measurement like '3 cm', or the word 'extreme'."""
    if isinstance(value, str):
        text = _clean(value)
        if text == "extreme":
            return INF
        while text and text[-1].isalpha():
            text = text[:-1]
        text = text.strip()
        if not text:
            raise ValueError("unreadable thickness: %r" % (value,))
        number = float(text)
    else:
        number = float(value)
    if number < 0:
        raise ValueError("thickness cannot be negative: %r" % (value,))
    elif number >= EXTREME_CM:
        return INF
    return number


def plan_action(species, season, thickness):
    if species in FLOWERING and season == "spring":
        return DELAY
    elif thickness == INF:
        return "cut back with a handsaw"
    elif species == "pine" and season == "spring":
        return "pinch candles"
    elif species == "maple" and season == "winter":
        return "structural prune"
    elif species == "juniper" and season == "summer":
        return "thin foliage"
    elif season == "autumn" and species in DECIDUOUS:
        return "minimal trim"
    return "light shaping"


def prune(trees):
    actions = []
    for tree in trees:
        if len(tree) < 3:
            raise ValueError("each tree needs species, season and thickness: %r" % (tree,))
        species = _clean(tree[0])
        season = _clean(tree[1])
        if season not in SEASONS:
            raise ValueError("unknown season: %r" % (tree[1],))
        thickness = parse_thickness(tree[2])
        notes = _clean(tree[3]) if len(tree) > 3 else ""
        steps = [plan_action(species, season, thickness)]
        if steps[0] != DELAY:
            if thickness > 2:
                steps.append("apply cut paste")
            if "root" in notes and "expos" in notes:
                steps.append("repot")
        actions.append("; ".join(steps))
    return actions


def report(trees):
    lines = []
    for tree, action in zip(trees, prune(trees)):
        lines.append("%s in %s -> %s" % (tree[0], tree[1], action))
    return lines


def main():
    garden = [
        ("Pine", "spring", 1),
        ("Maple", "winter", "4 cm"),
        ("Juniper", "summer", 2.5),
        ("Oak", "autumn", "3cm", "roots exposed"),
        ("Cherry", "spring", 5),
        ("Elm", "summer", "extreme"),
    ]
    for line in report(garden):
        print(line)


