def is_prime(n):
    """Return True if the positive integer n is prime, False otherwise."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be a positive integer")
    if n < 4:
        return n > 1
    if n % 2 == 0 or n % 3 == 0:
        return False
    step = 2
    divisor = 5
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += step
        step = 6 - step
    return True


def next_prime(n):
    """Return the smallest prime strictly greater than n."""
    if n < 2:
        return 2
    candidate = n + 1
    if candidate % 2 == 0:
        candidate += 1
    while not is_prime(candidate):
        candidate += 2
    return candidate


def prime_factors(n):
    """Return the prime factors of n (with multiplicity) in ascending order."""
    if n < 1:
        raise ValueError("n must be a positive integer")
    factors = []
    remaining = n
    factor = 2
    while factor * factor <= remaining:
        while remaining % factor == 0:
            factors.append(factor)
            remaining //= factor
        if factor == 2:
            factor = 3
        else:
            factor += 2
    if remaining > 1:
        factors.append(remaining)
    return factors


def describe(n):
    """Build a human-readable report line about the number n."""
    if is_prime(n):
        return "{0} is prime; the next prime is {1}.".format(n, next_prime(n))
    elif n == 1:
        return "1 is neither prime nor composite."
    parts = "*".join(str(f) for f in prime_factors(n))
    return "{0} is composite: {0} = {1}.".format(n, parts)


def primes_up_to(limit):
    """Return every prime number that is not greater than limit."""
    primes = []
    for value in range(1, limit + 1):
        if is_prime(value):
            primes.append(value)
    return primes


def twin_pairs(primes, limit):
    """Return the twin prime pairs (p, p + 2) with both members up to limit."""
    pairs = []
    for p in primes:
        if p + 2 <= limit and is_prime(p + 2):
            pairs.append((p, p + 2))
    return pairs


def main():
    for value in [1, 2, 7, 10, 91, 97, 561, 7919, 104729, 104730]:
        print(describe(value))
    limit = 50
    primes = primes_up_to(limit)
    print("Primes up to {0}: {1}".format(limit, primes))
    print("Twin prime pairs up to {0}: {1}".format(limit, twin_pairs(primes, limit)))


main()

