import sys


def tokenize(sentence):
    """Split a sentence into words, dropping surrounding punctuation."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")
    words = []
    for chunk in sentence.split():
        cleaned = chunk.strip(".,;:!?\"'()[]{}")
        if cleaned:
            words.append(cleaned)
    return words


def find_longest_word(sentence):
    """Return the first longest word of the sentence, or '' when there is none."""
    longest = ""
    for word in tokenize(sentence):
        if len(word) > len(longest):
            longest = word
    return longest


def average_length(sentence):
    """Return the mean word length, or 0.0 for a sentence without words."""
    words = tokenize(sentence)
    if not words:
        return 0.0
    total = 0
    for word in words:
        total += len(word)
    return total / len(words)


def ties_for_longest(sentence):
    """Return every word sharing the maximum length, first occurrence first."""
    best = find_longest_word(sentence)
    if not best:
        return []
    return [word for word in tokenize(sentence) if len(word) == len(best)]


def describe(sentence):
    """Build a one-line report about the words of the sentence."""
    words = tokenize(sentence)
    if not words:
        return "no words found"
    longest = find_longest_word(sentence)
    tied = ties_for_longest(sentence)
    report = "%d words, longest %r (%d chars), average %.2f" % (
        len(words), longest, len(longest), average_length(sentence))
    if len(tied) > 1:
        report += ", tied with " + ", ".join(repr(w) for w in tied[1:])
    return report


def read_sentences(argv):
    """Take the sentence from the command line, else read one per input line."""
    if len(argv) > 1:
        return [" ".join(argv[1:])]
    return [line.rstrip("\n") for line in sys.stdin]


