    sentences = read_sentences(argv)
    index = 0
    while index < len(sentences):
        sentence = sentences[index]
        print("input : %r" % sentence)
        print("result: %s" % describe(sentence))
        index += 1
    return 0


sys.exit(main(sys.argv))

