def _validate(name, value):
    if not isinstance(value, (list, tuple)):
        raise TypeError(name + " must be a list or tuple, got " + type(value).__name__)
    return list(value)


def _is_hashable(value):
    try:
        hash(value)
    except TypeError:
        return False
    return True


def list_intersection(list1, list2):
    """Return the common elements of two lists, keeping list1's order."""
    items1 = _validate("list1", list1)
    items2 = _validate("list2", list2)
    if not items1 or not items2:
        return []
    hashable = [x for x in items2 if _is_hashable(x)]
    if len(hashable) == len(items2):
        pool = set(hashable)
    else:
        pool = items2
    result = []
    for item in items1:
        if item not in pool:
            continue
        elif item in result:
            continue
        result.append(item)
    return result


def intersection_all(lists):
    """Intersect an arbitrary number of lists, left to right."""
    remaining = _validate("lists", lists)
    if not remaining:
        return []
    current = _validate("lists[0]", remaining[0])
    index = 1
    while index < len(remaining) and current:
        current = list_intersection(current, remaining[index])
        index += 1
    return current


def describe(list1, list2):
    """Build a one-line human readable report about two lists."""
    common = list_intersection(list1, list2)
    if not common:
        summary = "no common elements"
    elif len(common) == 1:
        summary = "1 common element: " + repr(common[0])
    else:
        summary = str(len(common)) + " common elements: " + repr(common)
    return repr(list(list1)) + " vs " + repr(list(list2)) + " -> " + summary


def main():
    pairs = [
        ([1, 2, 3], [3, 4, 5]),
        ([1, 2], [3, 4]),
        (["a", "b", "b", "c"], ["b", "c", "c"]),
        ([[1], [2]], [[2], [3]]),
        ([], [1, 2, 3]),
    ]
    for left, right in pairs:
        print(describe(left, right))
    chain = [[1, 2, 3, 4], [2, 3, 4, 5], [3, 4, 9]]
    shared = intersection_all(chain)
    if shared:
        print("shared across " + str(len(chain)) + " lists: " + repr(shared))
    else:
        print("shared across " + str(len(chain)) + " lists: none")


main()

