def merge_dictionaries(dict1, dict2):
    """Return a new dict with all pairs from both; dict2 wins on conflicts."""
    if not isinstance(dict1, dict):
        raise TypeError("dict1 must be a dictionary")
    if not isinstance(dict2, dict):
        raise TypeError("dict2 must be a dictionary")
    merged = {}
    for key in dict1:
        merged[key] = dict1[key]
    for key in dict2:
        merged[key] = dict2[key]
    return merged


def merge_all(dicts):
    """Fold merge_dictionaries over a sequence of dictionaries."""
    result = {}
    for item in dicts:
        result = merge_dictionaries(result, item)
    return result


def deep_merge(dict1, dict2):
    """Like merge_dictionaries, but nested dictionaries are merged recursively."""
    merged = merge_dictionaries(dict1, dict2)
    for key in dict2:
        if key not in dict1:
            continue
        left = dict1[key]
        right = dict2[key]
        if isinstance(left, dict) and isinstance(right, dict):
            merged[key] = deep_merge(left, right)
    return merged


def conflicts(dict1, dict2):
    """Keys present in both dictionaries whose values actually differ."""
    found = {}
    for key in dict1:
        if key not in dict2:
            continue
        if dict1[key] != dict2[key]:
            found[key] = (dict1[key], dict2[key])
    return found


def format_report(dict1, dict2):
    """Human readable summary of merging dict1 with dict2."""
    merged = merge_dictionaries(dict1, dict2)
    clashes = conflicts(dict1, dict2)
    lines = ["merged: " + repr(merged)]
    if not clashes:
        lines.append("no overriding took place")
    elif len(clashes) == 1:
        lines.append("1 key overridden:")
    else:
        lines.append("{} keys overridden:".format(len(clashes)))
    for key in sorted(clashes, key=str):
        old, new = clashes[key]
        lines.append("  {!r}: {!r} -> {!r}".format(key, old, new))
    return "\n".join(lines)


def main():
    print(format_report({'a': 1, 'b': 2}, {'b': 3, 'c': 4}))
    print(format_report({'x': 1}, {'y': 2}))
    settings = merge_all([
        {'host': 'localhost', 'port': 80, 'debug': False},
        {'port': 8080},
        {'debug': True},
    ])
    print("settings:", settings)
    if settings['debug']:
        print("debug mode is on")
    profile = deep_merge(
        {'user': {'name': 'ada', 'lang': 'en'}, 'theme': 'light'},
        {'user': {'lang': 'fr'}, 'theme': 'dark'},
    )
    print("profile:", profile)


main()

