import math
import sys


def validate(numbers):
    """Return the values as floats, raising ValueError on bad input."""
    if numbers is None:
        raise ValueError("no data given")
    values = []
    for item in numbers:
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise ValueError("not a number: %r" % (item,))
        value = float(item)
        if value <= 0.0:
            raise ValueError("values must be positive, got %g" % value)
        values.append(value)
    if len(values) == 0:
        raise ValueError("cannot take the geometric mean of an empty list")
    return values


def geometric_mean(numbers):
    """Nth root of the product of N positive numbers."""
    values = validate(numbers)
    total = math.fsum(math.log(value) for value in values)
    result = math.exp(total / len(values))
    rounded = round(result)
    if abs(result - rounded) < 1e-9:
        return float(rounded)
    return result


def arithmetic_mean(numbers):
    values = validate(numbers)
    return math.fsum(values) / len(values)


def harmonic_mean(numbers):
    values = validate(numbers)
    return len(values) / math.fsum(1.0 / v for v in values)


def parse_numbers(text):
    """Read whitespace or comma separated numbers from a string."""
    numbers = []
    for token in text.replace(",", " ").split():
        try:
