def guess_number(secret_number, guess):
    """Compare a guess against the secret number and describe the result."""
    if guess > secret_number:
        return 'Too high'
    elif guess < secret_number:
        return 'Too low'
    return 'Correct!'


def parse_guess(text, low=1, high=100):
    """Turn raw user text into an integer guess, or raise ValueError."""
    cleaned = text.strip()
    if not cleaned:
        raise ValueError('no guess entered')
    try:
        value = int(cleaned)
    except ValueError:
        raise ValueError('%r is not a whole number' % cleaned)
    if value < low or value > high:
        raise ValueError('%d is outside the range %d-%d' % (value, low, high))
    return value


def play_round(secret_number, raw_guesses, low=1, high=100):
    """Feed a sequence of raw guesses to the game, stopping once solved."""
    history = []
    for raw in raw_guesses:
        try:
            guess = parse_guess(raw, low, high)
        except ValueError as err:
            history.append((raw, 'Invalid: %s' % err))
            continue
        verdict = guess_number(secret_number, guess)
        history.append((guess, verdict))
        if verdict == 'Correct!':
            break
    return history


def solve(secret_number, low=1, high=100):
    """Play the game automatically with a binary search; return the guesses."""
    guesses = []
    while low <= high:
        middle = (low + high) // 2
        verdict = guess_number(secret_number, middle)
        guesses.append(middle)
        if verdict == 'Correct!':
            return guesses
        elif verdict == 'Too high':
            high = middle - 1
        else:
            low = middle + 1
    raise ValueError('secret number %d is not in range' % secret_number)


def format_history(history):
    """Render a played round as numbered lines of feedback."""
    lines = []
    for index, (guess, verdict) in enumerate(history, start=1):
        lines.append('%d. %s -> %s' % (index, guess, verdict))
    if not history:
        lines.append('no guesses were made')
    elif history[-1][1] != 'Correct!':
        lines.append('out of guesses; the answer was hidden')
    return '\n'.join(lines)


def main():
    secret = 10
    print(format_history(play_round(secret, ['12', 'seven', '3', '10', '5'])))
    for target in (1, 37, 100):
        path = solve(target)
        print('%d found in %d guesses: %s' % (target, len(path), path))


main()

