def calculate_bmi(weight_kg, height_m):
    """Return the Body Mass Index rounded to two decimals."""
    if not isinstance(weight_kg, (int, float)) or not isinstance(height_m, (int, float)):
        raise TypeError("weight and height must be numbers")
    if weight_kg <= 0:
        raise ValueError("weight must be positive")
    elif height_m <= 0:
        raise ValueError("height must be positive")
    return round(weight_kg / height_m ** 2, 2)


def classify_bmi(bmi):
    """Map a BMI value onto the standard WHO category names."""
    if bmi < 18.5:
        return "underweight"
    elif bmi < 25.0:
        return "normal weight"
    elif bmi < 30.0:
        return "overweight"
    return "obese"


def parse_record(line):
    """Parse 'name,weight,height' into a (name, weight, height) tuple."""
    fields = line.split(",")
    if len(fields) != 3:
        raise ValueError("expected three comma-separated fields: " + line)
    name = fields[0].strip()
    if not name:
        raise ValueError("missing name in record: " + line)
    return name, float(fields[1]), float(fields[2])


def healthy_weight_range(height_m):
    """Return the weight bounds that keep the BMI in the normal band."""
    low = 18.5 * height_m ** 2
    high = 24.9 * height_m ** 2
    return round(low, 1), round(high, 1)


def advise(weight_kg, height_m):
    """Describe how far the weight is from the healthy range."""
    low, high = healthy_weight_range(height_m)
    if weight_kg < low:
        return "gain %.1f kg to reach the healthy range" % (low - weight_kg)
    elif weight_kg > high:
        return "lose %.1f kg to reach the healthy range" % (weight_kg - high)
    return "already within the healthy range"


def report(records):
    """Build one formatted report line per valid record, skipping bad ones."""
    lines = []
    index = 0
    while index < len(records):
        raw = records[index].strip()
        index += 1
        if not raw or raw.startswith("#"):
            continue
        try:
            name, weight, height = parse_record(raw)
            bmi = calculate_bmi(weight, height)
        except ValueError as exc:
            lines.append("skipped: %s" % exc)
            continue
        lines.append("%-8s BMI %5.2f  %-13s (%s)" % (name, bmi, classify_bmi(bmi), advise(weight, height)))
    return lines


def main():
    data = [
        "# name,weight_kg,height_m",
        "Ada,70,1.75",
        "Linus,100,2.0",
        "Grace,45,1.68",
        "Broken,80",
        "",
    ]
    for line in report(data):
        print(line)


main()

