def validate_operation(op):
    """Return the normalised (action, item) pair, raising ValueError when invalid."""
    if not isinstance(op, tuple) and not isinstance(op, list):
        raise ValueError("each operation must be a tuple or list")
    if len(op) != 2:
        raise ValueError("each operation must have exactly two elements")
    action, item = op[0], op[1]
    if not isinstance(action, str):
        raise ValueError("the action must be a string")
    action = action.strip().lower()
    if action not in ("enqueue", "dequeue"):
        raise ValueError("unknown action: %r" % (op[0],))
    if action == "dequeue" and item is not None:
        raise ValueError("a dequeue operation carries no item")
    return action, item


def simulate_queue(operations):
    """Simulate a FIFO queue backed by a list and return its final contents."""
    queue = []
    for op in operations:
        action, item = validate_operation(op)
        if action == "enqueue":
            queue.append(item)
        elif queue:
            queue.pop(0)
    return queue


def drain_queue(queue):
    """Remove and return every element of queue, front first."""
    drained = []
    while queue:
        drained.append(queue.pop(0))
    return drained


def describe_operation(op):
    """Render a single operation as a short human readable string."""
    action, item = validate_operation(op)
    if action == "dequeue":
        return "dequeue"
    return "enqueue %r" % (item,)


def report(operations):
    """Build a multi-line report of the operations and the resulting queue."""
    lines = []
    for index, op in enumerate(operations, start=1):
        lines.append("%2d. %s" % (index, describe_operation(op)))
    final = simulate_queue(operations)
    if not final:
        lines.append("final queue: empty")
    else:
        lines.append("final queue: %s (front = %r)" % (final, final[0]))
    return "\n".join(lines)


def main():
    samples = [
        [("enqueue", 1), ("enqueue", 2), ("dequeue", None)],
        [("dequeue", None)],
        [("enqueue", "a"), ("dequeue", None), ("enqueue", "b"), ("enqueue", "c")],
    ]
    for sample in samples:
        print(report(sample))
        print("-" * 40)

    leftovers = simulate_queue(samples[2])
    order = drain_queue(leftovers)
    if order:
        print("drained in order:", order)
    else:
        print("nothing left to drain")


main()

