def is_tag_char(ch):
    return ch.isalnum() or ch == '_'


def extract_hashtags(text):
    """Return the hashtags found in text, without the leading '#'."""
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    tags = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] != '#':
            i += 1
            continue
        if i > 0 and is_tag_char(text[i - 1]):
            i += 1
            continue
        j = i + 1
        while j < n and is_tag_char(text[j]):
            j += 1
        if j > i + 1:
            tags.append(text[i + 1:j])
        i = j
    return tags


def normalize(tag):
    """Lower-case a hashtag and strip trailing digits used as counters."""
    tag = tag.lower()
    end = len(tag)
    while end > 1 and tag[end - 1].isdigit():
        end -= 1
    return tag[:end]


def count_hashtags(texts, fold_case=True):
    counts = {}
    for text in texts:
        for tag in extract_hashtags(text):
            key = normalize(tag) if fold_case else tag
            if key in counts:
                counts[key] += 1
            else:
                counts[key] = 1
    return counts


def format_report(counts, limit=5):
    if not counts:
        return 'no hashtags found'
    items = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    lines = []
    for name, total in items[:limit]:
        if total == 1:
            lines.append('#%s: once' % name)
        else:
            lines.append('#%s: %d times' % (name, total))
    hidden = len(items) - limit
    if hidden > 0:
        lines.append('... and %d more' % hidden)
    return '\n'.join(lines)


def main():
    samples = [
        'This is a #test with #python.',
        'No hashtags here.',
        'Loving #Python3 and #python again, mail me at user#example',
        '#test #TEST2 #_private # empty',
    ]
    for text in samples:
        print('%-52r -> %s' % (text, extract_hashtags(text)))
    print()
    print(format_report(count_hashtags(samples), limit=3))


main()

