import sys


def validate_numbers(numbers):
    """Check that numbers is a sequence of at least two plain integers."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    if len(numbers) < 2:
        raise ValueError("numbers must contain at least two elements")
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("numbers must contain integers only")


def find_second_largest(numbers):
    """Return the second largest element of numbers (duplicates included)."""
    validate_numbers(numbers)
    first, second = numbers[0], numbers[1]
    if second > first:
        first, second = second, first
    for value in numbers[2:]:
        if value >= first:
            second = first
            first = value
        elif value > second:
            second = value
    return second


def parse_line(line):
    """Turn a comma or space separated line into a list of integers."""
    tokens = line.replace(",", " ").split()
    numbers = []
    index = 0
    while index < len(tokens):
        token = tokens[index]
        if token.lstrip("+-").isdigit():
            numbers.append(int(token))
        else:
            raise ValueError("not an integer: " + token)
        index += 1
    return numbers


def format_report(numbers):
    """Build a one line summary of the largest and second largest values."""
    largest = max(numbers)
    second = find_second_largest(numbers)
    gap = largest - second
    parts = ["values=" + repr(numbers), "largest=%d" % largest, "second=%d" % second]
    if gap == 0:
        parts.append("the top value is repeated")
    elif gap > 5:
        parts.append("clear gap of %d" % gap)
    return " | ".join(parts)


