def normalize(binary_string):
    """Strip whitespace and an optional '0b' prefix from a binary literal."""
    if not isinstance(binary_string, str):
        raise TypeError("binary_string must be a str")
    text = binary_string.strip()
    if text.lower().startswith("0b"):
        text = text[2:]
    if text == "":
        raise ValueError("binary_string must contain at least one digit")
    return text


def validate(digits):
    """Raise ValueError on the first character that is not a binary digit."""
    for index, char in enumerate(digits):
        if char != "0" and char != "1":
            raise ValueError(
                "invalid binary digit %r at position %d" % (char, index)
            )
    return digits


def binary_to_decimal(binary_string):
    """Convert a binary string such as '1011' to its decimal value (11)."""
    digits = validate(normalize(binary_string))
    value = 0
    for char in digits:
        value = value * 2
        if char == "1":
            value += 1
    return value


def decimal_to_binary(number):
    """Inverse of binary_to_decimal, used to echo a canonical form."""
    if number < 0:
        raise ValueError("only non-negative integers are supported")
    if number == 0:
        return "0"
    digits = []
    while number > 0:
        digits.append(str(number % 2))
        number //= 2
    digits.reverse()
    return "".join(digits)


def describe(binary_string):
    """Return a one-line report about the conversion of one input string."""
    try:
        value = binary_to_decimal(binary_string)
    except (TypeError, ValueError) as error:
        return "%-12s -> error: %s" % (repr(binary_string), error)
    canonical = decimal_to_binary(value)
    note = ""
    if canonical != normalize(binary_string):
        note = "  (canonical form: %s)" % canonical
    elif value % 2 == 0:
        note = "  (even)"
    return "%-12s -> %d%s" % (repr(binary_string), value, note)


def main():
    samples = ["1011", "1", "0", "0b1111", " 100000 ", "00101", "1021", ""]
    total = 0
    for sample in samples:
        print(describe(sample))
        try:
            total += binary_to_decimal(sample)
        except (TypeError, ValueError):
            continue
    print("sum of valid values: %d (binary %s)" % (total, decimal_to_binary(total)))


