import math


def parse_numbers(text):
    values = []
    for token in text.replace(",", " ").split():
        try:
            values.append(float(token))
        except ValueError:
            raise ValueError("not a number: " + token)
    if len(values) < 2:
        raise ValueError("need at least two numbers")
    return values


def calculate_mean(numbers):
    total = 0.0
    for value in numbers:
        total += value
    return total / len(numbers)


def calculate_std_dev(numbers):
    n = len(numbers)
    mean = calculate_mean(numbers)
    squared = 0.0
    for value in numbers:
        diff = value - mean
        squared += diff * diff
    if squared <= 0.0:
        return 0.0
    return math.sqrt(squared / (n - 1))


def describe_spread(numbers):
    sd = calculate_std_dev(numbers)
    mean = calculate_mean(numbers)
    if sd == 0.0:
        return "all values identical"
    elif mean == 0.0:
        return "spread %.3f around zero" % sd
    ratio = abs(sd / mean)
    if ratio < 0.1:
        label = "tight"
    elif ratio < 0.5:
        label = "moderate"
    else:
        label = "wide"
    return "spread %.3f (%s, cv=%.2f)" % (sd, label, ratio)


def outliers(numbers, threshold=2.0):
    sd = calculate_std_dev(numbers)
    if sd == 0.0:
        return []
    mean = calculate_mean(numbers)
    found = []
    for value in numbers:
        if abs(value - mean) / sd >= threshold:
            found.append(value)
    return found


def main():
