def validate_numbers(numbers):
    """Return a list of numeric values, raising informative errors on bad input."""
    if (numbers is None):
        raise ValueError("numbers must not be None")
    if (not isinstance(numbers, (list, tuple))):
        raise TypeError("numbers must be a list or tuple")
    if (len(numbers) == 0):
        raise ValueError("median of an empty sequence is undefined")
    cleaned = []
    for item in numbers:
        if (isinstance(item, bool)):
            raise TypeError("booleans are not valid numbers")
        elif (isinstance(item, (int, float))):
            cleaned.append(item)
        else:
            raise TypeError("unsupported value: %r" % (item,))
    return cleaned


def calculate_median(numbers):
    """Median of a list of ints/floats; average of the two middle values if even."""
    values = sorted(validate_numbers(numbers))
    size = len(values)
    middle = size // 2
    if (size % 2 == 1):
        median_value = values[middle]
    else:
        low = values[middle - 1]
        high = values[middle]
        median_value = (low + high) / 2
        if (median_value == int(median_value)):
            median_value = int(median_value)
    return median_value


def parse_numbers(text):
    """Turn a whitespace/comma separated string into a list of numbers."""
    tokens = text.replace(",", " ").split()
    parsed = []
    index = 0
    while (index < len(tokens)):
        token = tokens[index]
        index += 1
        if (token.lstrip("+-").isdigit()):
            parsed.append(int(token))
        else:
            parsed.append(float(token))
    return parsed


def format_median(numbers):
    """Build a one-line report describing the median of the given numbers."""
    try:
        median_value = calculate_median(numbers)
    except (TypeError, ValueError) as exc:
        return "error: %s" % exc
    if (isinstance(median_value, int)):
        shown = str(median_value)
    elif (median_value == round(median_value, 3)):
        shown = "%g" % median_value
    else:
        shown = "%.3f" % median_value
    return "median of %d value(s) -> %s" % (len(numbers), shown)


def main(argv):
    """Report the median of numbers given as arguments, or one line of input each."""
    if (argv):
        lines = [" ".join(argv)]
    else:
        lines = [line for line in sys.stdin if line.strip()]
    for line in lines:
        try:
            numbers = parse_numbers(line)
        except ValueError:
            print("error: could not parse %r" % line.strip())
            continue
        print(format_median(numbers))


main(sys.argv[1:])

