def is_armstrong(number):
    """Return True if `number` equals the sum of its digits raised to the digit count."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be an int")
    if number <= 0:
        raise ValueError("number must be a positive integer")
    digits = digits_of(number)
    power = len(digits)
    total = 0
    for digit in digits:
        total += digit ** power
        if total > number:
            return False
    return total == number


def digits_of(number):
    """Return the decimal digits of a positive integer, most significant first."""
    digits = []
    while number > 0:
        digits.append(number % 10)
        number //= 10
    digits.reverse()
    return digits


def armstrong_numbers_upto(limit):
    """Return every Armstrong number from 1 to `limit` inclusive."""
    if limit < 1:
        return []
    found = []
    candidate = 1
    while candidate <= limit:
        if is_armstrong(candidate):
            found.append(candidate)
        candidate += 1
    return found


def explain(number):
    """Build a human readable expansion such as '153 = 1^3 + 5^3 + 3^3 = 153'."""
    digits = digits_of(number)
    power = len(digits)
    terms = " + ".join("{}^{}".format(d, power) for d in digits)
    total = sum(d ** power for d in digits)
    verdict = "Armstrong" if total == number else "not Armstrong"
    return "{} = {} = {} ({})".format(number, terms, total, verdict)


def parse_number(text):
    """Convert user supplied text into a positive integer, or None when invalid."""
    stripped = text.strip()
    if not stripped:
        return None
    if stripped.startswith("+"):
        stripped = stripped[1:]
    if not stripped.isdigit():
        return None
    value = int(stripped)
    if value == 0:
        return None
    return value


def main():
    samples = ["153", "123", "9474", " 407 ", "0", "twelve"]
    for sample in samples:
        number = parse_number(sample)
        if number is None:
            print("{!r}: not a positive integer".format(sample))
        elif is_armstrong(number):
            print(explain(number))
        else:
            print("{} is not an Armstrong number".format(number))
    print("Armstrong numbers up to 1000:", armstrong_numbers_upto(1000))


main()

