def _is_hashable(value):
    try:
        hash(value)
    except TypeError:
        return False
    return True


def _validate_list(name, candidate):
    if not isinstance(candidate, list):
        raise TypeError(name + " must be a list, got " + type(candidate).__name__)
    return candidate


def _build_lookup(values):
    """Split values into a set of hashable items and a list of the rest."""
    hashable = set()
    unhashable = []
    for value in values:
        if _is_hashable(value):
            hashable.add(value)
        else:
            unhashable.append(value)
    return hashable, unhashable


def list_difference(list1, list2):
    _validate_list("list1", list1)
    _validate_list("list2", list2)
    hashable, unhashable = _build_lookup(list2)
    difference_list = []
    for item in list1:
        if _is_hashable(item):
            if item in hashable:
                continue
        elif item in unhashable:
            continue
        difference_list.append(item)
    return difference_list


def unique_difference(list1, list2):
    """Difference with duplicates removed, order preserved."""
    result = []
    for item in list_difference(list1, list2):
        if item in result:
            continue
        result.append(item)
    return result


def format_difference(list1, list2):
    difference_list = list_difference(list1, list2)
    if not difference_list:
        return "no elements of list1 are missing from list2"
    parts = [repr(value) for value in difference_list]
    label = "element"
    if len(parts) > 1:
        label = "elements"
    return "%d %s only in list1: %s" % (len(parts), label, ", ".join(parts))


def main():
    cases = [
        ([1, 2, 3, 4], [3, 4, 5, 6]),
        (['a', 'b'], ['c', 'd']),
        ([1, 1, 2, 2, 3], [3]),
        ([[1], [2], 5], [[2]]),
        ([7, 8], [7, 8]),
    ]
    for list1, list2 in cases:
        difference = list_difference(list1, list2)
        print(list1, "-", list2, "=", difference)
        print("   ", format_difference(list1, list2))
        squeezed = unique_difference(list1, list2)
        if squeezed != difference:
            print("    without duplicates:", squeezed)


if __name__ == "__main__":
    main()

