def update_dict(dict1, dict2):
    """Merge dict2 into a copy of dict1 and return the result."""
    if not isinstance(dict1, dict):
        raise TypeError("dict1 must be a dict, got %s" % type(dict1).__name__)
    if not isinstance(dict2, dict):
        raise TypeError("dict2 must be a dict, got %s" % type(dict2).__name__)
    merged_dict = dict(dict1)
    for key, value in dict2.items():
        merged_dict[key] = value
    return merged_dict


def deep_update_dict(dict1, dict2):
    """Like update_dict, but nested dicts are merged instead of replaced."""
    merged_dict = update_dict(dict1, dict2)
    for key, value in dict2.items():
        old = dict1.get(key)
        if isinstance(old, dict) and isinstance(value, dict):
            merged_dict[key] = deep_update_dict(old, value)
    return merged_dict


def overlapping_keys(dict1, dict2):
    """Return the keys present in both dictionaries, in dict1's order."""
    shared = []
    for key in dict1:
        if key in dict2:
            shared.append(key)
    return shared


def merge_all(dicts):
    """Fold a sequence of dictionaries left to right into one dictionary."""
    result = {}
    index = 0
    while index < len(dicts):
        result = update_dict(result, dicts[index])
        index += 1
    return result


def describe_merge(dict1, dict2):
    """Build a human readable summary of what a merge would change."""
    lines = []
    shared = overlapping_keys(dict1, dict2)
    if shared:
        for key in shared:
            lines.append("update %r: %r -> %r" % (key, dict1[key], dict2[key]))
    else:
        lines.append("no overlapping keys")
    added = [key for key in dict2 if key not in dict1]
    while added:
        key = added.pop(0)
        lines.append("add %r: %r" % (key, dict2[key]))
    return "\n".join(lines)


def main():
    left = {'a': 1, 'b': 2}
    right = {'b': 3, 'c': 4}
    print(update_dict(left, right))
    print(update_dict({'x': 10}, {'y': 20}))
    print(describe_merge(left, right))

    settings = {'host': 'localhost', 'opts': {'debug': False, 'level': 1}}
    override = {'opts': {'level': 3}, 'port': 8080}
    flat = update_dict(settings, override)
    deep = deep_update_dict(settings, override)
    if flat['opts'] == deep['opts']:
        print("flat and deep merges agree on 'opts'")
    else:
        print("flat opts:", flat['opts'])
        print("deep opts:", deep['opts'])

    print(merge_all([{'a': 1}, {'a': 2, 'b': 2}, {'c': 3}]))


main()

