def simulate_guess(target, guess):
    """Return feedback for a single guess against the target."""
    if not isinstance(target, int) or isinstance(target, bool):
        raise TypeError("target must be an int")
    if not isinstance(guess, int) or isinstance(guess, bool):
        raise TypeError("guess must be an int")
    if guess > target:
        return 'Too high'
    elif guess < target:
        return 'Too low'
    return 'Correct!'


def parse_guess(text, low=1, high=100):
    """Turn raw user input into a valid guess, or raise ValueError."""
    stripped = text.strip()
    if not stripped:
        raise ValueError("no guess entered")
    try:
        value = int(stripped)
    except ValueError:
        raise ValueError("%r is not a whole number" % stripped)
    if value < low or value > high:
        raise ValueError("guess must be between %d and %d" % (low, high))
    return value


def next_guess(low, high):
    """Pick the midpoint of the remaining interval."""
    if low > high:
        raise ValueError("empty search range")
    return (low + high) // 2


def narrow(feedback, guess, low, high):
    """Shrink the search interval according to the feedback."""
    if feedback == 'Too high':
        return low, guess - 1
    elif feedback == 'Too low':
        return guess + 1, high
    return guess, guess


def play_auto(target, low=1, high=100):
    """Solve the game by bisection and return the list of (guess, feedback)."""
    history = []
    while low <= high:
        guess = next_guess(low, high)
        feedback = simulate_guess(target, guess)
        history.append((guess, feedback))
        if feedback == 'Correct!':
            break
        low, high = narrow(feedback, guess, low, high)
    return history


def format_round(number, guess, feedback):
    """Describe one played round in a single readable line."""
    if feedback == 'Correct!':
        return "Round %d: %d -> %s" % (number, guess, feedback)
    return "Round %d: %d -> %s, keep going" % (number, guess, feedback)


def main():
    target = 7
    for raw in [" 50 ", "7", "101", "abc", "5"]:
        try:
            guess = parse_guess(raw)
        except ValueError as exc:
            print("Rejected %r: %s" % (raw, exc))
            continue
        print("Manual guess %d -> %s" % (guess, simulate_guess(target, guess)))
    history = play_auto(target)
    for index, (guess, feedback) in enumerate(history, start=1):
        print(format_round(index, guess, feedback))
    if history and history[-1][1] == 'Correct!':
        print("Found %d in %d guesses" % (target, len(history)))
    else:
        print("Search failed for target %d" % target)


main()

