def simulate_stack(stack, operation, item=None):
    """Perform a single 'push' or 'pop' on the given stack (in place)."""
    if not isinstance(stack, list):
        raise TypeError("stack must be a list")
    if not isinstance(operation, str):
        raise TypeError("operation must be a string")

    op = operation.strip().lower()
    if op == "push":
        stack.append(item)
        return stack
    elif op == "pop":
        if not stack:
            return None
        return stack.pop()
    raise ValueError("unknown operation: " + operation)


def coerce_item(text):
    """Convert a token to int or float when possible, else keep the string."""
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return text


def parse_command(line):
    """Turn a non-empty command such as 'push 3' or 'pop' into (operation, item)."""
    parts = line.split()
    op = parts[0].lower()
    if op == "pop":
        if len(parts) > 1:
            raise ValueError("pop takes no argument")
        return ("pop", None)
    elif op == "push":
        if len(parts) != 2:
            raise ValueError("push needs exactly one item")
        return ("push", coerce_item(parts[1]))
    raise ValueError("unknown operation: " + op)


def run_script(stack, script):
    """Apply every command of a newline-separated script, collecting a report."""
    report = []
    for raw in script.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        operation, item = parse_command(line)
        result = simulate_stack(stack, operation, item)
        if operation == "push":
            report.append("stack is now " + repr(list(result)))
        elif result is None:
            report.append("pop from empty stack")
        else:
            report.append("popped " + repr(result))
    return report


def main():
    script = "push 1\npush 2\n# now empty it\npop\npop\npop\npush hello\n"
    stack = []
    for line in run_script(stack, script):
        print(line)
    print("final stack:", stack)


main()

