    op = parts[0].lower()
    if (op == "pop"):
        if (len(parts) > 1):
            raise ValueError("pop takes no argument")
        return ("pop", None)
    elif (op == "push"):
        if (len(parts) != 2):
            raise ValueError("push needs exactly one item")
        return ("push", coerce_item(parts[1]))
    raise ValueError("unknown operation: " + op)


def run_script(stack, script):
    """Apply every command of a newline-separated script, collecting a report."""
    report = []
    for raw in script.splitlines():
        line = raw.strip()
        if (not line or line.startswith("#")):
            continue
        operation, item = parse_command(line)
        result = simulate_stack(stack, operation, item)
        if (operation == "push"):
            report.append("stack is now " + repr(list(result)))
        elif (result is None):
            report.append("pop from empty stack")
        else:
            report.append("popped " + repr(result))
    return report


def main():
    script = "push 1\npush 2\n# now empty it\npop\npop\npop\npush hello\n"
    stack = []
    for line in run_script(stack, script):
        print(line)
    print("final stack:", stack)


