def _validate_point(p, name):
    if not isinstance(p, (tuple, list)):
        raise TypeError(f"{name} must be a tuple of two numbers")
    if len(p) != 2:
        raise ValueError(f"{name} must have exactly two coordinates")
    for value in p:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"{name} coordinates must be numeric")
    return float(p[0]), float(p[1])


def manhattan_distance(p1, p2):
    x1, y1 = _validate_point(p1, "p1")
    x2, y2 = _validate_point(p2, "p2")
    return abs(x1 - x2) + abs(y1 - y2)


def parse_point(text):
    cleaned = text.strip()
    while cleaned and cleaned[0] in "([":
        cleaned = cleaned[1:]
    while cleaned and cleaned[-1] in ")]":
        cleaned = cleaned[:-1]
    parts = [chunk for chunk in cleaned.replace(";", ",").split(",") if chunk.strip()]
    if len(parts) != 2:
        raise ValueError(f"cannot parse point from {text!r}")
    return tuple(float(chunk) for chunk in parts)


def format_distance(value):
    if value == int(value):
        return f"{value:.1f}"
    return f"{value:.4f}".rstrip("0")


def nearest_point(origin, candidates):
    best = None
    best_distance = None
    for candidate in candidates:
        distance = manhattan_distance(origin, candidate)
        if best_distance is None or distance < best_distance:
            best = candidate
            best_distance = distance
    if best is None:
        raise ValueError("candidates must not be empty")
    return best, best_distance


def report(pairs):
    lines = []
    for raw1, raw2 in pairs:
        first = parse_point(raw1)
        second = parse_point(raw2)
        distance = manhattan_distance(first, second)
        label = "same point" if distance == 0.0 else format_distance(distance)
        lines.append(f"{first} -> {second}: {label}")
    return "\n".join(lines)


