import secrets
import sys

MIN_LENGTH = 3
MAX_LENGTH = 12
DEFAULT_LENGTHS = (4, 6, 8)


def generate_pin(length):
    """Return a random numeric PIN of the requested length as a string."""
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an int")
    if length < MIN_LENGTH:
        raise ValueError("length must be at least %d" % MIN_LENGTH)
    if length > MAX_LENGTH:
        raise ValueError("length must be at most %d" % MAX_LENGTH)
    return "".join(str(secrets.randbelow(10)) for _ in range(length))


def has_run(pin, min_run=3):
    """True if the PIN contains an ascending or descending run of digits."""
    run = 1
    step = 0
    for prev, cur in zip(pin, pin[1:]):
        delta = int(cur) - int(prev)
        if delta == step and delta in (1, -1):
            run += 1
        elif delta in (1, -1):
            run = 2
            step = delta
        else:
            run = 1
            step = 0
        if run >= min_run:
            return True
    return False


def is_weak(pin):
    """A PIN is weak if it repeats one digit, has a long run or a short period."""
    if len(set(pin)) == 1:
        return True
    if has_run(pin):
        return True
    period = 2
    while period <= len(pin) // 2:
        if len(pin) % period == 0 and pin == pin[:period] * (len(pin) // period):
            return True
        period += 1
    return False


def generate_strong_pin(length, attempts=50):
    """Generate a PIN that does not look obviously guessable."""
    tries = 0
    while tries < attempts:
        pin = generate_pin(length)
        if not is_weak(pin):
            return pin
        tries += 1
    return generate_pin(length)


def parse_lengths(args):
    """Turn command line arguments into a list of PIN lengths."""
    lengths = []
    for arg in args:
        if not arg.isdigit():
            raise ValueError("not a length: %s" % arg)
        lengths.append(int(arg))
    if not lengths:
        return list(DEFAULT_LENGTHS)
    return lengths


def describe(pin):
    label = "weak" if is_weak(pin) else "ok"
    return "%s (%d digits, %s)" % (pin, len(pin), label)


def main(args):
    try:
        lengths = parse_lengths(args)
    except ValueError as err:
        print("error:", err)
        return 2
    for length in lengths:
        try:
            print(describe(generate_strong_pin(length)))
        except (TypeError, ValueError) as err:
            print("error:", err)
            return 1
    return 0


sys.exit(main(sys.argv[1:]))

