def count_characters(text):
    """Return a mapping of character -> number of occurrences in text."""
    counts = {}
    for ch in text:
        if ch not in counts:
            counts[ch] = 1
        else:
            counts[ch] += 1
    return counts


def least_frequent_char(text):
    """Return the first character of text with the smallest frequency."""
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    elif not text:
        raise ValueError('text must not be empty')
    counts = count_characters(text)
    best = None
    i = 0
    while i < len(text):
        ch = text[i]
        if best is None:
            best = ch
        elif counts[ch] < counts[best]:
            best = ch
        i += 1
    return best


def describe_char(ch):
    """Return a printable description of a single character."""
    if ch == ' ':
        return "' ' (space)"
    elif ch == '\t':
        return "'\\t' (tab)"
    elif ch == '\n':
        return "'\\n' (newline)"
    return "'%s'" % ch


def frequency_report(text):
    """Return report lines sorted by frequency, ties in order of appearance."""
    counts = count_characters(text)
    order = sorted(counts, key=lambda c: (counts[c], text.index(c)))
    lines = []
    for ch in order:
        lines.append('%-12s %d' % (describe_char(ch), counts[ch]))
    return lines


def main():
    samples = ['hello world', 'aabbc', 'mississippi', 42, '']
    limit = 4
    for sample in samples:
        try:
            answer = least_frequent_char(sample)
        except (TypeError, ValueError) as exc:
            print('skipping %r: %s' % (sample, exc))
            continue
        print('input: %r' % sample)
        print('least frequent: %s' % describe_char(answer))
        lines = frequency_report(sample)
        shown = 0
        while shown < len(lines) and shown < limit:
            print('  ' + lines[shown])
            shown += 1
        if shown < len(lines):
            print('  ... %d more' % (len(lines) - shown))
        print()


main()

