def is_divisible_by_3_and_5(number):
    """Return True when number is a multiple of both 3 and 5."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be an int")
    return number % 3 == 0 and number % 5 == 0


def parse_int(text):
    """Convert a user-supplied string into an int, or return None."""
    stripped = text.strip()
    if not stripped:
        return None
    sign = 1
    if stripped[0] in "+-":
        if stripped[0] == "-":
            sign = -1
        stripped = stripped[1:]
    if not stripped.isdigit():
        return None
    return sign * int(stripped)


def describe(number):
    """Build a human-readable verdict for a single number."""
    if is_divisible_by_3_and_5(number):
        return "{0} is divisible by both 3 and 5".format(number)
    elif number % 3 == 0:
        return "{0} is divisible by 3 only".format(number)
    elif number % 5 == 0:
        return "{0} is divisible by 5 only".format(number)
    return "{0} is divisible by neither 3 nor 5".format(number)


def multiples_up_to(limit):
    """Collect every value in 1..limit that is divisible by 3 and 5."""
    found = []
    value = 1
    while value <= limit:
        if is_divisible_by_3_and_5(value):
            found.append(value)
        value += 1
    return found


def report(raw_values):
    """Describe each raw input, skipping the ones that are not integers."""
    lines = []
    for raw in raw_values:
        number = parse_int(raw)
        if number is None:
            lines.append("{0!r} is not an integer".format(raw))
        else:
            lines.append(describe(number))
    return lines


def main():
    samples = ["15", "10", " -45 ", "9", "20", "0", "seven", ""]
    for line in report(samples):
        print(line)

    limit = 60
    hits = multiples_up_to(limit)
    print("Multiples of 15 up to {0}: {1}".format(limit, hits))


main()

