def _sort_rank(value):
    """Return a tuple that allows values of mixed types to be ordered."""
    if isinstance(value, (int, float)):
        return (0, float(value), "")
    elif isinstance(value, str):
        return (1, 0.0, value)
    return (2, 0.0, repr(value))


def validate_input(dict_list, key):
    """Raise a descriptive error if the arguments cannot be sorted."""
    if not isinstance(dict_list, list):
        raise TypeError("dict_list must be a list")
    if not isinstance(key, str):
        raise TypeError("key must be a string")
    for position, item in enumerate(dict_list):
        if not isinstance(item, dict):
            raise TypeError("element %d is not a dict" % position)
        if key not in item:
            raise KeyError("element %d has no key %r" % (position, key))


def sort_dicts_by_key(dict_list, key):
    validate_input(dict_list, key)
    return sorted(dict_list, key=lambda item: _sort_rank(item[key]))


def _cell(row, name):
    if name not in row:
        return ""
    value = row[name]
    if isinstance(value, float):
        return "%g" % value
    return str(value)


def format_table(dict_list, key):
    """Render the rows as a text table, with the sort key in the first column."""
    fields = [key]
    for row in dict_list:
        for name in row:
            if name not in fields:
                fields.append(name)
    widths = {name: len(name) for name in fields}
    for row in dict_list:
        for name in fields:
            text = _cell(row, name)
            if len(text) > widths[name]:
                widths[name] = len(text)
    lines = [" | ".join(name.ljust(widths[name]) for name in fields)]
    lines.append("-+-".join("-" * widths[name] for name in fields))
    for row in dict_list:
        lines.append(" | ".join(_cell(row, name).ljust(widths[name]) for name in fields))
    return "\n".join(lines)


def main():
    datasets = [
        ([{'name': 'B', 'age': 30}, {'name': 'A', 'age': 20}], 'age'),
        ([{'id': 2}, {'id': 1}], 'id'),
        ([{'city': 'Oslo', 'pop': 0.7}, {'city': 'Lima'}], 'pop'),
    ]
    for rows, key in datasets:
        print("sorting %d rows by %r" % (len(rows), key))
        try:
            ordered = sort_dicts_by_key(rows, key)
        except (TypeError, KeyError) as exc:
            print("  skipped: %s" % exc)
        else:
            print(format_table(ordered, key))


main()

