def as_text(key):
    if isinstance(key, str):
        return key
    return str(key)


def join_key(prefix, key, separator):
    if prefix == "":
        return as_text(key)
    return prefix + separator + as_text(key)


def unique_key(candidate, taken, separator):
    if candidate not in taken:
        return candidate
    suffix = 2
    while candidate + separator + str(suffix) in taken:
        suffix += 1
    return candidate + separator + str(suffix)


def check_inputs(nested_dict, separator):
    if not isinstance(nested_dict, dict):
        raise TypeError("nested_dict must be a dict")
    elif not isinstance(separator, str):
        raise TypeError("separator must be a str")
    elif separator == "":
        raise ValueError("separator must not be empty")
    for value in nested_dict.values():
        if not isinstance(value, dict):
            continue
        for inner_value in value.values():
            if isinstance(inner_value, dict):
                raise ValueError("only one level of nesting is supported")


def flatten_dict(nested_dict, separator):
    check_inputs(nested_dict, separator)
    flattened_dict = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            for inner_key, inner_value in value.items():
                combined = join_key(as_text(key), inner_key, separator)
                flattened_dict[unique_key(combined, flattened_dict, separator)] = inner_value
        else:
            flattened_dict[unique_key(as_text(key), flattened_dict, separator)] = value
    return flattened_dict


def depth_of(nested_dict):
    for value in nested_dict.values():
        if isinstance(value, dict):
            return 2
    return 1


def format_report(nested_dict, separator):
    flat = flatten_dict(nested_dict, separator)
    lines = ["depth=%d separator=%r" % (depth_of(nested_dict), separator)]
    for key, value in flat.items():
        if isinstance(value, float):
