HEX_DIGITS = "0123456789ABCDEF"


def digit_value(ch):
    upper = ch.upper()
    if upper not in HEX_DIGITS:
        raise ValueError("invalid hexadecimal digit: " + ch)
    return HEX_DIGITS.index(upper)


def normalize(hex_string):
    if not isinstance(hex_string, str):
        raise TypeError("hex_string must be a str")
    text = hex_string.strip()
    if text == "":
        raise ValueError("hex_string must not be empty")
    negative = False
    if text[0] == "-":
        negative = True
        text = text[1:]
    elif text[0] == "+":
        text = text[1:]
    if text[:2].lower() == "0x":
        text = text[2:]
    if text == "":
        raise ValueError("hex_string has no digits")
    return negative, text


def hex_to_decimal(hex_string):
    negative, digits = normalize(hex_string)
    decimal_num = 0
    for ch in digits:
        if ch == "_":
            continue
        decimal_num = decimal_num * 16 + digit_value(ch)
    if negative:
        decimal_num = -decimal_num
    return decimal_num


def decimal_to_hex(value):
    if value == 0:
        return "0"
    sign = ""
    if value < 0:
        sign = "-"
        value = -value
    out = ""
    while value > 0:
        out = HEX_DIGITS[value % 16] + out
        value //= 16
    return sign + out


def report(hex_string):
    try:
        value = hex_to_decimal(hex_string)
    except (TypeError, ValueError) as exc:
        return "{!r} -> error: {}".format(hex_string, exc)
    line = "{!r} -> {}".format(hex_string, value)
    canonical = decimal_to_hex(value)
    if canonical != normalize(hex_string)[1].replace("_", "").upper():
        line += " (canonical {})".format(canonical)
    return line


def main():
    samples = ["FF", "A", "0x1f", "  ff  ", "-2A", "00ff", "DE_AD", "", "G1", "0"]
    for sample in samples:
        print(report(sample))


