PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = set(PAIRS.values())
CLOSERS = set(PAIRS.keys())


def validate_input(s):
    """Return the string unchanged, raising if it is not a bracket-only string."""
    if not isinstance(s, str):
        raise TypeError('expected a string of brackets')
    for index, ch in enumerate(s):
        if ch not in OPENERS and ch not in CLOSERS:
            raise ValueError('illegal character %r at position %d' % (ch, index))
    return s


def is_brackets_balanced(s):
    """True when every bracket in s is closed by its own kind in the right order."""
    validate_input(s)
    stack = []
    for ch in s:
        if ch in OPENERS:
            stack.append(ch)
        elif not stack:
            return False
        elif stack.pop() != PAIRS[ch]:
            return False
    return not stack


def first_mismatch(s):
    """Index of the bracket that breaks the balance, or None if s is balanced."""
    stack = []
    for index, ch in enumerate(s):
        if ch in OPENERS:
            stack.append((ch, index))
        elif not stack:
            return index
        elif stack.pop()[0] != PAIRS[ch]:
            return index
    if stack:
        return stack[0][1]
    return None


def max_nesting_depth(s):
    """Deepest nesting level reached while scanning a balanced string."""
    depth = 0
    best = 0
    for ch in s:
        if ch in OPENERS:
            depth += 1
            if depth > best:
                best = depth
        else:
            depth -= 1
    return best


def describe(s):
    """Human readable one line verdict for a bracket string."""
    label = s if s else '<empty>'
    if is_brackets_balanced(s):
        return '%-12s balanced, depth %d' % (label, max_nesting_depth(s))
    spot = first_mismatch(s)
    return '%-12s unbalanced at position %d' % (label, spot)


def main():
    samples = ['()[]{}', '([{}])', '({[})', '', '[[[]]', ']']
    position = 0
    while position < len(samples):
        print(describe(samples[position]))
        position += 1
    bad = 'a(b)'
    try:
        is_brackets_balanced(bad)
    except ValueError as exc:
        print('%-12s rejected: %s' % (bad, exc))


if __name__ == '__main__':
    main()

