def calculate_range(numbers):
    """Return the difference between the largest and smallest value in numbers."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list of int/float")
    if len(numbers) == 0:
        raise ValueError("numbers must contain at least one value")
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("all elements must be int or float: %r" % (value,))
    data_range = max(numbers) - min(numbers)
    return data_range


def parse_numbers(text):
    """Turn a whitespace/comma separated string into a list of int/float."""
    cleaned = text.replace(",", " ").strip()
    if not cleaned:
        return []
    values = []
