import sys


def normalize_word(word):
    """Return the comparable form of a word: lowercase, letters only."""
    if not isinstance(word, str):
        raise TypeError("words must be strings, got %r" % (word,))
    cleaned = []
    for ch in word:
        if ch.isalpha():
            cleaned.append(ch.lower())
    return "".join(cleaned)


def anagram_key(word):
    """Return a canonical signature shared by all anagrams of `word`."""
    return "".join(sorted(normalize_word(word)))


def group_anagrams(words):
    """Group the given words so that each inner list holds mutual anagrams."""
    if words is None:
        raise TypeError("words must be a list of strings, not None")
    if isinstance(words, str):
        raise TypeError("words must be a list of strings, not a single string")
    buckets = {}
    order = []
    for word in words:
        key = anagram_key(word)
        if key not in buckets:
            buckets[key] = []
            order.append(key)
        buckets[key].append(word)
    return [buckets[key] for key in order]


def largest_group(anagram_groups):
    """Return the longest group, preferring the earliest one on ties."""
    best = []
    index = 0
    while index < len(anagram_groups):
        group = anagram_groups[index]
        if len(group) > len(best):
            best = group
        index += 1
    return best


def format_groups(anagram_groups):
    """Render groups as one line per group, words sorted for stable output."""
    lines = []
    for position, group in enumerate(anagram_groups, start=1):
        if len(group) == 1:
            label = "unique"
        elif len(group) == 2:
            label = "pair"
        else:
            label = "%d anagrams" % len(group)
        lines.append("%d. [%s] %s" % (position, label, ", ".join(sorted(group))))
    return "\n".join(lines)


def main(words):
    """Group the words given on the command line, or a small default sample."""
    if not words:
        words = ["eat", "tea", "tan", "ate", "nat", "bat"]
    groups = group_anagrams(words)
    print(format_groups(groups))
    biggest = largest_group(groups)
    if len(biggest) > 1:
        print("Largest group: %s" % ", ".join(sorted(biggest)))
    else:
        print("No two words in the input are anagrams.")


main(sys.argv[1:])

