def is_leap_year(year):
    if year % 4 != 0:
        return False
    elif year % 100 != 0:
        return True
    else:
        return year % 400 == 0


def days_in_month(year, month):
    if month == 2:
        return 29 if is_leap_year(year) else 28
    elif month in (4, 6, 9, 11):
        return 30
    else:
        return 31


def parse_date(date_str):
    if not isinstance(date_str, str):
        raise TypeError("date must be a string in 'YYYY-MM-DD' format")
    parts = date_str.strip().split('-')
    if len(parts) != 3:
        raise ValueError("malformed date: " + date_str)
    if len(parts[0]) != 4 or len(parts[1]) != 2 or len(parts[2]) != 2:
        raise ValueError("malformed date: " + date_str)
    for part in parts:
        if not part.isdigit():
            raise ValueError("malformed date: " + date_str)
    year, month, day = (int(p) for p in parts)
    if year < 1:
        raise ValueError("year out of range: " + date_str)
    if month < 1 or month > 12:
        raise ValueError("month out of range: " + date_str)
    if day < 1 or day > days_in_month(year, month):
        raise ValueError("day out of range: " + date_str)
    return year, month, day


def to_ordinal(year, month, day):
    total = 0
    y = 1
    while y < year:
        total += 366 if is_leap_year(y) else 365
        y += 1
    m = 1
    while m < month:
        total += days_in_month(year, m)
        m += 1
    return total + day


def days_between_dates(start_date_str, end_date_str):
    start = parse_date(start_date_str)
    end = parse_date(end_date_str)
    return to_ordinal(*end) - to_ordinal(*start)

