    if not spec:
        raise ValueError("empty dice notation")
    if spec.startswith("d"):
        spec = "1" + spec
    if "d" not in spec:
        raise ValueError("notation must contain 'd', e.g. 2d6")
    count_part, sides_part = spec.split("d", 1)
    if not count_part.isdigit() or not sides_part.isdigit():
        raise ValueError("notation must use non-negative integers, e.g. 3d8")
    return int(count_part), int(sides_part)


def tally(rolls):
    counts = {}
    for value in rolls:
        if value in counts:
            counts[value] += 1
        else:
            counts[value] = 1
    return counts


def describe(rolls):
    total = sum(rolls)
    if len(rolls) == 1:
        return "rolled {0}".format(total)
    return "rolled {0} for a total of {1}".format(rolls, total)


def histogram_lines(counts, width=30):
    peak = max(counts.values())
    lines = []
    for face in sorted(counts):
        hits = counts[face]
        bar_len = int(round(width * hits / peak))
        if bar_len < 1:
            bar_len = 1
        lines.append("{0:>3} | {1} {2}".format(face, "#" * bar_len, hits))
    return lines


def main():
    for notation in ("d6", "2d6", "3d20"):
        count, sides = parse_dice_notation(notation)
        rolls = roll_many(sides, count)
        print("{0}: {1}".format(notation, describe(rolls)))

    sides = 6
    trials = 6000
    counts = tally(roll_many(sides, trials))
    missing = [face for face in range(1, sides + 1) if face not in counts]
    if missing:
        print("faces never seen in {0} trials: {1}".format(trials, missing))
