    expected = trials / sides
    worst = max(abs(counts.get(f, 0) - expected) for f in range(1, sides + 1))
    if worst > expected * 0.25:
        print("warning: distribution looks skewed")
    elif worst > expected * 0.1:
        print("distribution is a little uneven but plausible")
    else:
        print("distribution looks fair")


main()

