        return False
    return True


def classify_point(px, py, x1, y1, x2, y2):
    """Return 'outside', 'border' or 'interior' for the given point."""
    x1, y1, x2, y2 = normalize_rectangle(x1, y1, x2, y2)
    if (not is_point_in_rectangle(px, py, x1, y1, x2, y2)):
        return "outside"
    elif (px == x1 or px == x2):
        return "border"
    elif (py == y1 or py == y2):
        return "border"
    return "interior"


def parse_point_line(line):
    """Parse 'px py' into a pair of ints, or return None for blank lines."""
    parts = line.replace(",", " ").split()
    if (not parts):
        return None
    if (len(parts) != 2):
        raise ValueError("expected two coordinates, got: " + line.strip())
    return int(parts[0]), int(parts[1])


def format_report(px, py, x1, y1, x2, y2):
    kind = classify_point(px, py, x1, y1, x2, y2)
    if (kind == "outside"):
        return "({0}, {1}) is outside".format(px, py)
    return "({0}, {1}) is inside [{2}]".format(px, py, kind)


def scan_points(lines, x1, y1, x2, y2):
    """Report every parsable point in lines against the rectangle."""
    reports = []
    index = 0
    while (index < len(lines)):
        point = parse_point_line(lines[index])
        index += 1
        if (point is None):
            continue
        px, py = point
        reports.append(format_report(px, py, x1, y1, x2, y2))
    return reports


def main():
    rect = (0, 0, 5, 5)
    samples = ["3 3", "", "6 2", "5 1", "0, 0", "2 5"]
    for line in scan_points(samples, *rect):
        print(line)


main()

