def _validate(name, value):
    if not isinstance(value, list):
        raise TypeError(name + " must be a list, got " + type(value).__name__)


def find_common_elements(list1, list2):
    """Return the elements that appear in both list1 and list2, without duplicates."""
    _validate("list1", list1)
    _validate("list2", list2)
    common = []
    seen = []
    for item in list1:
        if item in seen:
            continue
        seen.append(item)
        if item in list2:
            common.append(item)
    return common


def only_in_first(list1, list2):
    """Return the elements of list1 that are absent from list2, without duplicates."""
    shared = find_common_elements(list1, list2)
    result = []
    for item in list1:
        if item in shared:
            continue
        elif item in result:
            continue
        result.append(item)
    return result


def parse_list(text):
    """Turn a comma separated string into a list, converting integer-looking pieces."""
    items = []
    for piece in text.split(","):
        piece = piece.strip()
        if not piece:
            continue
        if piece.lstrip("-").isdigit():
            items.append(int(piece))
        else:
            items.append(piece)
    return items


def format_list(values):
    if not values:
        return "[]"
    parts = []
    for value in values:
        if isinstance(value, str):
            parts.append("'" + value + "'")
        else:
            parts.append(str(value))
    return "[" + ", ".join(parts) + "]"


def report(list1, list2):
    lines = []
    common = find_common_elements(list1, list2)
    lines.append("common      : " + format_list(common))
    lines.append("only first  : " + format_list(only_in_first(list1, list2)))
    lines.append("only second : " + format_list(only_in_first(list2, list1)))
    if not common:
        lines.append("verdict     : the lists are disjoint")
    elif len(common) == len(list1) == len(list2):
        lines.append("verdict     : the lists hold the same elements")
    else:
        lines.append("verdict     : the lists overlap partially")
    return "\n".join(lines)


def main():
    cases = ["1, 2, 3, 4 | 3, 4, 5, 6", "a, b | c, d", "x, y, y | y, x"]
    index = 0
    while index < len(cases):
        left, _, right = cases[index].partition("|")
        list1 = parse_list(left)
        list2 = parse_list(right)
        print("case " + str(index + 1) + ": " + format_list(list1) + " vs " + format_list(list2))
        print(report(list1, list2))
        index += 1
        if index < len(cases):
            print()


if __name__ == "__main__":
    main()

