def calculate_bmi(weight_kg, height_m):
    """Return the BMI for a weight in kilograms and a height in metres."""
    weight_kg = float(weight_kg)
    height_m = float(height_m)
    if weight_kg <= 0:
        raise ValueError("weight must be a positive number of kilograms")
    elif height_m <= 0:
        raise ValueError("height must be a positive number of metres")
    return round(weight_kg / (height_m * height_m), 2)


def classify_bmi(bmi):
    """Map a BMI value onto the usual WHO weight categories."""
    if bmi < 18.5:
        return "underweight"
    elif bmi < 25.0:
        return "normal weight"
    elif bmi < 30.0:
        return "overweight"
    return "obese"


def parse_height(text):
    """Accept a height given either in metres (1.75) or in centimetres (175)."""
    value = float(text)
    if value <= 0:
        raise ValueError("height must be positive")
    elif value > 3.0:
        value = value / 100.0
    return value


def describe(weight_kg, height_m):
    """Build a one line report for a single person."""
    bmi = calculate_bmi(weight_kg, height_m)
    return "{:.1f} kg / {:.2f} m -> BMI {:.2f} ({})".format(
        weight_kg, height_m, bmi, classify_bmi(bmi)
    )


def healthy_weight_range(height_m):
    """Return the weight interval that keeps the BMI inside the normal band."""
    if height_m <= 0:
        raise ValueError("height must be positive")
    low = 18.5 * height_m * height_m
    high = 24.9 * height_m * height_m
    return round(low, 1), round(high, 1)


def read_person(prompt_weight, prompt_height):
    """Ask the user for a weight and a height until both can be used."""
    while True:
        try:
            weight = float(input(prompt_weight))
            height = parse_height(input(prompt_height))
        except ValueError as err:
            print("Invalid input:", err)
            continue
        if weight > 0:
            return weight, height
        print("Invalid input: weight must be positive")


def main():
    for weight, height in [(70, 1.75), (90, 1.80)]:
        print(describe(weight, height))

    answer = input("Enter your own measurements? [y/N] ").strip().lower()
    if answer not in ["y", "yes"]:
        return
    weight, height = read_person("Weight in kg: ", "Height in m or cm: ")
    print(describe(weight, height))
    low, high = healthy_weight_range(height)
    print("Healthy range for your height: {} kg - {} kg".format(low, high))
    if weight < low:
        print("You are {:.1f} kg below the healthy range.".format(low - weight))
    elif weight > high:
        print("You are {:.1f} kg above the healthy range.".format(weight - high))
    else:
        print("Your weight is inside the healthy range.")


main()

