import sys


def binary_to_decimal(binary_string):
    """Convert a binary string such as '1011' into its decimal value."""
    if not isinstance(binary_string, str):
        raise TypeError("binary_to_decimal expects a string")
    cleaned = binary_string.strip()
    if cleaned.startswith("0b") or cleaned.startswith("0B"):
        cleaned = cleaned[2:]
    if cleaned == "":
        raise ValueError("empty binary string")
    value = 0
    for digit in cleaned:
        if digit == "0":
            value = value * 2
        elif digit == "1":
            value = value * 2 + 1
        else:
            raise ValueError("invalid binary digit: " + digit)
    return value


def decimal_to_binary(number):
    """Render a non-negative integer as its canonical binary string."""
    if number < 0:
        raise ValueError("negative numbers are not supported")
    if number == 0:
        return "0"
    digits = []
    while number > 0:
        digits.append(str(number % 2))
        number //= 2
    digits.reverse()
    return "".join(digits)


def group_bits(binary_string, size=4):
    """Pad on the left and group the bits for readable output."""
    if size < 1:
        raise ValueError("group size must be positive")
    bits = binary_string.strip()
    while len(bits) % size != 0:
        bits = "0" + bits
    return " ".join(bits[i:i + size] for i in range(0, len(bits), size))


def describe(binary_string):
    """Return a one-line report about a single binary literal."""
    try:
        value = binary_to_decimal(binary_string)
    except (TypeError, ValueError) as exc:
        return "{!r}: error - {}".format(binary_string, exc)
    grouped = group_bits(decimal_to_binary(value))
    if value == 0:
        note = "zero"
    elif value % 2 == 0:
        note = "even"
    else:
        note = "odd"
    return "{:>12} -> {:<6} [{}] {}".format(binary_string, value, grouped, note)


def main(argv):
    literals = argv[1:]
    if not literals:
        literals = [line.strip() for line in sys.stdin if line.strip()]
    for literal in literals:
        print(describe(literal))


main(sys.argv)

