        value = binary_to_decimal(binary_string)
    except (TypeError, ValueError) as exc:
        return "{!r}: error - {}".format(binary_string, exc)
    grouped = group_bits(decimal_to_binary(value))
    if (value == 0):
        note = "zero"
    elif (value % 2 == 0):
        note = "even"
    else:
        note = "odd"
    return "{:>12} -> {:<6} [{}] {}".format(binary_string, value, grouped, note)


def main(argv):
    literals = argv[1:]
    if (not literals):
        literals = [line.strip() for line in sys.stdin if line.strip()]
    for literal in literals:
        print(describe(literal))


main(sys.argv)

