import os
import sys


def append_to_file(filepath, content):
    """Append content to filepath. Return True on success, False on failure."""
    try:
        with open(filepath, "a", encoding="utf-8") as handle:
            handle.write(content)
    except OSError:
        return False
    return True


def read_lines(filepath):
    """Return the lines of filepath, or an empty list if it cannot be read."""
    try:
        with open(filepath, "r", encoding="utf-8") as handle:
            return handle.read().splitlines()
    except OSError:
        return []


def append_log_entry(filepath, message):
    """Append message as one line, adding a newline only when needed."""
    text = message
    if not text.endswith("\n"):
        text = text + "\n"
    return append_to_file(filepath, text)


def append_many(filepath, messages):
    """Append several messages, stopping at the first failure."""
    written = 0
    index = 0
    while index < len(messages):
        if not append_log_entry(filepath, messages[index]):
            break
        written += 1
        index += 1
    return written


def describe(filepath):
    """Return a short human readable description of filepath's state."""
    if not os.path.exists(filepath):
        return filepath + ": missing"
    elif os.path.isdir(filepath):
        return filepath + ": directory"
    size = os.path.getsize(filepath)
    lines = len(read_lines(filepath))
    return "%s: %d bytes, %d line(s)" % (filepath, size, lines)


def main(argv):
    target = "test.txt"
    if len(argv) > 1:
        target = argv[1]
    messages = argv[2:]
    if not messages:
        messages = ["Hello", "second entry", "third entry"]

    written = append_many(target, messages)
    print(describe(target))
    if written == len(messages):
        print("appended %d entry/entries to %s" % (written, target))
        return 0
    elif written > 0:
        print("partial write: %d of %d entries" % (written, len(messages)))
    else:
        print("could not write to " + target)
    return 1


sys.exit(main(sys.argv))

