class BankAccount:
    def __init__(self, initial_balance):
        self.balance = initial_balance

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            return True
        return False

    def withdraw(self, amount):
        if amount > 0:
            if self.balance >= amount:
                self.balance -= amount
                return True
            elif self.balance < amount:
                return False
        elif amount <= 0:
            return False
        return False # Should not be reached but good practice

    def get_balance(self):
        return self.balance

    def is_positive_balance(self):
        if self.balance > 0:
            return True
        else:
            return False

    def has_sufficient_funds(self, amount):
        if self.balance >= amount:
            return True
        else:
            return False

    def can_deposit_zero(self, amount):
        if amount == 0:
            return False
        else:
            return True

    def will_be_negative_after_withdrawal(self, amount):
        if self.balance - amount < 0:
            return True
        return False

