def validate_event(event):
    if not isinstance(event, tuple):
        raise TypeError("event must be a tuple of (start_time, end_time)")
    if len(event) != 2:
        raise ValueError("event must have exactly two elements")
    start, end = event
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError("event times must be integers")
    if start > end:
        raise ValueError("event start must not be after its end")
    return start, end


def check_event_overlap(event1, event2):
    start1, end1 = validate_event(event1)
    start2, end2 = validate_event(event2)
    if end1 <= start2:
        return False
    elif end2 <= start1:
        return False
    return True


def merge_events(event1, event2):
    start = min(event1[0], event2[0])
    end = max(event1[1], event2[1])
    return start, end


def find_conflicts(schedule):
    conflicts = []
    index = 0
    while index < len(schedule):
        other = index + 1
        while other < len(schedule):
            if check_event_overlap(schedule[index], schedule[other]):
                conflicts.append((index, other))
            other += 1
        index += 1
    return conflicts


def format_time(minutes):
    if minutes < 0:
        raise ValueError("time must not be negative")
    hours = minutes // 60 % 24
    return "{:02d}:{:02d}".format(hours, minutes % 60)


def describe_event(event):
    start, end = validate_event(event)
    if start == end:
        return "{} (instant)".format(format_time(start))
    return "{}-{}".format(format_time(start), format_time(end))


def report(schedule):
    lines = ["Schedule:"]
    for event in schedule:
        lines.append("  " + describe_event(event))
    conflicts = find_conflicts(schedule)
    if not conflicts:
        lines.append("No conflicts found.")
        return "\n".join(lines)
    lines.append("Conflicts:")
    for i, j in conflicts:
        merged = merge_events(schedule[i], schedule[j])
        lines.append("  {} overlaps {} -> busy {}".format(
            describe_event(schedule[i]), describe_event(schedule[j]),
            describe_event(merged)))
    return "\n".join(lines)


def main():
    schedule = [(540, 600), (570, 630), (660, 660), (700, 780)]
    print(report(schedule))


main()

