def normalize(word):
    if not isinstance(word, str):
        raise TypeError("words must be strings, got %r" % (word,))
    cleaned = word.strip()
    while cleaned and not cleaned[0].isalnum():
        cleaned = cleaned[1:]
    while cleaned and not cleaned[-1].isalnum():
        cleaned = cleaned[:-1]
    return cleaned.lower()


def word_frequency(words):
    counts = {}
    if words is None:
        return counts
    for word in words:
        key = normalize(word)
        if not key:
            continue
        elif key in counts:
            counts[key] += 1
        else:
            counts[key] = 1
    return counts


def tokenize(text):
    tokens = []
    current = ""
    for char in text:
        if char.isalnum() or char == "'":
            current += char
        elif current:
            tokens.append(current)
            current = ""
    if current:
        tokens.append(current)
    return tokens


def most_common(counts, limit=3):
    if limit < 1:
        return []
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:limit]


def format_report(counts, limit=3):
    if not counts:
        return "no words counted"
    lines = []
    total = sum(counts.values())
    for word, hits in most_common(counts, limit):
        share = 100.0 * hits / total
        lines.append("%-10s %4d  %5.1f%%" % (word, hits, share))
    remaining = len(counts) - len(lines)
    if remaining > 0:
        lines.append("... and %d more unique word(s)" % remaining)
    return "\n".join(lines)


def main():
    samples = [
        ['Apple', 'banana', 'apple', 'Orange'],
        [],
        tokenize("The rain in Spain stays mainly in the plain; the rain!"),
    ]
    for index, sample in enumerate(samples, 1):
        counts = word_frequency(sample)
        print("sample %d: %r" % (index, counts))
        print(format_report(counts))
        print("-" * 30)


