ABSOLUTE_ZERO = {'C': -273.15, 'F': -459.67, 'K': 0.0}


def normalize_unit(unit):
    cleaned = unit.strip().upper()
    if cleaned not in ABSOLUTE_ZERO:
        raise ValueError("unknown temperature unit: " + unit)
    return cleaned


def to_celsius(value, unit):
    if unit == 'C':
        return float(value)
    elif unit == 'F':
        return (value - 32.0) * 5.0 / 9.0
    return value - 273.15


def from_celsius(celsius, unit):
    if unit == 'C':
        return float(celsius)
    elif unit == 'F':
        return celsius * 9.0 / 5.0 + 32.0
    return celsius + 273.15


def convert_temperature(value, unit_from, unit_to):
    source = normalize_unit(unit_from)
    target = normalize_unit(unit_to)
    if source == target:
        return float(value)
    return from_celsius(to_celsius(value, source), target)


def is_below_absolute_zero(value, unit):
    return value < ABSOLUTE_ZERO[normalize_unit(unit)]


def format_temperature(value, unit):
    symbol = normalize_unit(unit)
    rounded = round(value, 2)
    if rounded == int(rounded):
        text = str(int(rounded))
    else:
        text = "{0:.2f}".format(rounded)
    if symbol == 'K':
        return text + " K"
    return text + "\u00b0" + symbol


def conversion_table(value, unit_from):
    source = normalize_unit(unit_from)
    rows = []
    for target in ('C', 'F', 'K'):
        if target == source:
            continue
        rows.append((target, convert_temperature(value, source, target)))
    return rows


def main():
    samples = [(0.0, 'C'), (273.15, 'K'), (98.6, 'F'), (-500.0, 'F')]
    index = 0
    while index < len(samples):
        value, unit = samples[index]
        index += 1
        if is_below_absolute_zero(value, unit):
            print(format_temperature(value, unit) + " is below absolute zero")
            continue
        print(format_temperature(value, unit) + ":")
        for target, converted in conversion_table(value, unit):
            print("  -> " + format_temperature(converted, target))


main()

