def generate_permutations(lst):
    """Return a list of all orderings of the elements in lst."""
    if (not isinstance(lst, list)):
        raise TypeError("generate_permutations expects a list")
    if (len(lst) <= 1):
        return [list(lst)]
    result = []
    for index in range(len(lst)):
        head = lst[index]
        rest = lst[:index] + lst[index + 1:]
        for tail in generate_permutations(rest):
            result.append([head] + tail)
    return result


def count_permutations(n):
    """Number of permutations of n distinct items, computed iteratively."""
    if (n < 0):
        raise ValueError("n must be non-negative")
    total = 1
    while (n > 1):
        total *= n
        n -= 1
    return total


def unique_permutations(lst):
    """Permutations with duplicate orderings removed, original order kept."""
    seen = set()
    unique = []
    for perm in generate_permutations(lst):
        key = tuple(repr(item) for item in perm)
        if (key in seen):
            continue
        seen.add(key)
        unique.append(perm)
    return unique


def format_permutations(perms, limit=None):
    """Render permutations one per line, optionally truncating the output."""
    lines = []
    shown = 0
    for perm in perms:
        if (limit is not None and shown >= limit):
            lines.append("... and %d more" % (len(perms) - shown))
            break
        lines.append(" ".join(str(item) for item in perm))
        shown += 1
    return "\n".join(lines)


def describe(lst, limit=None):
    """Build a short report about the permutations of lst."""
    uniques = unique_permutations(lst)
    total = count_permutations(len(lst))
    header = "input %r -> %d permutations" % (lst, total)
    if (len(uniques) < total):
        header += " (%d distinct)" % len(uniques)
    return header + "\n" + format_permutations(uniques, limit)


def main():
    samples = [[1, 2], ['a'], [], [1, 2, 3], ['x', 'x', 'y'], [1, 2, 3, 4]]
    for sample in samples:
        cap = None
        if (len(sample) > 3):
            cap = 4
        print(describe(sample, cap))
        print("-" * 30)


main()

