def remove_duplicates_unordered(items):
    """Return a new list containing each distinct element of `items` exactly once."""
    if not isinstance(items, list):
        raise TypeError("remove_duplicates_unordered() requires a list")
    seen = set()
    unhashable = []
    result = []
    for item in items:
        try:
            if item in seen:
                continue
            seen.add(item)
        except TypeError:
            if item in unhashable:
                continue
            unhashable.append(item)
        result.append(item)
    return result


def duplicate_counts(items):
    """Map each repeated element to how many extra copies it has."""
    counts = {}
    for item in remove_duplicates_unordered(items):
        extra = items.count(item) - 1
        if extra > 0:
            counts[repr(item)] = extra
    return counts


def sorted_if_possible(items):
    """Sort a list of unique elements when the elements are mutually comparable."""
    try:
        return sorted(items)
    except TypeError:
        return list(items)


def format_report(items):
    """Build a short human readable summary of the de-duplication of `items`."""
    unique = remove_duplicates_unordered(items)
    removed = len(items) - len(unique)
    lines = ["input : " + repr(items)]
    lines.append("unique: " + repr(sorted_if_possible(unique)))
    if removed == 0:
        lines.append("no duplicates found")
        return "\n".join(lines)
    if removed == 1:
        lines.append("removed 1 duplicate element")
    else:
        lines.append("removed %d duplicate elements" % removed)
    for key, extra in duplicate_counts(items).items():
        lines.append("  %s appeared %d extra time(s)" % (key, extra))
    return "\n".join(lines)


def main():
    samples = [
        [1, 2, 2, 3, 1, 4],
        ['a', 'b', 'a', 'c'],
        [],
        [[1], [1], [2], 3, 3],
    ]
    index = 0
    while index < len(samples):
        if index > 0:
            print()
        print(format_report(samples[index]))
        index += 1


