def calculate_average(numbers):
    """Return the mean of a list of numbers, or 0.0 for an empty list."""
    if not numbers:
        return 0.0
    total = 0.0
    for value in numbers:
        total += value
    return total / len(numbers)


def parse_numbers(text):
    """Turn a comma or whitespace separated string into a list of floats."""
    cleaned = text.replace(",", " ")
    values = []
    for token in cleaned.split():
        try:
            values.append(float(token))
        except ValueError:
            raise ValueError("not a number: " + token)
    return values


def validate(numbers):
    """Raise for input that cannot be averaged meaningfully."""
    if not isinstance(numbers, list):
        raise TypeError("expected a list of numbers")
    index = 0
    while index < len(numbers):
        value = numbers[index]
        if isinstance(value, bool):
            raise TypeError("booleans are not numbers")
        elif not isinstance(value, (int, float)):
            raise TypeError("bad element at position %d" % index)
        elif value != value:
            raise ValueError("NaN at position %d" % index)
        index += 1
    return numbers


def format_average(numbers):
    """Describe the average of a list in a short human readable line."""
    validate(numbers)
    average = calculate_average(numbers)
    if not numbers:
        return "no values -> 0.0"
    label = "values" if len(numbers) > 1 else "value"
    return "%d %s -> %.4g" % (len(numbers), label, average)


def spread(numbers):
    """Return how far the extremes lie from the average."""
    validate(numbers)
    if not numbers:
        return 0.0, 0.0
    average = calculate_average(numbers)
    return average - min(numbers), max(numbers) - average


def main():
    samples = ["1 2 3 4 5", "10, 20", "", "-3 7 7.5"]
    for text in samples:
        numbers = parse_numbers(text)
        print(format_average(numbers))
        low, high = spread(numbers)
        if low == 0.0 and high == 0.0:
            print("  spread: none")
        elif low > high:
            print("  spread: skewed low by %.4g" % (low - high))
        elif high > low:
            print("  spread: skewed high by %.4g" % (high - low))
        else:
            print("  spread: balanced at %.4g" % low)


main()

