def is_binary_string(text):
    if not text:
        return False
    for ch in text:
        if ch != '0' and ch != '1':
            return False
    return True


def binary_to_gray(binary):
    if not is_binary_string(binary):
        raise ValueError('not a valid binary string: %r' % binary)
    gray = binary[0]
    index = 1
    while index < len(binary):
        if binary[index] == binary[index - 1]:
            gray += '0'
        else:
            gray += '1'
        index += 1
    return gray


def gray_to_binary(gray):
    if not is_binary_string(gray):
        raise ValueError('not a valid Gray code string: %r' % gray)
    binary = gray[0]
    index = 1
    while index < len(gray):
        if gray[index] == '0':
            binary += binary[index - 1]
        elif binary[index - 1] == '1':
            binary += '0'
        else:
            binary += '1'
        index += 1
    return binary


def normalize(text, width):
    stripped = text.strip()
    if len(stripped) >= width:
        return stripped
    return '0' * (width - len(stripped)) + stripped


def gray_sequence(bits):
    if bits < 1:
        raise ValueError('bits must be positive')
    codes = []
    for value in range(2 ** bits):
        pattern = normalize(format(value, 'b'), bits)
        codes.append(binary_to_gray(pattern))
    return codes


def main():
    samples = ['000', '1011', '1', '0', '11110000', '101010']
    width = 0
    for sample in samples:
        if len(sample) > width:
            width = len(sample)
    for sample in samples:
        padded = normalize(sample, width)
        print('%s -> %s' % (padded, binary_to_gray(padded)))
    codes = gray_sequence(3)
    print('3-bit Gray sequence: %s' % ' '.join(codes))
    for code in codes:
        print('%s decodes back to %s' % (code, gray_to_binary(code)))


main()

