import random


def validate_flips(flips):
    if not isinstance(flips, str):
        raise TypeError("flips must be a string")
    cleaned = flips.strip().upper()
    for index, symbol in enumerate(cleaned):
        if symbol not in "HT":
            raise ValueError("invalid flip %r at position %d" % (symbol, index))
    return cleaned


def longest_coin_flip_streak(flips):
    sequence = validate_flips(flips)
    if not sequence:
        return 0
    best = 1
    current = 1
    position = 1
    while position < len(sequence):
        if sequence[position] == sequence[position - 1]:
            current += 1
        else:
            current = 1
        if current > best:
            best = current
        position += 1
    return best


def streak_runs(flips):
    sequence = validate_flips(flips)
    runs = []
    for symbol in sequence:
        if runs and runs[-1][0] == symbol:
            runs[-1][1] += 1
        else:
            runs.append([symbol, 1])
    return [(symbol, length) for symbol, length in runs]


def simulate_flips(count, seed=None):
    if count < 0:
        raise ValueError("count must be non-negative")
    rng = random.Random(seed)
    return "".join(rng.choice("HT") for _ in range(count))


def describe_streaks(flips):
    runs = streak_runs(flips)
    if not runs:
        return "no flips recorded"
    longest = longest_coin_flip_streak(flips)
    heads = sum(length for symbol, length in runs if symbol == "H")
    tails = sum(length for symbol, length in runs if symbol == "T")
    parts = ["%s x%d" % (symbol, length) for symbol, length in runs]
    summary = "runs: " + ", ".join(parts)
    if heads > tails:
        verdict = "heads lead"
    elif tails > heads:
        verdict = "tails lead"
    else:
        verdict = "even split"
    return "%s | longest streak: %d | %s" % (summary, longest, verdict)


def main():
    samples = ["HHHTTTHHHH", "HTHTHT", "", simulate_flips(20, seed=7)]
    for sample in samples:
        label = sample if sample else "(empty)"
        print("%-22s -> %s" % (label, describe_streaks(sample)))


main()

