import sys

MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
MONTH_NAMES = ("January", "February", "March", "April", "May", "June", "July",
               "August", "September", "October", "November", "December")


def is_leap_year(year):
    if year % 400 == 0:
        return True
    elif year % 100 == 0:
        return False
    elif year % 4 == 0:
        return True
    return False


def count_days_in_month(year, month):
    if not isinstance(year, int) or not isinstance(month, int):
        raise TypeError("year and month must be integers")
    if month < 1 or month > 12:
        raise ValueError("month must be in 1..12")
    if month == 2 and is_leap_year(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def days_in_year(year):
    total = 0
    month = 1
    while month <= 12:
        total += count_days_in_month(year, month)
        month += 1
    return total


def parse_arguments(argv):
    if len(argv) == 1:
        raise ValueError("usage: prog YEAR [MONTH]")
    elif len(argv) > 3:
        raise ValueError("too many arguments")
    year = int(argv[1])
    if len(argv) == 3:
        return year, int(argv[2])
    return year, None


def format_month(year, month):
    days = count_days_in_month(year, month)
    return "%s %d: %d days" % (MONTH_NAMES[month - 1], year, days)


def report(year, month=None):
    lines = []
    if month is not None:
        lines.append(format_month(year, month))
    else:
        current = 1
        while current <= 12:
            lines.append(format_month(year, current))
            current += 1
        lines.append("Total for %d: %d days" % (year, days_in_year(year)))
    return "\n".join(lines)


def main(argv):
    try:
        year, month = parse_arguments(argv)
    except ValueError as exc:
        print("error: %s" % exc)
        return 2
    print(report(year, month))
    if month is None and is_leap_year(year):
        print("%d is a leap year." % year)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

